INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ad6d468-7ff1-4a7b-8b24-a27d70d00ed4', '帝京篇十首 一', '帝京篇十首 一', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["秦川雄帝宅，函谷壯皇居。","綺殿千尋起，離宮百雉餘。","連甍遙接漢，飛觀迥凌虛。","雲日隱層闕，風煙出綺疎。"]', '["秦川雄帝宅，函谷壯皇居。","綺殿千尋起，離宮百雉餘。","連甍遙接漢，飞观迥凌虛。","云日隐層闕，风煙出綺疎。"]', '诗', 'shi', '', NULL, '帝京篇十首 一 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13e72581-968b-457f-b381-a3b7d95b8b7c', '帝京篇十首 二', '帝京篇十首 二', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["巖廊罷機務，崇文聊駐輦。","玉匣啓龍圖，金繩披鳳篆。","韋編斷仍續，縹帙舒還卷。","對此乃淹留，欹案觀墳典。"]', '["巖廊罷機務，崇文聊駐輦。","玉匣啓龙圖，金繩披鳳篆。","韋編斷仍續，縹帙舒還卷。","对此乃淹留，欹案观墳典。"]', '诗', 'shi', '', NULL, '帝京篇十首 二 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7ff247d-a11c-4ca9-a22f-ca420b8c537c', '帝京篇十首 三', '帝京篇十首 三', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["移步出詞林，停輿欣武宴。","琱弓寫明月，駿馬疑流電。","驚雁落虛弦，啼猿悲急箭。","閱賞誠多美，於茲乃忘倦。"]', '["移步出词林，停輿欣武宴。","琱弓寫明月，駿马疑流電。","驚雁落虛弦，啼猿悲急箭。","閱賞誠多美，於茲乃忘倦。"]', '诗', 'shi', '', NULL, '帝京篇十首 三 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa374b2b-c196-4362-b4ad-8931fc9a8860', '帝京篇十首 四', '帝京篇十首 四', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["鳴笳臨樂館，眺聽歡芳節。","急管韻朱絃，清歌凝白雪。","彩鳳肅來儀，玄鶴紛成列。","去茲鄭衛聲，雅音方可悅。"]', '["鳴笳臨乐館，眺听歡芳節。","急管韻朱絃，清歌凝白雪。","彩鳳肅来儀，玄鹤紛成列。","去茲鄭衛声，雅音方可悅。"]', '诗', 'shi', '', NULL, '帝京篇十首 四 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86952cb3-b622-4398-a56a-01dd39f6c6ec', '帝京篇十首 五', '帝京篇十首 五', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["芳辰追逸趣，禁苑信多奇。","橋形通漢上，峰勢接雲危。","煙霞交隱映，花鳥自參差。","何如肆轍跡？萬里賞瑤池。"]', '["芳辰追逸趣，禁苑信多奇。","橋形通漢上，峰勢接云危。","煙霞交隐映，花鸟自參差。","何如肆轍跡？万里賞瑤池。"]', '诗', 'shi', '', NULL, '帝京篇十首 五 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90bcc00c-bcdb-424e-947b-cf108c47416b', '帝京篇十首 六', '帝京篇十首 六', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["飛蓋去芳園，蘭橈遊翠渚。","萍間日彩亂，荷處香風舉。","桂楫滿中川，弦歌振長嶼。","豈必汾河曲，方爲歡宴所。"]', '["飞蓋去芳园，蘭橈游翠渚。","萍间日彩亂，荷处香风舉。","桂楫满中川，弦歌振长嶼。","豈必汾河曲，方爲歡宴所。"]', '诗', 'shi', '', NULL, '帝京篇十首 六 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('621207da-c9ba-4f95-b637-a6bef91b1411', '帝京篇十首 七', '帝京篇十首 七', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["落日雙闕昏，回輿九重暮。","長煙散初碧，皎月澄輕素。","搴幌翫琴書，開軒引雲霧。","斜漢耿層閣，清風搖玉樹。"]', '["落日雙闕昏，回輿九重暮。","长煙散初碧，皎月澄轻素。","搴幌翫琴书，开軒引云霧。","斜漢耿層閣，清风搖玉樹。"]', '诗', 'shi', '', NULL, '帝京篇十首 七 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ed3f92a-d1d2-46ff-ae2c-1e58676a38a7', '帝京篇十首 八', '帝京篇十首 八', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["歡樂難再逢，芳辰良可惜。","玉酒泛雲罍，蘭殽陳綺席。","千鍾合堯禹，百獸諧金石。","得志重寸陰，忘懷輕尺璧。"]', '["歡乐难再逢，芳辰良可惜。","玉酒泛云罍，蘭殽陳綺席。","千鍾合堯禹，百獸諧金石。","得志重寸陰，忘懷轻尺璧。"]', '诗', 'shi', '', NULL, '帝京篇十首 八 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b6731ea-1ac2-4ed5-88bf-1d7da232fb0b', '帝京篇十首 九', '帝京篇十首 九', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["建章歡賞夕，二八盡妖妍。","羅綺昭陽殿，芬芳玳瑁筵。","珮移星正動，扇掩月初圓。","無勞上懸圃，即此對神仙。"]', '["建章歡賞夕，二八尽妖妍。","羅綺昭陽殿，芬芳玳瑁筵。","珮移星正动，扇掩月初圓。","無勞上懸圃，即此对神仙。"]', '诗', 'shi', '', NULL, '帝京篇十首 九 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b51924c-4325-4bc7-8134-1217dcbb2585', '帝京篇十首 十', '帝京篇十首 十', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["以茲遊觀極，悠然獨長想。","披卷覽前蹤，撫躬尋既往。","望古茅茨約，瞻今蘭殿廣。","人道惡高危，虛心戒盈蕩。","奉天竭誠敬，臨民思惠養。","納善察忠諫，明科慎刑賞。","六五誠難繼，四三非易仰。","廣待淳化敷，方嗣云亭響。"]', '["以茲游观極，悠然独长想。","披卷覽前蹤，撫躬尋既往。","望古茅茨約，瞻今蘭殿廣。","人道惡高危，虛心戒盈蕩。","奉天竭誠敬，臨民思惠養。","納善察忠諫，明科慎刑賞。","六五誠难繼，四三非易仰。","廣待淳化敷，方嗣云亭响。"]', '诗', 'shi', '', NULL, '帝京篇十首 十 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84b9a130-8145-4902-aac7-5779c17e3fef', '飲馬長城窟行', '饮马长城窟行', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["塞外悲風切，交河冰已結。","瀚海百重波，陰山千里雪。","迥戍危烽火，層巒引高節。","悠悠卷斾旌，飲馬出長城。","寒沙連騎跡，朔吹斷邊聲。","胡塵清玉塞，羌笛韻金鉦。","絕漠干戈戢，車徒振原隰。","都尉反龍堆，將軍旋馬邑。","揚麾氛霧靜，紀石功名立。","荒裔一戎衣，靈臺凱歌入。"]', '["塞外悲风切，交河冰已結。","瀚海百重波，陰山千里雪。","迥戍危烽火，層巒引高節。","悠悠卷斾旌，饮马出长城。","寒沙連騎跡，朔吹斷邊声。","胡塵清玉塞，羌笛韻金鉦。","絕漠干戈戢，车徒振原隰。","都尉反龙堆，將軍旋马邑。","揚麾氛霧静，紀石功名立。","荒裔一戎衣，靈台凱歌入。"]', '诗', 'shi', '', NULL, '飲馬長城窟行 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('786e30bf-b8a8-4067-a51c-1a5b522ed71d', '執契靜三邊', '執契静三邊', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["執契靜三邊，持衡臨萬姓。","玉彩輝關燭，金華流日鏡。","無爲宇宙清，有美璇璣正。","皎佩星連景，飄衣雲結慶。","戢武耀七德，昇文輝九功。","煙波澄舊碧，塵火息前紅。","霜野韜蓮劒，關城罷月弓。","錢綴榆天合，新城柳塞空。","花銷蔥嶺雪，縠盡流沙霧。","秋駕轉兢懷，春冰彌軫慮。","書絕龍庭羽，烽休鳳穴戍。","衣宵寢二難，食旰餐三懼。","翦暴興先廢，除兇存昔亡。","圓蓋歸天壤，方輿入地荒。","孔海池京邑，雙河沼帝鄉。","循躬思勵己，撫俗媿時康。","元首佇鹽梅，股肱惟輔弼。","羽賢崆嶺四，翼聖襄城七。","澆俗庶反淳，替文聊就質。","已知隆至道，共歡區宇一。"]', '["執契静三邊，持衡臨万姓。","玉彩輝关燭，金华流日镜。","無爲宇宙清，有美璇璣正。","皎佩星連景，飄衣云結慶。","戢武耀七德，昇文輝九功。","煙波澄旧碧，塵火息前紅。","霜野韜蓮劒，关城罷月弓。","錢綴榆天合，新城柳塞空。","花銷蔥嶺雪，縠尽流沙霧。","秋駕轉兢懷，春冰彌軫慮。","书絕龙庭羽，烽休鳳穴戍。","衣宵寢二难，食旰餐三懼。","翦暴兴先廢，除兇存昔亡。","圓蓋归天壤，方輿入地荒。","孔海池京邑，雙河沼帝乡。","循躬思勵己，撫俗媿时康。","元首佇鹽梅，股肱惟輔弼。","羽賢崆嶺四，翼聖襄城七。","澆俗庶反淳，替文聊就質。","已知隆至道，共歡區宇一。"]', '诗', 'shi', '', NULL, '執契靜三邊 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb81eac8-221c-4d0a-89d7-aa4c0f01d8a1', '正日臨朝', '正日臨朝', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["條風開獻節，灰律動初陽。","百蠻奉遐賮，萬國朝未央。","雖無舜禹迹，幸欣天地康。","車軌同八表，書文混四方。","赫奕儼冠蓋，紛綸盛服章。","羽旄飛馳道，鐘鼓震巖廊。","組練輝霞色，霜戟耀朝光。","晨宵懷至理，終媿撫遐荒。"]', '["條风开獻節，灰律动初陽。","百蠻奉遐賮，万国朝未央。","雖無舜禹迹，幸欣天地康。","车軌同八表，书文混四方。","赫奕儼冠蓋，紛綸盛服章。","羽旄飞驰道，鐘鼓震巖廊。","組練輝霞色，霜戟耀朝光。","晨宵懷至理，終媿撫遐荒。"]', '诗', 'shi', '', NULL, '正日臨朝 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84bf01fc-ec00-4d81-8189-153cd0c0d4ea', '幸武功慶善宮', '幸武功慶善宮', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["壽丘惟舊跡，酆邑乃前基。","粵予承累聖，懸弧亦在茲。","弱齡逢運改，提劒鬱匡時。","指麾八荒定，懷柔萬國夷。","梯山咸入款，駕海亦來思。","單于陪武帳，日逐衛文㮰。","端扆朝四岳，無爲任百司。","霜節明秋景，輕冰結水湄。","芸黃徧原隰，禾穎積京畿。","共樂還鄉宴，歡比大風詩。"]', '["壽丘惟旧跡，酆邑乃前基。","粵予承累聖，懸弧亦在茲。","弱齡逢運改，提劒鬱匡时。","指麾八荒定，懷柔万国夷。","梯山咸入款，駕海亦来思。","單于陪武帳，日逐衛文㮰。","端扆朝四岳，無爲任百司。","霜節明秋景，轻冰結水湄。","芸黄徧原隰，禾穎積京畿。","共乐還乡宴，歡比大风诗。"]', '诗', 'shi', '', NULL, '幸武功慶善宮 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5436455-4bdd-4425-96c5-12ed92905950', '重幸武功', '重幸武功', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["代馬依朔吹，驚禽愁昔叢。","況茲承眷德，懷舊感深衷。","積善忻餘慶，暢武悅成功。","垂衣天下治，端拱車書同。","白水巡前跡，丹陵幸舊宮。","列筵歡故老，高宴聚新豐。","駐蹕撫田畯，回輿訪牧童。","瑞氣縈丹闕，祥煙散碧空。","孤嶼含霜白，遙山帶日紅。","於焉歡擊筑，聊以詠南風。"]', '["代马依朔吹，驚禽愁昔叢。","況茲承眷德，懷旧感深衷。","積善忻餘慶，暢武悅成功。","垂衣天下治，端拱车书同。","白水巡前跡，丹陵幸旧宮。","列筵歡故老，高宴聚新豐。","駐蹕撫田畯，回輿訪牧童。","瑞氣縈丹闕，祥煙散碧空。","孤嶼含霜白，遙山带日紅。","於焉歡擊筑，聊以詠南风。"]', '诗', 'shi', '', NULL, '重幸武功 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a3c83d8-a6f2-46f7-852b-4d2162d1c6c4', '經破薛舉戰地', '經破薛舉戰地', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["昔年懷壯氣，提戈初仗節。","心隨朗日高，志與秋霜潔。","移鋒驚電起，轉戰長河決。","營碎落星沈，陣卷橫雲裂。","一揮氛沴靜，再舉鯨鯢滅。","於茲俯舊原，屬目駐華軒。","沈沙無故迹，減竈有殘痕。","浪霞穿水淨，峰霧抱蓮昏。","世途亟流易，人事殊今昔。","長想眺前蹤，撫躬聊自適。"]', '["昔年懷壯氣，提戈初仗節。","心隨朗日高，志與秋霜潔。","移鋒驚電起，轉戰长河決。","營碎落星沈，陣卷橫云裂。","一揮氛沴静，再舉鯨鯢滅。","於茲俯旧原，屬目駐华軒。","沈沙無故迹，減竈有殘痕。","浪霞穿水淨，峰霧抱蓮昏。","世途亟流易，人事殊今昔。","长想眺前蹤，撫躬聊自適。"]', '诗', 'shi', '', NULL, '經破薛舉戰地 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba88d33-b035-4949-b673-e498ccfcee24', '過舊宅二首 一', '過旧宅二首 一', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["新豐停翠輦，譙邑駐鳴笳。","園荒一徑斷，苔古半階斜。","前池消舊水，昔樹發今花。","一朝辭此地，四海遂爲家。"]', '["新豐停翠輦，譙邑駐鳴笳。","园荒一徑斷，苔古半階斜。","前池消旧水，昔樹發今花。","一朝辞此地，四海遂爲家。"]', '诗', 'shi', '', NULL, '過舊宅二首 一 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c69b5b5-49c7-4d2b-8472-e11d39ca4106', '過舊宅二首 二', '過旧宅二首 二', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["金輿巡白水，玉輦駐新豐。","紐落藤披架，花殘菊破叢。","葉鋪荒草蔓，流竭半池空。","紉珮蘭凋徑，舒圭葉翦桐。","昔地一蕃內，今宅九圍中。","架海波澄鏡，韜戈器反農。","八表文同軌，無勞歌大風。"]', '["金輿巡白水，玉輦駐新豐。","紐落藤披架，花殘菊破叢。","葉鋪荒草蔓，流竭半池空。","紉珮蘭凋徑，舒圭葉翦桐。","昔地一蕃內，今宅九圍中。","架海波澄镜，韜戈器反農。","八表文同軌，無勞歌大风。"]', '诗', 'shi', '', NULL, '過舊宅二首 二 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70ec76dd-b81d-4d0b-944d-a71d13469e19', '還陝述懷', '還陝述懷', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["慨然撫長劒，濟世豈邀名。","星旂紛電舉，日羽肅天行。","徧野屯萬騎，臨原駐五營。","登山麾武節，背水縱神兵。","在昔戎戈動，今來宇宙平。"]', '["慨然撫长劒，濟世豈邀名。","星旂紛電舉，日羽肅天行。","徧野屯万騎，臨原駐五營。","登山麾武節，背水縱神兵。","在昔戎戈动，今来宇宙平。"]', '诗', 'shi', '', NULL, '還陝述懷 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09848995-b603-4010-8f95-0027fda0d119', '入潼關', '入潼关', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["崤函稱地險，襟帶壯兩京。","霜峰直臨道，冰河曲繞城。","古木參差影，寒猿斷續聲。","冠蓋往來合，風塵朝夕驚。","高談先馬度，僞曉預雞鳴。","棄繻懷遠志，封泥負壯情。","別有真人氣，安知名不名。"]', '["崤函稱地險，襟带壯兩京。","霜峰直臨道，冰河曲繞城。","古木參差影，寒猿斷續声。","冠蓋往来合，风塵朝夕驚。","高談先马度，僞晓預雞鳴。","棄繻懷远志，封泥負壯情。","別有真人氣，安知名不名。"]', '诗', 'shi', '', NULL, '入潼關 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c821f7b5-7b29-4f76-be64-cd5b5f9eca09', '於北平作', '於北平作', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["翠野駐戎軒，盧龍轉征斾。","遙山麗如綺，長流縈似帶。","海氣百重樓，巖松千丈蓋。"]', '["翠野駐戎軒，盧龙轉征斾。","遙山丽如綺，长流縈似带。","海氣百重楼，巖松千丈蓋。"]', '诗', 'shi', '', NULL, '於北平作 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d1a470-54cc-4e65-954b-5ab6eeb7358b', '遼城望月', '遼城望月', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["玄兔月初明，澄輝照遼碣。","映雲光暫隱，隔樹花如綴。","魄滿桂枝圓，輪虧鏡彩缺。","臨城却影散，帶暈重圍結。","駐蹕俯九都，停觀妖氛滅。"]', '["玄兔月初明，澄輝照遼碣。","映云光暫隐，隔樹花如綴。","魄满桂枝圓，輪虧镜彩缺。","臨城却影散，带暈重圍結。","駐蹕俯九都，停观妖氛滅。"]', '诗', 'shi', '', NULL, '遼城望月 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7136e8b6-cec9-423f-89e9-a260eeb32481', '春日登陝州城樓俯眺原野迴丹碧綴煙霞密翠斑紅芳菲花柳即目川岫聊以命篇', '春日登陝州城楼俯眺原野迴丹碧綴煙霞密翠斑紅芳菲花柳即目川岫聊以命篇', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["碧原開霧隰，綺嶺峻霞城。","煙峰高下翠，日浪淺深明。","斑紅粧橤樹，圓青壓溜荆。","迹巖勞傅想，窺野訪莘情。","巨川何以濟，舟楫佇時英。"]', '["碧原开霧隰，綺嶺峻霞城。","煙峰高下翠，日浪淺深明。","斑紅粧橤樹，圓青壓溜荆。","迹巖勞傅想，窺野訪莘情。","巨川何以濟，舟楫佇时英。"]', '诗', 'shi', '', NULL, '春日登陝州城樓俯眺原野迴丹碧綴煙霞密翠斑紅芳菲花柳即目川岫聊以命篇 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f85432ef-54f1-4cc0-91c5-91af18ff0d05', '春日玄武門宴羣臣', '春日玄武门宴羣臣', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["韶光開令序，淑氣動芳年。","駐輦華林側，高宴柏梁前。","紫庭文珮滿，丹墀衮紱連。","九夷簉瑤席，五狄列瓊筵。","娛賓歌湛露，廣樂奏鈞天。","清尊浮綠醑，雅曲韻朱弦。","粵余君萬國，還慙撫八埏。","庶幾保貞固，虛己厲求賢。"]', '["韶光开令序，淑氣动芳年。","駐輦华林側，高宴柏梁前。","紫庭文珮满，丹墀衮紱連。","九夷簉瑤席，五狄列瓊筵。","娛賓歌湛露，廣乐奏鈞天。","清尊浮綠醑，雅曲韻朱弦。","粵余君万国，還慙撫八埏。","庶幾保貞固，虛己厲求賢。"]', '诗', 'shi', '', NULL, '春日玄武門宴羣臣 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db548528-fbd1-4356-bc2d-403760c1267c', '登三臺言志', '登三台言志', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["未央初壯漢，阿房昔侈秦。","在危猶騁麗，居奢遂役人。","豈如家四海，日宇罄朝倫。","扇天裁戶舊，砌地翦基新。","引月擎宵桂，飄雲逼曙鱗。","露除光炫玉，霜闕映雕銀。","舞接花梁燕，歌迎鳥路塵。","鏡池波太液，莊苑麗宜春。","作異甘泉日，停非路寢辰。","念勞慙逸己，居曠返勞神。","所欣成大厦，宏材佇渭濱。"]', '["未央初壯漢，阿房昔侈秦。","在危猶騁丽，居奢遂役人。","豈如家四海，日宇罄朝倫。","扇天裁戶旧，砌地翦基新。","引月擎宵桂，飄云逼曙鱗。","露除光炫玉，霜闕映雕銀。","舞接花梁燕，歌迎鸟路塵。","镜池波太液，莊苑丽宜春。","作異甘泉日，停非路寢辰。","念勞慙逸己，居曠返勞神。","所欣成大厦，宏材佇渭濱。"]', '诗', 'shi', '', NULL, '登三臺言志 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('822d55ea-2b24-4067-a997-106adf6d6f55', '出獵', '出獵', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["楚王雲夢澤，漢帝長楊宮。","豈若因農暇，閱武出轘嵩。","三驅陳銳卒，七萃列材雄。","寒野霜氛白，平原燒火紅。","琱戈夏服箭，羽騎綠沈弓。","怖獸潛幽壑，驚禽散翠空。","長煙晦落景，灌木振嚴風。","所爲除民瘼，非是悅林叢。"]', '["楚王云梦澤，漢帝长楊宮。","豈若因農暇，閱武出轘嵩。","三驱陳銳卒，七萃列材雄。","寒野霜氛白，平原燒火紅。","琱戈夏服箭，羽騎綠沈弓。","怖獸潛幽壑，驚禽散翠空。","长煙晦落景，灌木振嚴风。","所爲除民瘼，非是悅林叢。"]', '诗', 'shi', '', NULL, '出獵 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b11c8320-d662-41e0-a9f2-8f4d4c4ceccd', '冬狩', '冬狩', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["烈烈寒風起，慘慘飛雲浮。","霜濃凝廣隰，冰厚結清流。","金鞍移上苑，玉勒騁平疇。","旌旗四望合，罝羅一面求。","楚踣爭兕殪，秦亡角鹿愁。","獸忙投密樹，鴻驚起礫洲。","騎斂原塵靜，戈迴嶺日收。","心非洛汭逸，意在渭濱游。","禽荒非所樂，撫轡更招憂。"]', '["烈烈寒风起，慘慘飞云浮。","霜濃凝廣隰，冰厚結清流。","金鞍移上苑，玉勒騁平疇。","旌旗四望合，罝羅一面求。","楚踣爭兕殪，秦亡角鹿愁。","獸忙投密樹，鴻驚起礫洲。","騎斂原塵静，戈迴嶺日收。","心非洛汭逸，意在渭濱游。","禽荒非所乐，撫轡更招憂。"]', '诗', 'shi', '', NULL, '冬狩 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdf597bd-d45c-407d-9a5b-739be83771de', '春日望海', '春日望海', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["披襟眺滄海，憑軾翫春芳。","積流橫地紀，疎派引天潢。","仙氣凝三嶺，和風扇八荒。","拂潮雲布色，穿浪日舒光。","照岸花分彩，迷雲雁斷行。","懷卑運深廣，持滿守靈長。","有形非易測，無源詎可量。","洪濤經變野，翠島屢成桑。","之罘思漢帝，碣石想秦皇。","霓裳非本意，端拱且圖王。"]', '["披襟眺滄海，憑軾翫春芳。","積流橫地紀，疎派引天潢。","仙氣凝三嶺，和风扇八荒。","拂潮云布色，穿浪日舒光。","照岸花分彩，迷云雁斷行。","懷卑運深廣，持满守靈长。","有形非易測，無源詎可量。","洪濤經变野，翠島屢成桑。","之罘思漢帝，碣石想秦皇。","霓裳非本意，端拱且圖王。"]', '诗', 'shi', '', NULL, '春日望海 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('602688e2-e83d-4afd-87aa-af6f8f971a8a', '臨洛水', '臨洛水', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["春蒐馳駿骨，總轡俯長河。","霞處流縈錦，風前瀁卷羅。","水花翻照樹，堤蘭倒插波。","豈必汾陰曲，秋雲發棹歌。"]', '["春蒐驰駿骨，總轡俯长河。","霞处流縈錦，风前瀁卷羅。","水花翻照樹，堤蘭倒插波。","豈必汾陰曲，秋云發棹歌。"]', '诗', 'shi', '', NULL, '臨洛水 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4714a2d4-49c5-45f5-a2ae-4a0eceac88f8', '望終南山', '望終南山', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["重巒俯渭水，碧嶂插遙天。","出紅扶嶺日，入翠貯巖煙。","疊松朝若夜，複岫闕疑全。","對此恬千慮，無勞訪九仙。"]', '["重巒俯渭水，碧嶂插遙天。","出紅扶嶺日，入翠貯巖煙。","叠松朝若夜，複岫闕疑全。","对此恬千慮，無勞訪九仙。"]', '诗', 'shi', '', NULL, '望終南山 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63397c51-1271-4a83-b1c3-a9daef8f406a', '元日', '元日', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["高軒曖春色，邃閣媚朝光。","彤庭飛綵斾，翠幌曜明璫。","恭己臨四極，垂衣馭八荒。","霜戟列丹陛，絲竹韻長廊。","穆矣熏風茂，康哉帝道昌。","繼文遵後軌，循古鑒前王。","草秀故春色，梅豔昔年粧。","巨川思欲濟，終以寄舟航。"]', '["高軒曖春色，邃閣媚朝光。","彤庭飞綵斾，翠幌曜明璫。","恭己臨四極，垂衣馭八荒。","霜戟列丹陛，絲竹韻长廊。","穆矣熏风茂，康哉帝道昌。","繼文遵後軌，循古鑒前王。","草秀故春色，梅豔昔年粧。","巨川思欲濟，終以寄舟航。"]', '诗', 'shi', '', NULL, '元日 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd63be75-f6b3-491d-91d5-04179194f1aa', '初春登樓即目觀作述懷', '初春登楼即目观作述懷', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["憑軒俯蘭閣，眺矚散靈襟。","綺峰含翠霧，照日蕊紅林。","鏤丹霞錦岫，殘素雪斑岑。","拂浪堤垂柳，嬌花鳥續吟。","連甍豈一拱，衆幹如千尋。","明非獨材力，終藉棟梁深。","彌懷矜樂志，更懼戒盈心。","媿制勞居逸，方規十產金。"]', '["憑軒俯蘭閣，眺矚散靈襟。","綺峰含翠霧，照日蕊紅林。","鏤丹霞錦岫，殘素雪斑岑。","拂浪堤垂柳，嬌花鸟續吟。","連甍豈一拱，衆幹如千尋。","明非独材力，終藉棟梁深。","彌懷矜乐志，更懼戒盈心。","媿制勞居逸，方規十產金。"]', '诗', 'shi', '', NULL, '初春登樓即目觀作述懷 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f1983d-2147-4028-a0d8-fdfc4c2d8244', '首春', '首春', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["寒隨窮律變，春逐鳥聲開。","初風飄帶柳，晚雪間花梅。","碧林青舊竹，綠沼翠新苔。","芝田初雁去，綺樹巧鸎來。"]', '["寒隨窮律变，春逐鸟声开。","初风飄带柳，晚雪间花梅。","碧林青旧竹，綠沼翠新苔。","芝田初雁去，綺樹巧鸎来。"]', '诗', 'shi', '', NULL, '首春 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('847b969b-de24-48b5-9917-29f1e0233c08', '初晴落景', '初晴落景', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["晚霞聊自怡，初晴彌可喜。","日晃百花色，風動千林翠。","池魚躍不同，園鳥聲還異。","寄言博通者，知予物外志。"]', '["晚霞聊自怡，初晴彌可喜。","日晃百花色，风动千林翠。","池鱼躍不同，园鸟声還異。","寄言博通者，知予物外志。"]', '诗', 'shi', '', NULL, '初晴落景 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d2bd14f-e18f-4296-a4f0-972b09a7928a', '初夏', '初夏', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["一朝春夏改，隔夜鳥花遷。","陰陽深淺葉，曉夕重輕煙。","哢鸎猶響殿，橫絲正網天。","珮高蘭影接，綬細草紋連。","碧鱗驚櫂側，玄燕舞檐前。","何必汾陽處，始復有山泉。"]', '["一朝春夏改，隔夜鸟花遷。","陰陽深淺葉，晓夕重轻煙。","哢鸎猶响殿，橫絲正網天。","珮高蘭影接，綬細草紋連。","碧鱗驚櫂側，玄燕舞檐前。","何必汾陽处，始复有山泉。"]', '诗', 'shi', '', NULL, '初夏 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc15b398-9ab5-4210-b1df-885c70cf846f', '度秋', '度秋', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["夏律昨留灰，秋箭今移晷。","峨嵋岫初出，洞庭波漸起。","桂白發幽巖，菊黃開灞涘。","運流方可歎，含毫屬微理。"]', '["夏律昨留灰，秋箭今移晷。","峨嵋岫初出，洞庭波漸起。","桂白發幽巖，菊黄开灞涘。","運流方可歎，含毫屬微理。"]', '诗', 'shi', '', NULL, '度秋 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09bbfe4c-d07c-4f0d-96b1-92647d37cd1e', '儀鸞殿早秋', '儀鸾殿早秋', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["寒驚薊門葉，秋發小山枝。","松陰背日轉，竹影避風移。","提壺菊花岸，高興芙蓉池。","欲知涼氣早，巢空燕不窺。"]', '["寒驚薊门葉，秋發小山枝。","松陰背日轉，竹影避风移。","提壺菊花岸，高兴芙蓉池。","欲知涼氣早，巢空燕不窺。"]', '诗', 'shi', '', NULL, '儀鸞殿早秋 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a609556d-746c-4703-97a2-0aac7168fce7', '秋日即目', '秋日即目', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["爽氣浮丹闕，秋光澹紫宮。","衣碎荷疎影，花明菊點叢。","袍輕低草露，蓋側舞松風。","散岫飄雲葉，迷路飛煙鴻。","砌冷蘭凋佩，閨寒樹隕桐。","別鶴棲琴裏，離猿啼峽中。","落野飛星箭，弦虛半月弓。","芳菲夕霧起，暮色滿房櫳。"]', '["爽氣浮丹闕，秋光澹紫宮。","衣碎荷疎影，花明菊点叢。","袍轻低草露，蓋側舞松风。","散岫飄云葉，迷路飞煙鴻。","砌冷蘭凋佩，閨寒樹隕桐。","別鹤棲琴裏，離猿啼峽中。","落野飞星箭，弦虛半月弓。","芳菲夕霧起，暮色满房櫳。"]', '诗', 'shi', '', NULL, '秋日即目 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4f255b-13f1-4a5f-b36c-5ef48f8fc455', '山閣晚秋', '山閣晚秋', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["山亭秋色滿，巖牖涼風度。","疎蘭尚染煙，殘菊猶承露。","古石衣新苔，新巢封古樹。","歷覽情無極，咫尺輸光暮。"]', '["山亭秋色满，巖牖涼风度。","疎蘭尚染煙，殘菊猶承露。","古石衣新苔，新巢封古樹。","歷覽情無極，咫尺輸光暮。"]', '诗', 'shi', '', NULL, '山閣晚秋 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d2bcfb9-1052-40ca-8a14-87ba811aee4e', '秋暮言志', '秋暮言志', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["朝光浮燒野，霜華淨碧空。","結浪冰初鏡，在逕菊方叢。","約嶺煙深翠，分旗霞散紅。","抽思滋泉側，飛想傅巖中。"]', '["朝光浮燒野，霜华淨碧空。","結浪冰初镜，在逕菊方叢。","約嶺煙深翠，分旗霞散紅。","抽思滋泉側，飞想傅巖中。"]', '诗', 'shi', '', NULL, '秋暮言志 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8de88b9b-bb36-4f7e-a2cd-4771ff984a8a', '喜雪', '喜雪', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["碧昏朝合霧，丹卷暝韜霞。","結葉繁雲色，凝璚徧雪華。","光樓皎若粉，映幕集疑沙。","泛柳飛飛絮，粧梅片片花。","照璧臺圓月，飄珠箔穿露。","瑤潔短長階，玉藂高下樹。","映桐珪累白，縈峰蓮抱素。","斷續氣將沈，徘徊歲云暮。","懷珍媿隱德，表瑞佇豐年。","橤間飛禁苑，鶴處舞伊川。","儻詠幽蘭曲，同懽黃竹篇。"]', '["碧昏朝合霧，丹卷暝韜霞。","結葉繁云色，凝璚徧雪华。","光楼皎若粉，映幕集疑沙。","泛柳飞飞絮，粧梅片片花。","照璧台圓月，飄珠箔穿露。","瑤潔短长階，玉藂高下樹。","映桐珪累白，縈峰蓮抱素。","斷續氣將沈，徘徊歲云暮。","懷珍媿隐德，表瑞佇豐年。","橤间飞禁苑，鹤处舞伊川。","儻詠幽蘭曲，同懽黄竹篇。"]', '诗', 'shi', '', NULL, '喜雪 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7be96695-a98f-43ce-a539-db885c3b0cf0', '秋日斅庾信體', '秋日斅庾信體', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["嶺銜宵月桂，珠穿曉露叢。","蟬啼覺樹冷，螢火不溫風。","花生圓菊橤，荷盡戲魚通。","晨浦鳴飛雁，夕渚集栖鴻。","颯颯高天吹，氛澄下熾空。"]', '["嶺銜宵月桂，珠穿晓露叢。","蟬啼覺樹冷，螢火不溫风。","花生圓菊橤，荷尽戲鱼通。","晨浦鳴飞雁，夕渚集栖鴻。","颯颯高天吹，氛澄下熾空。"]', '诗', 'shi', '', NULL, '秋日斅庾信體 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f09ef2-88a4-4fd3-979d-8cfb6541eb93', '賦尚書', '賦尚书', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["崇文時駐步，東觀還停輦。","輟膳翫三墳，暉燈披五典。","寒心覩肉林，飛魄看沈湎。","縱情昏主多，克己明君鮮。","滅身資累惡，成名由積善。","既承百王末，戰兢隨歲轉。"]', '["崇文时駐步，东观還停輦。","輟膳翫三墳，暉灯披五典。","寒心覩肉林，飞魄看沈湎。","縱情昏主多，克己明君鲜。","滅身資累惡，成名由積善。","既承百王末，戰兢隨歲轉。"]', '诗', 'shi', '', NULL, '賦尚書 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2236d4fc-b6ec-481c-97cb-ac7609dd8382', '詠司馬彪續漢志', '詠司马彪續漢志', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["二儀初創象，三才乃分位。","非惟樹司牧，固亦垂文字。","緜代更膺期，芳圖無輟記。","炎漢承君道，英謨纂神器。","潛龍既可躍，逵兔奚難致。","前史殫妙詞，後昆沈雅思。","書言揚盛跡，補闕興洪志。","川谷猶舊途，郡國開新意。","梅山未覺朽，穀水誰云異。","車服隨名表，文物因時置。","鳳戟翼康衢，鑾輿總柔轡。","清濁必能澄，洪纖幸無棄。","觀儀不失序，遵禮方由事。","政宣竹律和，時平玉條備。","文囿雕奇彩，藝門蘊深致。","雲飛星共流，風揚月兼至。","類禋遵令典，壇壝資良地。","五勝竟無違，百司誠有庇。","粵予承暇景，談叢引泉祕。","討論窮義府，看覈披經笥。","大辨良難仰，小學終先匱。","聞道諒知榮，含毫孰忘媿。"]', '["二儀初創象，三才乃分位。","非惟樹司牧，固亦垂文字。","緜代更膺期，芳圖無輟記。","炎漢承君道，英謨纂神器。","潛龙既可躍，逵兔奚难致。","前史殫妙词，後昆沈雅思。","书言揚盛跡，補闕兴洪志。","川谷猶旧途，郡国开新意。","梅山未覺朽，穀水誰云異。","车服隨名表，文物因时置。","鳳戟翼康衢，鑾輿總柔轡。","清濁必能澄，洪纖幸無棄。","观儀不失序，遵禮方由事。","政宣竹律和，时平玉條備。","文囿雕奇彩，藝门蘊深致。","云飞星共流，风揚月兼至。","類禋遵令典，壇壝資良地。","五勝竟無違，百司誠有庇。","粵予承暇景，談叢引泉祕。","討論窮義府，看覈披經笥。","大辨良难仰，小学終先匱。","闻道諒知榮，含毫孰忘媿。"]', '诗', 'shi', '', NULL, '詠司馬彪續漢志 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d4ab8fc-aa99-46f4-8571-54af4d4666bf', '詠風', '詠风', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["蕭條起關塞，搖颺下蓬瀛。","拂林花亂彩，響谷鳥分聲。","披雲羅影散，泛水織文生。","勞歌大風曲，威加四海清。"]', '["蕭條起关塞，搖颺下蓬瀛。","拂林花亂彩，响谷鸟分声。","披云羅影散，泛水织文生。","勞歌大风曲，威加四海清。"]', '诗', 'shi', '', NULL, '詠風 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28968a18-20d9-4c42-91ea-98e53f9e769e', '詠雨', '詠雨', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["罩雲飄遠岫，噴雨泛長河。","低飛昏嶺腹，斜足灑巖阿。","泫叢珠締葉，起溜鏡圖波。","濛柳添絲密，含吹織空羅。"]', '["罩云飄远岫，噴雨泛长河。","低飞昏嶺腹，斜足灑巖阿。","泫叢珠締葉，起溜镜圖波。","濛柳添絲密，含吹织空羅。"]', '诗', 'shi', '', NULL, '詠雨 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125c6392-6a3b-4ba2-a0af-d9520b6b7e6b', '詠雪', '詠雪', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["潔野凝晨曜，裝墀帶夕暉。","集條分樹玉，拂浪影泉璣。","色灑妝臺粉，花飄綺席衣。","入扇縈離匣，點素皎殘機。"]', '["潔野凝晨曜，裝墀带夕暉。","集條分樹玉，拂浪影泉璣。","色灑妝台粉，花飄綺席衣。","入扇縈離匣，点素皎殘機。"]', '诗', 'shi', '', NULL, '詠雪 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3850fcde-577f-4a8a-8fae-3efe63b00439', '賦得夏首啓節', '賦得夏首啓節', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["北闕三春晚，南榮九夏初。","黃鶯弄漸變，翠林花落餘。","瀑流還響谷，猿啼自應虛。","早荷向心卷，長楊就影舒。","此時歡不極，調軫坐相於。"]', '["北闕三春晚，南榮九夏初。","黄鶯弄漸变，翠林花落餘。","瀑流還响谷，猿啼自應虛。","早荷向心卷，长楊就影舒。","此时歡不極，調軫坐相於。"]', '诗', 'shi', '', NULL, '賦得夏首啓節 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5060cf4-fac1-454f-b85e-014ec8c2870b', '賦得白日半西山', '賦得白日半西山', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["紅輪不暫駐，烏飛豈復停。","岑霞漸漸落，溪陰寸寸生。","藿葉隨光轉，葵心逐照傾。","晚煙含樹色，棲鳥雜流聲。"]', '["紅輪不暫駐，烏飞豈复停。","岑霞漸漸落，溪陰寸寸生。","藿葉隨光轉，葵心逐照傾。","晚煙含樹色，棲鸟杂流声。"]', '诗', 'shi', '', NULL, '賦得白日半西山 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c05f129-817c-4e03-af67-4ab13a07a172', '置酒坐飛閣', '置酒坐飞閣', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["高軒臨碧渚，飛檐迥架空。","餘花攢鏤檻，殘柳散雕櫳。","岸菊初含橤，園梨始帶紅。","莫慮崑山暗，還共盡杯中。"]', '["高軒臨碧渚，飞檐迥架空。","餘花攢鏤檻，殘柳散雕櫳。","岸菊初含橤，园梨始带紅。","莫慮崑山暗，還共尽杯中。"]', '诗', 'shi', '', NULL, '置酒坐飛閣 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('403f95d9-35f0-4a0a-9570-1337546203c6', '采芙蓉', '采芙蓉', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["結伴戲方塘，攜手上雕航。","船移分細浪，風散動浮香。","遊鸎無定曲，驚鳧有亂行。","蓮稀釧聲斷，水廣櫂歌長。","棲烏還密樹，泛流歸建章。"]', '["結伴戲方塘，携手上雕航。","船移分細浪，风散动浮香。","游鸎無定曲，驚鳧有亂行。","蓮稀釧声斷，水廣櫂歌长。","棲烏還密樹，泛流归建章。"]', '诗', 'shi', '', NULL, '采芙蓉 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ab98da-082d-4117-98e1-79bc8c2635ed', '賦得櫻桃', '賦得櫻桃', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["華林滿芳景，洛陽徧陽春。","朱顏含遠日，翠色影長津。","喬柯囀嬌鳥，低枝映美人。","昔作園中實，今來席上珍。"]', '["华林满芳景，洛陽徧陽春。","朱顏含远日，翠色影长津。","喬柯囀嬌鸟，低枝映美人。","昔作园中實，今来席上珍。"]', '诗', 'shi', '', NULL, '賦得櫻桃 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cc40e68-b5bb-4af8-9a5b-5b6118881e86', '賦得李', '賦得李', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["玉衡流桂圃，成蹊正可尋。","鸎啼密葉外，蝶戲脆花心。","麗景光朝彩，輕霞散夕陰。","暫顧暉章側，還眺靈山林。"]', '["玉衡流桂圃，成蹊正可尋。","鸎啼密葉外，蝶戲脆花心。","丽景光朝彩，轻霞散夕陰。","暫顧暉章側，還眺靈山林。"]', '诗', 'shi', '', NULL, '賦得李 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c1d43ec-220c-4983-a6f9-e4e55631ad44', '賦得浮橋', '賦得浮橋', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["岸曲非千里，橋斜異七星。","暫低逢輦度，還高值浪驚。","水搖文鷁動，纜轉錦花縈。","遠近隨輪影，輕重應人行。"]', '["岸曲非千里，橋斜異七星。","暫低逢輦度，還高值浪驚。","水搖文鷁动，纜轉錦花縈。","远近隨輪影，轻重應人行。"]', '诗', 'shi', '', NULL, '賦得浮橋 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147b640e-e767-4dbb-8934-23c199390f9f', '謁幷州大興國寺詩', '謁幷州大兴国寺诗', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["回鑾遊福地，極目玩芳晨。","梵鐘交二響，法日轉雙輪。","寶剎遙承露，天花近足春。","未佩蘭猶小，無絲柳尚新。","圓光低月殿，碎影亂風筠。","對此留餘想，超然離俗塵。"]', '["回鑾游福地，極目玩芳晨。","梵鐘交二响，法日轉雙輪。","寶剎遙承露，天花近足春。","未佩蘭猶小，無絲柳尚新。","圓光低月殿，碎影亂风筠。","对此留餘想，超然離俗塵。"]', '诗', 'shi', '', NULL, '謁幷州大興國寺詩 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed3c7340-40dd-4581-8fa0-73f4060473ae', '詠興國寺佛殿前幡', '詠兴国寺佛殿前幡', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["拂霞疑電落，騰虛狀寫虹。","屈伸煙霧裏，低舉白雲中。","紛披乍依迥，掣曳或隨風。","念茲輕薄質，無翅強搖空。"]', '["拂霞疑電落，腾虛狀寫虹。","屈伸煙霧裏，低舉白云中。","紛披乍依迥，掣曳或隨风。","念茲轻薄質，無翅強搖空。"]', '诗', 'shi', '', NULL, '詠興國寺佛殿前幡 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f444f7d-1c9a-42c5-a2dd-1dda1aac432a', '望送魏徵葬', '望送魏徵葬', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["閶闔總金鞍，上林移玉輦。","野郊愴新別，河橋非舊餞。","慘日映峰沈，愁雲隨蓋轉。","哀笳時斷續，悲旌乍舒卷。","望望情何極，浪浪淚空泫。","無復昔時人，芳春共誰遣。"]', '["閶闔總金鞍，上林移玉輦。","野郊愴新別，河橋非旧餞。","慘日映峰沈，愁云隨蓋轉。","哀笳时斷續，悲旌乍舒卷。","望望情何極，浪浪泪空泫。","無复昔时人，芳春共誰遣。"]', '诗', 'shi', '', NULL, '望送魏徵葬 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c59e8104-e7ec-433d-ae2f-033ba7267993', '傷遼東戰亡', '傷遼东戰亡', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["鑿門初奉律，仗戰始臨戎。","振鱗方躍浪，騁翼正凌風。","未展六奇術，先虧一簣功。","防身豈乏智，殉命有餘忠。"]', '["鑿门初奉律，仗戰始臨戎。","振鱗方躍浪，騁翼正凌风。","未展六奇術，先虧一簣功。","防身豈乏智，殉命有餘忠。"]', '诗', 'shi', '', NULL, '傷遼東戰亡 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f179f71-6bfa-4329-9340-2aa81745b2c6', '月晦', '月晦', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["晦魄移中律，凝暄起麗城。","罩雲朝蓋上，穿露曉珠呈。","笑樹花分色，啼枝鳥合聲。","披襟歡眺望，極目暢春情。"]', '["晦魄移中律，凝暄起丽城。","罩云朝蓋上，穿露晓珠呈。","笑樹花分色，啼枝鸟合声。","披襟歡眺望，極目暢春情。"]', '诗', 'shi', '', NULL, '月晦 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb8a283-d6a5-4fc0-9fc3-33e422157b3f', '秋日翠微宮', '秋日翠微宮', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["秋光凝翠嶺，涼吹肅離宮。","荷疎一蓋缺，樹冷半帷空。","側陣移鴻影，圓花釘菊叢。","攄懷俗塵外，高眺白雲中。"]', '["秋光凝翠嶺，涼吹肅離宮。","荷疎一蓋缺，樹冷半帷空。","側陣移鴻影，圓花釘菊叢。","攄懷俗塵外，高眺白云中。"]', '诗', 'shi', '', NULL, '秋日翠微宮 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f0897e1-ef12-4042-8e56-8cb1134cf9c3', '初秋夜坐', '初秋夜坐', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["斜廊連綺閣，初月照宵幃。","塞冷鴻飛疾，園秋蟬噪遲。","露結林疎葉，寒輕菊吐滋。","愁心逢此節，長歎獨含悲。"]', '["斜廊連綺閣，初月照宵幃。","塞冷鴻飞疾，园秋蟬噪遲。","露結林疎葉，寒轻菊吐滋。","愁心逢此節，长歎独含悲。"]', '诗', 'shi', '', NULL, '初秋夜坐 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff2b3cb0-be10-47e9-986f-3fa62c69e727', '秋日二首 一', '秋日二首 一', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["菊散金風起，荷疎玉露圓。","將秋數行雁，離夏幾林蟬。","雲凝愁半嶺，霞碎纈高天。","還似成都望，直見峨眉前。"]', '["菊散金风起，荷疎玉露圓。","將秋數行雁，離夏幾林蟬。","云凝愁半嶺，霞碎纈高天。","還似成都望，直见峨眉前。"]', '诗', 'shi', '', NULL, '秋日二首 一 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('731721e5-508d-452f-aaab-5b61f196de4c', '秋日二首 二', '秋日二首 二', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["爽氣澄蘭沼，秋風動桂林。","露凝千片玉，菊散一叢金。","日岫高低影，雲空點綴陰。","蓬瀛不可望，泉石且娛心。"]', '["爽氣澄蘭沼，秋风动桂林。","露凝千片玉，菊散一叢金。","日岫高低影，云空点綴陰。","蓬瀛不可望，泉石且娛心。"]', '诗', 'shi', '', NULL, '秋日二首 二 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed13392c-ff75-46b4-923b-509cadddbc24', '冬宵各爲四韻', '冬宵各爲四韻', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["雕宮靜龍漏，綺閣宴公侯。","珠簾燭燄動，繡柱月光浮。","雲起將歌發，風停與管遒。"]', '["雕宮静龙漏，綺閣宴公侯。","珠簾燭燄动，繡柱月光浮。","云起將歌發，风停與管遒。"]', '诗', 'shi', '', NULL, '冬宵各爲四韻 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c34fab35-9a2e-4bc3-82e7-e6d79c091b0b', '冬日臨昆明池', '冬日臨昆明池', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["石鯨分玉溜，劫燼隱平沙。","柳影冰無葉，梅心凍有花。","寒野凝朝霧，霜天散夕霞。","歡情猶未極，落景遽西斜。"]', '["石鯨分玉溜，劫燼隐平沙。","柳影冰無葉，梅心凍有花。","寒野凝朝霧，霜天散夕霞。","歡情猶未極，落景遽西斜。"]', '诗', 'shi', '', NULL, '冬日臨昆明池 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81a3a3f-0eec-4fe0-b482-40c50959b37e', '望雪', '望雪', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["凍雲宵徧嶺，素雪曉凝華。","入牖千重碎，迎風一半斜。","不妝空散粉，無樹獨飄花。","縈空慙夕照，破彩謝晨霞。"]', '["凍云宵徧嶺，素雪晓凝华。","入牖千重碎，迎风一半斜。","不妝空散粉，無樹独飄花。","縈空慙夕照，破彩謝晨霞。"]', '诗', 'shi', '', NULL, '望雪 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95db82fe-9e50-4bc6-be79-d1c79c61ce32', '守歲', '守歲', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["暮景斜芳殿，年華麗綺宮。","寒辭去冬雪，暖帶入春風。","階馥舒梅素，盤花卷燭紅。","共歡新故歲，迎送一宵中。"]', '["暮景斜芳殿，年华丽綺宮。","寒辞去冬雪，暖带入春风。","階馥舒梅素，盤花卷燭紅。","共歡新故歲，迎送一宵中。"]', '诗', 'shi', '', NULL, '守歲 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15fac24c-4cf1-424d-8758-511f755aa8fc', '除夜', '除夜', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["歲陰窮暮紀，獻節啓新芳。","冬盡今宵促，年開明日長。","冰消出鏡水，梅散入風香。","對此歡終宴，傾壺待曙光。"]', '["歲陰窮暮紀，獻節啓新芳。","冬尽今宵促，年开明日长。","冰消出镜水，梅散入风香。","对此歡終宴，傾壺待曙光。"]', '诗', 'shi', '', NULL, '除夜 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbad458d-8996-48f7-856d-1931d49f0e2c', '詠雨', '詠雨', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["和氣吹綠野，梅雨灑芳田。","新流添舊澗，宿霧足朝煙。","雁溼行無次，花霑色更鮮。","對此欣登歲，披襟弄五弦。"]', '["和氣吹綠野，梅雨灑芳田。","新流添旧澗，宿霧足朝煙。","雁溼行無次，花霑色更鲜。","对此欣登歲，披襟弄五弦。"]', '诗', 'shi', '', NULL, '詠雨 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c1c7765-a078-485f-9e03-f3905bc9d517', '賦得含峰雲', '賦得含峰云', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["翠樓含曉霧，蓮峰帶晚雲。","玉葉依巖聚，金枝觸石分。","橫天結陣影，逐吹起羅文。","非復陽臺下，空將惑楚君。"]', '["翠楼含晓霧，蓮峰带晚云。","玉葉依巖聚，金枝觸石分。","橫天結陣影，逐吹起羅文。","非复陽台下，空將惑楚君。"]', '诗', 'shi', '', NULL, '賦得含峰雲 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e022fa7a-ae8e-49c2-9369-f9d286b972e2', '三層閣上置音聲', '三層閣上置音声', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["綺筵移暮景，紫閣引宵煙。","隔棟歌塵合，分階舞影連。","聲流三處管，響亂一重絃。","不似秦樓上，吹簫空學仙。"]', '["綺筵移暮景，紫閣引宵煙。","隔棟歌塵合，分階舞影連。","声流三处管，响亂一重絃。","不似秦楼上，吹簫空学仙。"]', '诗', 'shi', '', NULL, '三層閣上置音聲 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fcbff48-e228-417c-bb6d-79979dddc1b2', '遠山澄碧霧', '远山澄碧霧', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["殘雲收翠嶺，夕霧結長空。","帶岫凝全碧，障霞隱半紅。","髣髴分初月，飄颻度曉風。","還因三里處，冠蓋遠相通。"]', '["殘云收翠嶺，夕霧結长空。","带岫凝全碧，障霞隐半紅。","髣髴分初月，飄颻度晓风。","還因三里处，冠蓋远相通。"]', '诗', 'shi', '', NULL, '遠山澄碧霧 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53cabac3-3558-4bcb-8845-9ebe1c3eb562', '賦得花庭霧', '賦得花庭霧', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["蘭氣已熏宮，新橤半粧叢。","色含輕重霧，香引去來風。","拂樹濃舒碧，縈花薄蔽紅。","還當雜行雨，髣髴隱遙空。"]', '["蘭氣已熏宮，新橤半粧叢。","色含轻重霧，香引去来风。","拂樹濃舒碧，縈花薄蔽紅。","還當杂行雨，髣髴隐遙空。"]', '诗', 'shi', '', NULL, '賦得花庭霧 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bfd3472-5aea-48b4-ae78-6c030ef4e64f', '春池柳', '春池柳', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["年柳變池臺，隋堤曲直回。","逐浪絲陰去，迎風帶影來。","疎黃一鳥弄，半翠幾眉開。","縈雪臨春岸，參差間早梅。"]', '["年柳变池台，隋堤曲直回。","逐浪絲陰去，迎风带影来。","疎黄一鸟弄，半翠幾眉开。","縈雪臨春岸，參差间早梅。"]', '诗', 'shi', '', NULL, '春池柳 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a422f68-ee50-4809-a6f7-e1ef510e51a5', '芳蘭', '芳蘭', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["春暉開紫苑，淑景媚蘭場。","映庭含淺色，凝露泫浮光。","日麗參差影，風傳輕重香。","會須君子折，佩裏作芬芳。"]', '["春暉开紫苑，淑景媚蘭場。","映庭含淺色，凝露泫浮光。","日丽參差影，风傳轻重香。","會須君子折，佩裏作芬芳。"]', '诗', 'shi', '', NULL, '芳蘭 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8098529a-3316-4f89-a17f-6e6a2ce52d59', '詠桃', '詠桃', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["禁苑春暉麗，花蹊綺樹妝。","綴條深淺色，點露參差光。","向日分千笑，迎風共一香。","如何仙嶺側，獨秀隱遙芳。"]', '["禁苑春暉丽，花蹊綺樹妝。","綴條深淺色，点露參差光。","向日分千笑，迎风共一香。","如何仙嶺側，独秀隐遙芳。"]', '诗', 'shi', '', NULL, '詠桃 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48bb657b-455d-4dd1-a38a-4312d39968fd', '賦簾', '賦簾', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["參差垂玉闕，舒卷映蘭宮。","珠光搖素月，竹影亂清風。","彩散銀鉤上，文斜桂戶中。","惟當雜羅綺，相與媚房櫳。"]', '["參差垂玉闕，舒卷映蘭宮。","珠光搖素月，竹影亂清风。","彩散銀鉤上，文斜桂戶中。","惟當杂羅綺，相與媚房櫳。"]', '诗', 'shi', '', NULL, '賦簾 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b4fdd33-abbc-4c1b-a33e-4e786e544865', '詠烏代陳師道', '詠烏代陳師道', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["凌晨麗城去，薄暮上林棲。","辭枝枝暫起，停樹樹還低。","向日終難託，迎風詎肯迷。","只待纖纖手，曲裏作宵啼。"]', '["凌晨丽城去，薄暮上林棲。","辞枝枝暫起，停樹樹還低。","向日終难託，迎风詎肯迷。","只待纖纖手，曲裏作宵啼。"]', '诗', 'shi', '', NULL, '詠烏代陳師道 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aab2f610-6652-486f-bbc7-034366eb35a4', '詠飲馬', '詠饮马', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["駿骨飲長涇，奔流灑絡纓。","細紋連噴聚，亂荇繞蹄縈。","水光鞍上側，馬影溜中橫。","翻似天池裏，騰波龍種生。"]', '["駿骨饮长涇，奔流灑絡纓。","細紋連噴聚，亂荇繞蹄縈。","水光鞍上側，马影溜中橫。","翻似天池裏，腾波龙種生。"]', '诗', 'shi', '', NULL, '詠飲馬 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e85cb66-dc1d-42b5-9f64-c5a19b4e9fed', '賦得殘菊', '賦得殘菊', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["階蘭凝曙霜，岸菊照晨光。","露濃晞晚笑，風勁淺殘香。","細葉凋輕翠，圓花飛碎黃。","還持今歲色，復結後年芳。"]', '["階蘭凝曙霜，岸菊照晨光。","露濃晞晚笑，风勁淺殘香。","細葉凋轻翠，圓花飞碎黄。","還持今歲色，复結後年芳。"]', '诗', 'shi', '', NULL, '賦得殘菊 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c23bb21b-7230-4256-b5e2-dbed22360c2e', '賦秋日懸清光賜房玄齡', '賦秋日懸清光賜房玄齡', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["秋露凝高掌，朝光上翠微。","參差麗雙闕，照耀滿重闈。","仙馭隨輪轉，靈烏帶影飛。","臨波無定彩，入隙有圓暉。","還當葵藿志，傾葉自相依。"]', '["秋露凝高掌，朝光上翠微。","參差丽雙闕，照耀满重闈。","仙馭隨輪轉，靈烏带影飞。","臨波無定彩，入隙有圓暉。","還當葵藿志，傾葉自相依。"]', '诗', 'shi', '', NULL, '賦秋日懸清光賜房玄齡 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5629da4-989d-4af5-a5e8-db1a6aaa8e6f', '琵琶', '琵琶', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["半月無雙影，全花有四時。","摧藏千里態，掩抑幾重悲。","促節縈紅袖，清音滿翠帷。","駛彈風響急，緩曲釧聲遲。","空餘關隴恨，因此代相思。"]', '["半月無雙影，全花有四时。","摧藏千里態，掩抑幾重悲。","促節縈紅袖，清音满翠帷。","駛彈风响急，緩曲釧声遲。","空餘关隴恨，因此代相思。"]', '诗', 'shi', '', NULL, '琵琶 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7c51477-e08e-4f2e-ba3b-361807bbecea', '宴中山', '宴中山', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["驅馬出遼陽，萬里轉旂常。","對敵六奇舉，臨戎八陣張。","斬鯨澄碧海，卷霧掃扶桑。","昔去蘭縈翠，今來桂染芳。","雲芝浮碎葉，冰鏡上朝光。","回首長安道，方歡宴柏梁。"]', '["驱马出遼陽，万里轉旂常。","对敵六奇舉，臨戎八陣張。","斬鯨澄碧海，卷霧掃扶桑。","昔去蘭縈翠，今来桂染芳。","云芝浮碎葉，冰镜上朝光。","回首长安道，方歡宴柏梁。"]', '诗', 'shi', '', NULL, '宴中山 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c6e81ed-cfe2-4900-aa3b-9d44ef7f1bea', '餞中書侍郎來濟', '餞中书侍郎来濟', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["曖曖去塵昏灞岸，飛飛輕蓋指河梁。","雲峰衣結千重葉，雪岫花開幾樹妝。","深悲黃鶴孤舟遠，獨歎青山別路長。","聊將分袂霑巾淚，還用持添離席觴。"]', '["曖曖去塵昏灞岸，飞飞轻蓋指河梁。","云峰衣結千重葉，雪岫花开幾樹妝。","深悲黄鹤孤舟远，独歎青山別路长。","聊將分袂霑巾泪，還用持添離席觴。"]', '诗', 'shi', '', NULL, '餞中書侍郎來濟 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7822c305-f1b3-4ed3-8011-f69dca0e965a', '於太原召侍臣賜宴守歲', '於太原召侍臣賜宴守歲', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["四時運灰琯，一夕變冬春。","送寒餘雪盡，迎歲早梅新。"]', '["四时運灰琯，一夕变冬春。","送寒餘雪尽，迎歲早梅新。"]', '诗', 'shi', '', NULL, '於太原召侍臣賜宴守歲 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4ea593e-ab38-4278-9d9b-ea23e30b3421', '詠燭二首 一', '詠燭二首 一', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["燄聽風來動，花開不待春。","鎮下千行淚，非是爲思人。"]', '["燄听风来动，花开不待春。","鎮下千行泪，非是爲思人。"]', '诗', 'shi', '', NULL, '詠燭二首 一 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3fd8880-154d-479b-a852-c5f31ad5463e', '詠燭二首 二', '詠燭二首 二', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["九龍蟠燄動，四照逐花生。","即此流高殿，堪持待月明。"]', '["九龙蟠燄动，四照逐花生。","即此流高殿，堪持待月明。"]', '诗', 'shi', '', NULL, '詠燭二首 二 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f79db59-87f2-4b64-9605-be330724d4de', '詠弓', '詠弓', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["上弦明月半，激箭流星遠。","落雁帶書驚，啼猿映枝轉。"]', '["上弦明月半，激箭流星远。","落雁带书驚，啼猿映枝轉。"]', '诗', 'shi', '', NULL, '詠弓 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c353940d-4bbc-4420-83bf-07cb4606d35f', '賦得早雁出雲鳴', '賦得早雁出云鳴', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["初秋玉露清，早雁出空鳴。","隔雲時亂影，因風乍含聲。"]', '["初秋玉露清，早雁出空鳴。","隔云时亂影，因风乍含声。"]', '诗', 'shi', '', NULL, '賦得早雁出雲鳴 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e00858-8361-4f48-9e95-d0353a54ab49', '賦得臨池柳', '賦得臨池柳', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["岸曲絲陰聚，波移帶影疎。","還將眉裏翠，來就鏡中舒。"]', '["岸曲絲陰聚，波移带影疎。","還將眉裏翠，来就镜中舒。"]', '诗', 'shi', '', NULL, '賦得臨池柳 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d340ad23-8f26-4ee8-9873-8b044a6f158b', '賦得臨池竹', '賦得臨池竹', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["貞條障曲砌，翠葉貫寒霜。","拂牖分龍影，臨池待鳳翔。"]', '["貞條障曲砌，翠葉貫寒霜。","拂牖分龙影，臨池待鳳翔。"]', '诗', 'shi', '', NULL, '賦得臨池竹 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('487805d3-fe67-46d9-912d-29587a2cb1c5', '賦得弱柳鳴秋蟬', '賦得弱柳鳴秋蟬', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["散影玉階柳，含翠隱鳴蟬。","微形藏葉裏，亂響出風前。"]', '["散影玉階柳，含翠隐鳴蟬。","微形藏葉裏，亂响出风前。"]', '诗', 'shi', '', NULL, '賦得弱柳鳴秋蟬 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edabeb38-248a-4bc6-a4f3-5dcdf340729c', '探得李', '探得李', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["盤根直盈渚，交幹橫倚天。","舒華光四海，卷葉蔭三川。"]', '["盤根直盈渚，交幹橫倚天。","舒华光四海，卷葉蔭三川。"]', '诗', 'shi', '', NULL, '探得李 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbeb0337-1af4-4987-87a7-34bb9e79d812', '詠小山', '詠小山', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["近谷交縈橤，遙峰對出蓮。","徑細無全磴，松小未含煙。"]', '["近谷交縈橤，遙峰对出蓮。","徑細無全磴，松小未含煙。"]', '诗', 'shi', '', NULL, '詠小山 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5737750c-bf61-45a3-b38e-44bd6038b425', '賜蕭瑀', '賜蕭瑀', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["疾風知勁草，板蕩識誠臣。","勇夫安識義，智者必懷仁。"]', '["疾风知勁草，板蕩識誠臣。","勇夫安識義，智者必懷仁。"]', '诗', 'shi', '', NULL, '賜蕭瑀 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('291dd1f7-f61e-42b0-bb46-a8b28f9a8ffd', '賜房玄齡', '賜房玄齡', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["太液仙舟迥，西園隱上才。","未曉征車度，雞鳴關早開。"]', '["太液仙舟迥，西园隐上才。","未晓征车度，雞鳴关早开。"]', '诗', 'shi', '', NULL, '賜房玄齡 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('297cc055-e94c-41a9-bdfb-2cbfef8cae83', '遼東山夜臨秋', '遼东山夜臨秋', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["煙生遙岸隱，月落半崖陰。","連山驚鳥亂，隔岫斷猿吟。"]', '["煙生遙岸隐，月落半崖陰。","連山驚鸟亂，隔岫斷猿吟。"]', '诗', 'shi', '', NULL, '遼東山夜臨秋 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fcbec86-3e3e-4250-ae58-47b567af7e8e', '賜魏徵詩', '賜魏徵诗', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["醽醁勝蘭生，翠濤過玉䪥。","千日醉不醒，十年味不敗。"]', '["醽醁勝蘭生，翠濤過玉䪥。","千日醉不醒，十年味不敗。"]', '诗', 'shi', '', NULL, '賜魏徵詩 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2685a1-fc35-4238-87ee-9f27fd58432a', '兩儀殿賦柏梁體', '兩儀殿賦柏梁體', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["絕域降附天下平，八表無事悅聖情。","雲披霧斂天地明，登封日觀禪云亭。","太常具禮方告成。"]', '["絕域降附天下平，八表無事悅聖情。","云披霧斂天地明，登封日观禪云亭。","太常具禮方告成。"]', '诗', 'shi', '', NULL, '兩儀殿賦柏梁體 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('861c1378-8568-4606-8e50-e0b54d194c5e', '句', '句', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["雪恥酬百王，除兇報千古。","昔乘匹馬去，今驅萬乘來。","近日毛雖暖聞弦心已驚。"]', '["雪恥酬百王，除兇報千古。","昔乘匹马去，今驱万乘来。","近日毛雖暖闻弦心已驚。"]', '诗', 'shi', '', NULL, '句 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f99f99d1-0379-4ce5-a570-90e6b5db19b4', '太子納妃太平公主出降', '太子納妃太平公主出降', '1701410c-07da-42a3-b2fb-7b1e407d7d52', '唐', '["龍樓光曙景，魯館啓朝扉。","豔日濃妝影，低星降婺輝。","玉庭浮瑞色，銀牓藻祥徽。","雲轉花縈蓋，霞飄葉綴旂。","雕軒回翠陌，寶駕歸丹殿。","鳴珠佩曉衣，鏤璧輪開扇。","華冠列綺筵，蘭醑申芳宴。","環階鳳樂陳，玳席珍羞薦。","蝶舞袖香新，歌分落素塵。","歡凝歡懿戚，慶叶慶初姻。","暑闌炎氣息，涼早吹疎頻。","方期六合泰，共賞萬年春。"]', '["龙楼光曙景，魯館啓朝扉。","豔日濃妝影，低星降婺輝。","玉庭浮瑞色，銀牓藻祥徽。","云轉花縈蓋，霞飄葉綴旂。","雕軒回翠陌，寶駕归丹殿。","鳴珠佩晓衣，鏤璧輪开扇。","华冠列綺筵，蘭醑申芳宴。","环階鳳乐陳，玳席珍羞薦。","蝶舞袖香新，歌分落素塵。","歡凝歡懿戚，慶叶慶初姻。","暑闌炎氣息，涼早吹疎頻。","方期六合泰，共賞万年春。"]', '诗', 'shi', '', NULL, '太子納妃太平公主出降 高宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f971131c-5b36-4888-9f4e-6e9410adf659', '七夕宴懸圃二首 一', '七夕宴懸圃二首 一', '1701410c-07da-42a3-b2fb-7b1e407d7d52', '唐', '["羽蓋飛天漢，鳳駕越層巒。","俱歎三秋阻，共敍一宵歡。","璜虧夜月落，靨碎曉星殘。","誰能重操杼，纖手濯清瀾。"]', '["羽蓋飞天漢，鳳駕越層巒。","俱歎三秋阻，共敍一宵歡。","璜虧夜月落，靨碎晓星殘。","誰能重操杼，纖手濯清瀾。"]', '诗', 'shi', '', NULL, '七夕宴懸圃二首 一 高宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('792e7017-3954-4a3b-a167-e183f17ca707', '七夕宴懸圃二首 二', '七夕宴懸圃二首 二', '1701410c-07da-42a3-b2fb-7b1e407d7d52', '唐', '["霓裳轉雲路，鳳駕儼天潢。","虧星凋夜靨，殘月落朝璜。","促歡今夕促，長離別後長。","輕梭聊駐織，掩淚獨悲傷。"]', '["霓裳轉云路，鳳駕儼天潢。","虧星凋夜靨，殘月落朝璜。","促歡今夕促，长離別後长。","轻梭聊駐织，掩泪独悲傷。"]', '诗', 'shi', '', NULL, '七夕宴懸圃二首 二 高宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca84f1d3-1494-4add-a44d-6ccd8f6484a2', '過溫湯', '過溫湯', '1701410c-07da-42a3-b2fb-7b1e407d7d52', '唐', '["溫渚停仙蹕，豐郊駐曉旌。","路曲迴輸影，巖虛傳漏聲。","暖溜驚湍駛，寒空碧霧輕。","林黃疎葉下，野白曙霜明。","眺聽良無已，煙霞斷續生。"]', '["溫渚停仙蹕，豐郊駐晓旌。","路曲迴輸影，巖虛傳漏声。","暖溜驚湍駛，寒空碧霧轻。","林黄疎葉下，野白曙霜明。","眺听良無已，煙霞斷續生。"]', '诗', 'shi', '', NULL, '過溫湯 高宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('694314d7-c1d5-4b3b-9e0d-b355697cced3', '九月九日', '九月九日', '1701410c-07da-42a3-b2fb-7b1e407d7d52', '唐', '["端居臨玉扆，初律啓金商。","鳳闕澄秋色，龍闈引夕涼。","野淨山氣斂，林疎風露長。","砌蘭虧半影，巖桂發全香。","滿蓋荷凋翠，圓花菊散黃。","揮鞭爭電烈，飛羽亂星光。","柳空穿石碎，弦虛側月張。","怯猿啼落岫，驚雁斷分行。","斜輪低夕景，歸斾擁通莊。"]', '["端居臨玉扆，初律啓金商。","鳳闕澄秋色，龙闈引夕涼。","野淨山氣斂，林疎风露长。","砌蘭虧半影，巖桂發全香。","满蓋荷凋翠，圓花菊散黄。","揮鞭爭電烈，飞羽亂星光。","柳空穿石碎，弦虛側月張。","怯猿啼落岫，驚雁斷分行。","斜輪低夕景，归斾擁通莊。"]', '诗', 'shi', '', NULL, '九月九日 高宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f442360-9ecd-40ad-9b97-8afef21e2a85', '謁慈恩寺題奘法師房', '謁慈恩寺題奘法師房', '1701410c-07da-42a3-b2fb-7b1e407d7d52', '唐', '["停軒觀福殿，遊目眺皇畿。","法輪含日轉，花蓋接雲飛。","翠煙香綺閣，丹霞光寶衣。","幡虹遙合彩，定水迥分暉。","蕭然登十地，自得會三歸。"]', '["停軒观福殿，游目眺皇畿。","法輪含日轉，花蓋接云飞。","翠煙香綺閣，丹霞光寶衣。","幡虹遙合彩，定水迥分暉。","蕭然登十地，自得會三归。"]', '诗', 'shi', '', NULL, '謁慈恩寺題奘法師房 高宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a91f55d-4f60-45b4-b9e2-36ddfd8ac342', '謁大慈恩寺', '謁大慈恩寺', '1701410c-07da-42a3-b2fb-7b1e407d7d52', '唐', '["日宮開萬仞，月殿聳千尋。","花蓋飛團影，幡虹曳曲陰。","綺霞遙籠帳，叢珠細網林。","寥廓煙雲表，超然物外心。"]', '["日宮开万仞，月殿聳千尋。","花蓋飞團影，幡虹曳曲陰。","綺霞遙籠帳，叢珠細網林。","寥廓煙云表，超然物外心。"]', '诗', 'shi', '', NULL, '謁大慈恩寺 高宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('527b27aa-af81-41ed-b7f4-31c4eb7bb57f', '守歲', '守歲', '1701410c-07da-42a3-b2fb-7b1e407d7d52', '唐', '["今宵冬律盡，來朝麗景新。","花餘凝地雪，條含煖吹分。","綬吐芽猶嫩，冰□已鏤津。","薄紅梅色冷，淺綠柳輕春。","送迎交兩節，暄寒變一辰。"]', '["今宵冬律尽，来朝丽景新。","花餘凝地雪，條含煖吹分。","綬吐芽猶嫩，冰□已鏤津。","薄紅梅色冷，淺綠柳轻春。","送迎交兩節，暄寒变一辰。"]', '诗', 'shi', '', NULL, '守歲 高宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('589c213c-6793-4ba6-b0d8-ef674ea4a544', '咸亨殿宴近臣諸親柏梁體', '咸亨殿宴近臣諸親柏梁體', '1701410c-07da-42a3-b2fb-7b1e407d7d52', '唐', '["屏欲除奢政返淳。"]', '["屏欲除奢政返淳。"]', '诗', 'shi', '', NULL, '咸亨殿宴近臣諸親柏梁體 高宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('103a8266-2d76-413d-9cde-e32f15f47d4c', '九月九日幸臨渭亭登高得秋字', '九月九日幸臨渭亭登高得秋字', 'ba551bb1-878d-41f6-8577-a41e16fff688', '唐', '["九月正乘秋，三杯興已周。","泛桂迎尊滿，吹花向酒浮。","長房萸早熟，彭澤菊初收。"]', '["九月正乘秋，三杯兴已周。","泛桂迎尊满，吹花向酒浮。","长房萸早熟，彭澤菊初收。"]', '诗', 'shi', '', NULL, '九月九日幸臨渭亭登高得秋字 中宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4305274-656b-4379-a658-eed9909fbaa2', '登驪山高頂寓目', '登驪山高頂寓目', 'ba551bb1-878d-41f6-8577-a41e16fff688', '唐', '["四郊秦漢國，八水帝王都。","閶闔雄里閈，城闕壯規模。","貫渭稱天邑，含岐實奧區。","金門披玉館，因此識皇圖。"]', '["四郊秦漢国，八水帝王都。","閶闔雄里閈，城闕壯規模。","貫渭稱天邑，含岐實奧區。","金门披玉館，因此識皇圖。"]', '诗', 'shi', '', NULL, '登驪山高頂寓目 中宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('651e8254-c709-49e8-86fd-0153306ff555', '幸秦始皇陵', '幸秦始皇陵', 'ba551bb1-878d-41f6-8577-a41e16fff688', '唐', '["眷言君失德，驪邑想秦餘。","政煩方改篆，愚俗乃焚書。","阿房久已滅，閣道遂成墟。","欲厭東南氣，翻傷掩鮑車。"]', '["眷言君失德，驪邑想秦餘。","政煩方改篆，愚俗乃焚书。","阿房久已滅，閣道遂成墟。","欲厭东南氣，翻傷掩鲍车。"]', '诗', 'shi', '', NULL, '幸秦始皇陵 中宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fe88983-0ad0-490b-b08a-8c359af920a3', '立春日遊苑迎春', '立春日游苑迎春', 'ba551bb1-878d-41f6-8577-a41e16fff688', '唐', '["神皐福地三秦邑，玉臺金闕九仙家。","寒光猶戀甘泉樹，淑景偏臨建始花。","綵蝶黃鸎未歌舞，梅香柳色已矜誇。","迎春正啓流霞席，暫囑曦輪勿遽斜。"]', '["神皐福地三秦邑，玉台金闕九仙家。","寒光猶戀甘泉樹，淑景偏臨建始花。","綵蝶黄鸎未歌舞，梅香柳色已矜誇。","迎春正啓流霞席，暫囑曦輪勿遽斜。"]', '诗', 'shi', '', NULL, '立春日遊苑迎春 中宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49359d18-613c-4aa0-8836-e2253b88d772', '十月誕辰內殿宴羣臣效柏梁體聯句', '十月誕辰內殿宴羣臣效柏梁體聯句', 'ba551bb1-878d-41f6-8577-a41e16fff688', '唐', '["潤色鴻業寄賢才，叨居右弼媿鹽梅。","運籌帷幄荷時來，職掌圖籍濫蓬萊。","兩司謬忝謝鍾裴，禮樂銓管效涓埃。","陳師振旅清九垓，欣承顧問侍天杯。","銜恩獻壽梁柏臺，黃縑青簡奉康哉。","鯫生侍從忝王枚，右掖司言實不才。","宗伯秩禮天地開，帝歌難續仰昭回。","微臣捧日變寒灰，遠慙班左媿遊陪。"]', '["潤色鴻業寄賢才，叨居右弼媿鹽梅。","運籌帷幄荷时来，職掌圖籍濫蓬萊。","兩司謬忝謝鍾裴，禮乐銓管效涓埃。","陳師振旅清九垓，欣承顧问侍天杯。","銜恩獻壽梁柏台，黄縑青簡奉康哉。","鯫生侍從忝王枚，右掖司言實不才。","宗伯秩禮天地开，帝歌难續仰昭回。","微臣捧日变寒灰，远慙班左媿游陪。"]', '诗', 'shi', '', NULL, '十月誕辰內殿宴羣臣效柏梁體聯句 中宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a60c13-e4f4-4653-8262-70e474cc636a', '景龍四年正月五日移仗蓬萊宮御大明殿會吐蕃騎馬之戲因重爲柏梁體聯句', '景龙四年正月五日移仗蓬萊宮御大明殿會吐蕃騎马之戲因重爲柏梁體聯句', 'ba551bb1-878d-41f6-8577-a41e16fff688', '唐', '["大明御宇臨萬方，顧慙內政翊陶唐。","鸞鳴鳳舞向平陽，秦樓魯館沐恩光。","無心爲子輒求郎，雄才七步謝陳王。","當熊讓輦媿前芳，再司銓筦恩可忘。","文江學海思濟航，萬邦考績臣所詳。","著作不休出中腸，權豪屏迹肅嚴霜。","鑄鼎開岳造明堂，玉醴由來獻壽觴。"]', '["大明御宇臨万方，顧慙內政翊陶唐。","鸾鳴鳳舞向平陽，秦楼魯館沐恩光。","無心爲子輒求郎，雄才七步謝陳王。","當熊讓輦媿前芳，再司銓筦恩可忘。","文江学海思濟航，万邦考績臣所詳。","著作不休出中腸，權豪屏迹肅嚴霜。","鑄鼎开岳造明堂，玉醴由来獻壽觴。"]', '诗', 'shi', '', NULL, '景龍四年正月五日移仗蓬萊宮御大明殿會吐蕃騎馬之戲因重爲柏梁體聯句 中宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3da0d066-be3c-427c-ad15-5b6c38d3ccf6', '石淙', '石淙', 'ba551bb1-878d-41f6-8577-a41e16fff688', '唐', '["三陽本是標靈紀，二室由來獨擅名。","霞衣霞錦千般狀，雲峰雲岫百重生。","水炫珠光遇泉客，巖懸石鏡厭山精。","永願乾坤符睿算，長居膝下屬歡情。"]', '["三陽本是標靈紀，二室由来独擅名。","霞衣霞錦千般狀，云峰云岫百重生。","水炫珠光遇泉客，巖懸石镜厭山精。","永願乾坤符睿算，长居膝下屬歡情。"]', '诗', 'shi', '', NULL, '石淙 中宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8c1489d-d98c-49bc-a2f6-6d8449664e26', '石淙', '石淙', '512b79d1-73c4-4fff-91bd-fc9af6b02974', '唐', '["奇峰嶾嶙箕山北，秀崿岹嶢嵩鎮南。","地首地肺何曾擬，天目天台倍覺慙。","樹影蒙蘢鄣疊岫，波深洶湧落懸潭。","□願紫宸居得一，永欣丹扆御通三。"]', '["奇峰嶾嶙箕山北，秀崿岹嶢嵩鎮南。","地首地肺何曾擬，天目天台倍覺慙。","樹影蒙蘢鄣叠岫，波深洶湧落懸潭。","□願紫宸居得一，永欣丹扆御通三。"]', '诗', 'shi', '', NULL, '石淙 睿宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0337427-89fa-44ca-8f08-6f989572feb6', '過晉陽宮', '過晉陽宮', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["緬想封唐處，實惟建國初。","俯察伊晉野，仰觀乃參虛。","井邑龍斯躍，城池鳳翔餘。","林塘猶沛澤，臺榭宛舊居。","運革祚中否，時遷命茲符。","顧循承丕構，怵惕多憂虞。","尚恐威不逮，復慮化未孚。","豈徒勞轍迹，所期訓戎車。","習俗問黎人，親巡慰里閭。","永言念成功，頌德臨康衢。","長懷經綸日，歎息履庭隅。","艱難安可忘，欲去良踟躕。"]', '["緬想封唐处，實惟建国初。","俯察伊晉野，仰观乃參虛。","井邑龙斯躍，城池鳳翔餘。","林塘猶沛澤，台榭宛旧居。","運革祚中否，时遷命茲符。","顧循承丕構，怵惕多憂虞。","尚恐威不逮，复慮化未孚。","豈徒勞轍迹，所期訓戎车。","習俗问黎人，親巡慰里閭。","永言念成功，頌德臨康衢。","长懷經綸日，歎息履庭隅。","艱难安可忘，欲去良踟躕。"]', '诗', 'shi', '', NULL, '過晉陽宮 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aaa788e-05f6-4bdf-acb9-773e3a5fa4d9', '行次成皋途經先聖擒建德之所緬思功業感而賦詩', '行次成皋途經先聖擒建德之所緬思功業感而賦诗', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["有隋政昏虐，羣雄已交爭。","先聖按劒起，叱咤風雲生。","飲馬河洛竭，作氣嵩華驚。","克敵睿圖就，擒俘帝道亨。","顧慙嗣寶曆，恭承天下平。","幸過翦鯨地，感慕神且英。"]', '["有隋政昏虐，羣雄已交爭。","先聖按劒起，叱咤风云生。","饮马河洛竭，作氣嵩华驚。","克敵睿圖就，擒俘帝道亨。","顧慙嗣寶曆，恭承天下平。","幸過翦鯨地，感慕神且英。"]', '诗', 'shi', '', NULL, '行次成皋途經先聖擒建德之所緬思功業感而賦詩 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a2266dd-ed4e-4168-8464-ec32d966daaa', '校獵義成喜逢大雪率題九韻以示羣官', '校獵義成喜逢大雪率題九韻以示羣官', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["弧矢威天下，旌旗遊近縣。","一面施鳥羅，三驅教人戰。","暮雲成積雪，曉色開行殿。","皓然原隰同，不覺林野變。","北風勇士馬，東日華組練。","觸地銀麞出，連山縞鹿見。","月兔落高矰，星狼下急箭。","既欣盈尺兆，復憶磻谿便。","歲豐將遇賢，俱荷皇天眷。"]', '["弧矢威天下，旌旗游近縣。","一面施鸟羅，三驱教人戰。","暮云成積雪，晓色开行殿。","皓然原隰同，不覺林野变。","北风勇士马，东日华組練。","觸地銀麞出，連山縞鹿见。","月兔落高矰，星狼下急箭。","既欣盈尺兆，复憶磻谿便。","歲豐將遇賢，俱荷皇天眷。"]', '诗', 'shi', '', NULL, '校獵義成喜逢大雪率題九韻以示羣官 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f00c11-e79e-4fe8-9890-1679f17a2dae', '賜諸州刺史以題座右', '賜諸州刺史以題座右', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["眷言思共理，鑑夢想維良。","猗歟此推擇，聲績著周行。","賢能既俟進，黎獻實佇康。","視人當如子，愛人亦如傷。","講學試誦論，阡陌勸耕桑。","虛譽不可飾，清知不可忘。","求名迹易見，安貞德自彰。","訟獄必以情，教民貴有常。","恤惸且存老，撫弱復綏強。","勉哉各祗命，知予眷萬方。"]', '["眷言思共理，鑑梦想維良。","猗歟此推擇，声績著周行。","賢能既俟進，黎獻實佇康。","視人當如子，愛人亦如傷。","講学試誦論，阡陌勸耕桑。","虛譽不可飾，清知不可忘。","求名迹易见，安貞德自彰。","訟獄必以情，教民貴有常。","恤惸且存老，撫弱复綏強。","勉哉各祗命，知予眷万方。"]', '诗', 'shi', '', NULL, '賜諸州刺史以題座右 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b792850c-9098-4cd8-821c-6a8a303ae01a', '送忠州太守康昭遠等', '送忠州太守康昭远等', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["端拱臨中樞，緬懷共予理。","不有臺閣英，孰振循良美。","分符侯甸內，拜手明庭裏。","誓節期飲冰，調人方導水。","嘉聲馳九牧，惠化光千祀。","時雨侔昔賢，芳猷貫前史。","佇爾頌中和，吾將令卿士。"]', '["端拱臨中樞，緬懷共予理。","不有台閣英，孰振循良美。","分符侯甸內，拜手明庭裏。","誓節期饮冰，調人方導水。","嘉声驰九牧，惠化光千祀。","时雨侔昔賢，芳猷貫前史。","佇爾頌中和，吾將令卿士。"]', '诗', 'shi', '', NULL, '送忠州太守康昭遠等 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a492586e-5029-4c46-8d6e-1915e18b9d3a', '送李邕之任滑臺', '送李邕之任滑台', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["漢家重東郡，宛彼白馬津。","黎庶既蕃殖，臨之勞近臣。","遠別初首路，今行方及春。","課成應第一，良牧爾當仁。"]', '["漢家重东郡，宛彼白马津。","黎庶既蕃殖，臨之勞近臣。","远別初首路，今行方及春。","課成應第一，良牧爾當仁。"]', '诗', 'shi', '', NULL, '送李邕之任滑臺 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8784b5fa-245f-4a1f-acc1-ca891154180e', '端午三殿宴羣臣探得神字', '端午三殿宴羣臣探得神字', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["五月符天數，五音調夏鈞。","舊來傳五日，無事不稱神。","穴枕通靈氣，長絲續命人。","四時花競巧，九子糉爭新。","方殿臨華節，圓宮宴雅臣。","進對一言重，遒文六義陳。","股肱良足詠，風化可還淳。"]', '["五月符天數，五音調夏鈞。","旧来傳五日，無事不稱神。","穴枕通靈氣，长絲續命人。","四时花競巧，九子糉爭新。","方殿臨华節，圓宮宴雅臣。","進对一言重，遒文六義陳。","股肱良足詠，风化可還淳。"]', '诗', 'shi', '', NULL, '端午三殿宴羣臣探得神字 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('305ed419-7cad-4659-b393-9b52aafa375f', '溫湯對雪', '溫湯对雪', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["北風吹同雲，同雲飛白雪。","白雪乍迴散，同雲何慘烈。","未見溫泉冰，寧知火井滅。","表瑞良在茲，庶幾可怡悅。"]', '["北风吹同云，同云飞白雪。","白雪乍迴散，同云何慘烈。","未见溫泉冰，寧知火井滅。","表瑞良在茲，庶幾可怡悅。"]', '诗', 'shi', '', NULL, '溫湯對雪 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fff5496-d24c-48c6-9c61-0d8925b663fe', '登蒲州逍遙樓', '登蒲州逍遙楼', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["長榆息烽火，高柳靜風塵。","卜征巡九洛，展豫出三秦。","昔是潛龍地，今爲上理辰。","時平乘道泰，聊賞遇年春。","黃河分地絡，飛觀接天津。","一覽遺芳翰，千載肅如神。"]', '["长榆息烽火，高柳静风塵。","卜征巡九洛，展豫出三秦。","昔是潛龙地，今爲上理辰。","时平乘道泰，聊賞遇年春。","黄河分地絡，飞观接天津。","一覽遺芳翰，千載肅如神。"]', '诗', 'shi', '', NULL, '登蒲州逍遙樓 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1669d597-4c37-4897-b5f8-a15eedd8cdf0', '經河上公廟', '經河上公廟', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["昔聞有耆叟，河上獨遺榮。","跡與塵嚻隔，心將道德幷。","詎以天地累，寧爲寵辱驚。","矯然翔寥廓，如何屈堅貞。","玄玄妙門啓，肅肅祠宇清。","冥漠無先後，那能紀姓名。"]', '["昔闻有耆叟，河上独遺榮。","跡與塵嚻隔，心將道德幷。","詎以天地累，寧爲寵辱驚。","矯然翔寥廓，如何屈堅貞。","玄玄妙门啓，肅肅祠宇清。","冥漠無先後，那能紀姓名。"]', '诗', 'shi', '', NULL, '經河上公廟 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ae53f2c-48fa-464c-8453-de7b2434c716', '過王濬暮', '過王濬暮', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["吳國分牛斗，晉室命龍驤。","受任敵已滅，策勳名不彰。","居美未盡善，矜功徒自傷。","長戟今何在？孤墳此路傍。","不觀松柏茂，空餘荆棘場。","歎嗟懸劒隴，誰識夢刀祥。"]', '["吳国分牛斗，晉室命龙驤。","受任敵已滅，策勳名不彰。","居美未尽善，矜功徒自傷。","长戟今何在？孤墳此路傍。","不观松柏茂，空餘荆棘場。","歎嗟懸劒隴，誰識梦刀祥。"]', '诗', 'shi', '', NULL, '過王濬暮 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4b72624-5f7c-4885-940b-5c1812023ead', '初入秦川路逢寒食', '初入秦川路逢寒食', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["洛陽芳樹映天津，灞岸垂楊窣地新。","直爲經過行處樂，不知虛度兩京春。","去年餘閏今春早，曙色和風著花草。","可憐寒食與清明，光輝幷在長安道。","自從關路入秦川，爭道何人不戲鞭。","公子途中妨蹴踘，佳人馬上廢鞦韆。","渭水長橋今欲渡，蔥蔥漸見新豐樹。","遠看驪岫入雲霄，預想湯池起煙霧。","煙霧氛氳水殿開，暫拂香輪歸去來。","今歲清明行已晚，明年寒食更相陪。"]', '["洛陽芳樹映天津，灞岸垂楊窣地新。","直爲經過行处乐，不知虛度兩京春。","去年餘閏今春早，曙色和风著花草。","可怜寒食與清明，光輝幷在长安道。","自從关路入秦川，爭道何人不戲鞭。","公子途中妨蹴踘，佳人马上廢鞦韆。","渭水长橋今欲渡，蔥蔥漸见新豐樹。","远看驪岫入云霄，預想湯池起煙霧。","煙霧氛氳水殿开，暫拂香輪归去来。","今歲清明行已晚，明年寒食更相陪。"]', '诗', 'shi', '', NULL, '初入秦川路逢寒食 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2465f80e-c739-41c6-b446-80aa00bed183', '春臺望', '春台望', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["暇景屬三春，高臺聊四望。","目極千里際，山川一何壯。","太華見重巖，終南分疊嶂。","郊原紛綺錯，參差多異狀。","佳氣滿通溝，遲步入綺樓。","初鸎一一鳴紅樹，歸雁雙雙去綠洲。","太液池中下黃鶴，昆明水上映牽牛。","聞道漢家全盛日，別館離宮趣非一。","甘泉逶迤亘明光，五柞連延接未央。","周廬徼道縱橫轉，飛閣迴軒左右長。","須念作勞居者逸，勿言我後焉能恤。","爲想雄豪壯柏梁，何如儉陋卑茅室。","陽烏黯黯向山沈，夕鳥喧喧入上林。","薄暮賞餘回步輦，還念中人罷百金。"]', '["暇景屬三春，高台聊四望。","目極千里際，山川一何壯。","太华见重巖，終南分叠嶂。","郊原紛綺錯，參差多異狀。","佳氣满通溝，遲步入綺楼。","初鸎一一鳴紅樹，归雁雙雙去綠洲。","太液池中下黄鹤，昆明水上映牽牛。","闻道漢家全盛日，別館離宮趣非一。","甘泉逶迤亘明光，五柞連延接未央。","周廬徼道縱橫轉，飞閣迴軒左右长。","須念作勞居者逸，勿言我後焉能恤。","爲想雄豪壯柏梁，何如儉陋卑茅室。","陽烏黯黯向山沈，夕鸟喧喧入上林。","薄暮賞餘回步輦，還念中人罷百金。"]', '诗', 'shi', '', NULL, '春臺望 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71c6c90b-67c3-451e-9463-23cd78cb05aa', '過大哥宅探得歌字韻', '過大哥宅探得歌字韻', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["魯衛情先重，親賢愛轉多。","冕旒豐暇日，乘景暫經過。","戚里申高宴，平臺奏雅歌。","復尋爲善樂，方驗保山河。"]', '["魯衛情先重，親賢愛轉多。","冕旒豐暇日，乘景暫經過。","戚里申高宴，平台奏雅歌。","复尋爲善乐，方驗保山河。"]', '诗', 'shi', '', NULL, '過大哥宅探得歌字韻 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31f91bce-39c0-4eb6-b905-c344eb337ecf', '同玉真公主過大哥山池', '同玉真公主過大哥山池', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["地有招賢處，人傳樂善名。","鶩池臨九達，龍岫對層城。","桂月先秋冷，蘋風向晚清。","鳳樓遙可見，彷彿玉簫聲。"]', '["地有招賢处，人傳乐善名。","鶩池臨九達，龙岫对層城。","桂月先秋冷，蘋风向晚清。","鳳楼遙可见，彷彿玉簫声。"]', '诗', 'shi', '', NULL, '同玉真公主過大哥山池 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1824eb8-4e2e-4d53-9a33-e1dcfe7d1c73', '經鄒魯祭孔子而歎之', '經鄒魯祭孔子而歎之', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["夫子何爲者？栖栖一代中。","地猶鄹氏邑，宅即魯王宮。","歎鳳嗟身否，傷麟怨道窮。","今看兩楹奠，當與夢時同。"]', '["夫子何爲者？栖栖一代中。","地猶鄹氏邑，宅即魯王宮。","歎鳳嗟身否，傷麟怨道窮。","今看兩楹奠，當與梦时同。"]', '诗', 'shi', '', NULL, '經鄒魯祭孔子而歎之 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed5ce508-2df4-4ef2-a6a0-5b8586766d6f', '惟此溫泉是稱愈疾豈予獨受其福思與兆人共之乘暇巡遊乃言其志', '惟此溫泉是稱愈疾豈予独受其福思與兆人共之乘暇巡游乃言其志', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["桂殿與山連，蘭湯湧自然。","陰崖含秀色，溫谷吐潺湲。","績爲蠲邪著，功因養正宣。","願言將億兆，同此共昌延。"]', '["桂殿與山連，蘭湯湧自然。","陰崖含秀色，溫谷吐潺湲。","績爲蠲邪著，功因養正宣。","願言將億兆，同此共昌延。"]', '诗', 'shi', '', NULL, '惟此溫泉是稱愈疾豈予獨受其福思與兆人共之乘暇巡遊乃言其志 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09b3b3e9-1c6d-4c01-a400-da5d81367407', '旋師喜捷', '旋師喜捷', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["邊服胡塵起，長安漢將飛。","龍蛇開陣法，貔虎振軍威。","詐虜腦塗地，征夫血染衣。","今朝書奏入，明日凱歌歸。"]', '["邊服胡塵起，长安漢將飞。","龙蛇开陣法，貔虎振軍威。","詐虜腦塗地，征夫血染衣。","今朝书奏入，明日凱歌归。"]', '诗', 'shi', '', NULL, '旋師喜捷 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e850ef1a-ddc7-4d29-a946-5fa8f1b32d7b', '過老子廟', '過老子廟', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["仙居懷聖德，靈廟肅神心。","草合人蹤斷，塵濃鳥跡深。","流沙丹竈沒，關路紫煙沈。","獨傷千載後，空餘松柏林。"]', '["仙居懷聖德，靈廟肅神心。","草合人蹤斷，塵濃鸟跡深。","流沙丹竈沒，关路紫煙沈。","独傷千載後，空餘松柏林。"]', '诗', 'shi', '', NULL, '過老子廟 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5675d954-3da8-4071-be97-da4c66f4675a', '途次陝州', '途次陝州', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["境出三秦外，途分二陝中。","山川入虞虢，風俗限西東。","樹古棠陰在，耕餘讓畔空。","鳴笳從此去，行見洛陽宮。"]', '["境出三秦外，途分二陝中。","山川入虞虢，风俗限西东。","樹古棠陰在，耕餘讓畔空。","鳴笳從此去，行见洛陽宮。"]', '诗', 'shi', '', NULL, '途次陝州 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cdf7e65-ec12-41de-9474-7ff1eeacd5f3', '野次喜雪', '野次喜雪', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["拂曙闢行宮，寒皋野望通。","繁雲低遠岫，飛雪舞長空。","賦象恆依物，縈迴屢逐風。","爲知勤恤意，先此示年豐。"]', '["拂曙闢行宮，寒皋野望通。","繁云低远岫，飞雪舞长空。","賦象恆依物，縈迴屢逐风。","爲知勤恤意，先此示年豐。"]', '诗', 'shi', '', NULL, '野次喜雪 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('535734bd-4603-4944-a44b-0f3ff9ee4da4', '送賀知章歸四明', '送賀知章归四明', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["遺榮期入道，辭老竟抽簪。","豈不惜賢達，其如高尚心。","寰中得祕要，方外散幽襟。","獨有青門餞，羣僚悵別深。"]', '["遺榮期入道，辞老竟抽簪。","豈不惜賢達，其如高尚心。","寰中得祕要，方外散幽襟。","独有青门餞，羣僚悵別深。"]', '诗', 'shi', '', NULL, '送賀知章歸四明 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3737773-2dc5-436c-aa3e-39f324aaef16', '軒遊宮十五夜', '軒游宮十五夜', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["行邁離秦國，巡方赴洛師。","路逢三五夜，春色暗中期。","關外長河轉，宮中淑氣遲。","歌鐘對明月，不減舊遊時。"]', '["行邁離秦国，巡方赴洛師。","路逢三五夜，春色暗中期。","关外长河轉，宮中淑氣遲。","歌鐘对明月，不減旧游时。"]', '诗', 'shi', '', NULL, '軒遊宮十五夜 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fe183cd-7771-4bb4-81d1-0d3ee507c647', '觀拔河俗戲', '观拔河俗戲', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["壯徒恆賈勇，拔拒抵長河。","欲練英雄志，須明勝負多。","譟齊山岌嶪，氣作水騰波。","預期年歲稔，先此樂時和。"]', '["壯徒恆賈勇，拔拒抵长河。","欲練英雄志，須明勝負多。","譟齊山岌嶪，氣作水腾波。","預期年歲稔，先此乐时和。"]', '诗', 'shi', '', NULL, '觀拔河俗戲 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('865bf66e-c1ad-4fee-8ab0-45876065155a', '同劉晃喜雨', '同劉晃喜雨', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["節變寒初盡，時和氣已春。","繁雲先合寸，膏雨自依旬。","颯颯飛平野，霏霏靜暗塵。","懸知花葉意，朝夕望中新。"]', '["節变寒初尽，时和氣已春。","繁云先合寸，膏雨自依旬。","颯颯飞平野，霏霏静暗塵。","懸知花葉意，朝夕望中新。"]', '诗', 'shi', '', NULL, '同劉晃喜雨 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe3a7358-9350-44e1-b04d-637ed5425b50', '千秋節賜羣臣鏡', '千秋節賜羣臣镜', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["鑄得千秋鏡，光生百鍊金。","分將賜羣后，遇象見清心。","臺上冰華澈，窗中月影臨。","更銜長綬帶，留意感人深。"]', '["鑄得千秋镜，光生百鍊金。","分將賜羣后，遇象见清心。","台上冰华澈，窗中月影臨。","更銜长綬带，留意感人深。"]', '诗', 'shi', '', NULL, '千秋節賜羣臣鏡 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('612c3100-a4ee-4478-87d3-6499a58a4430', '賜道士鄧紫陽', '賜道士鄧紫陽', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["太乙三門訣，元君六甲符。","下傳金版術，上刻玉清書。","有美探真士，囊中得祕書。","自知三醮後，翊我滅殘胡。"]', '["太乙三门訣，元君六甲符。","下傳金版術，上刻玉清书。","有美探真士，囊中得祕书。","自知三醮後，翊我滅殘胡。"]', '诗', 'shi', '', NULL, '賜道士鄧紫陽 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1373b7fb-a34d-468f-8bc3-127bce69027e', '幸蜀西至劒門', '幸蜀西至劒门', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["劒閣橫雲峻，鑾輿出狩回。","翠屏千仞合，丹嶂五丁開。","灌木縈旗轉，仙雲拂馬來。","乘時方在德，嗟爾勒銘才。"]', '["劒閣橫云峻，鑾輿出狩回。","翠屏千仞合，丹嶂五丁开。","灌木縈旗轉，仙云拂马来。","乘时方在德，嗟爾勒銘才。"]', '诗', 'shi', '', NULL, '幸蜀西至劒門 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ea9b354-24bc-497a-a8fb-0e83e0a00c9f', '答司馬承禎上劒鏡', '答司马承禎上劒镜', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["寶照含天地，神劒合陰陽。","日月麗光景，星斗裁文章。","寫鑑表容質，佩服爲身防。","從茲一賞玩，永德保齡長。"]', '["寶照含天地，神劒合陰陽。","日月丽光景，星斗裁文章。","寫鑑表容質，佩服爲身防。","從茲一賞玩，永德保齡长。"]', '诗', 'shi', '', NULL, '答司馬承禎上劒鏡 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9cf7b72-41cc-4e86-a5ff-b3b142fc2f1f', '送趙法師還蜀因名山奠簡', '送趙法師還蜀因名山奠簡', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["道家奠靈簡，自昔仰神仙。","真子今將命，蒼生福可傳。","江山尋故國，城郭信依然。","二室遙相望，雲回洞裏天。"]', '["道家奠靈簡，自昔仰神仙。","真子今將命，蒼生福可傳。","江山尋故国，城郭信依然。","二室遙相望，云回洞裏天。"]', '诗', 'shi', '', NULL, '送趙法師還蜀因名山奠簡 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fec324a-a88c-4c65-ab64-8c6fda63294c', '送道士薛季昌還山', '送道士薛季昌還山', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["洞府修真客，衡陽念舊居。","將成金闕要，願奉玉清書。","雲路三天近，松溪萬籟虛。","猶期傳祕訣，來往候仙輿。"]', '["洞府修真客，衡陽念旧居。","將成金闕要，願奉玉清书。","云路三天近，松溪万籟虛。","猶期傳祕訣，来往候仙輿。"]', '诗', 'shi', '', NULL, '送道士薛季昌還山 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3175be79-7852-4d21-ae00-6e99046947d5', '送玄同真人李抱朴謁灊山仙祠', '送玄同真人李抱朴謁灊山仙祠', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["城闕天中近，蓬瀛海上遙。","歸期千載鶴，春至一來朝。","采藥逢三秀，餐霞臥九霄。","參同如有旨，金鼎待君燒。"]', '["城闕天中近，蓬瀛海上遙。","归期千載鹤，春至一来朝。","采藥逢三秀，餐霞臥九霄。","參同如有旨，金鼎待君燒。"]', '诗', 'shi', '', NULL, '送玄同真人李抱朴謁灊山仙祠 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b69a61f7-c412-4d23-9f4d-e33115184411', '春日出苑遊矚', '春日出苑游矚', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["三陽麗景早芳辰，四序佳園物候新。","梅花百樹障去路，垂柳千條暗回津。","鳥飛直爲驚風葉，魚沒都由怯岸人。","惟願聖主南山壽，何愁不賞萬年春。"]', '["三陽丽景早芳辰，四序佳园物候新。","梅花百樹障去路，垂柳千條暗回津。","鸟飞直爲驚风葉，鱼沒都由怯岸人。","惟願聖主南山壽，何愁不賞万年春。"]', '诗', 'shi', '', NULL, '春日出苑遊矚 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83a52b39-32c7-4394-b619-3ede125ed7fd', '春晚宴兩相及禮官麗正殿學士探得風字', '春晚宴兩相及禮官丽正殿学士探得风字', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["乾道運無窮，恆將人代工。","陰陽調曆象，禮樂報玄穹。","介胄清荒外，衣冠佐域中。","言談延國輔，詞賦引文雄。","野霽伊川綠，郊明鞏樹紅。","冕旒多暇景，詩酒會春風。"]', '["乾道運無窮，恆將人代工。","陰陽調曆象，禮乐報玄穹。","介胄清荒外，衣冠佐域中。","言談延国輔，词賦引文雄。","野霽伊川綠，郊明鞏樹紅。","冕旒多暇景，诗酒會春风。"]', '诗', 'shi', '', NULL, '春晚宴兩相及禮官麗正殿學士探得風字 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a42f0ea-06a9-4bb4-a71a-f4ba0485cb5f', '首夏花萼樓觀羣臣宴寧王山亭回樓下又申之以賞樂賦詩', '首夏花萼楼观羣臣宴寧王山亭回楼下又申之以賞乐賦诗', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["今年通閏月，入夏展春輝。","樓下風光晚，城隅宴賞歸。","九歌揚政要，六舞散朝衣。","天喜時相合，人和事不違。","禮中推意厚，樂處感心微。","別賞陽臺樂，前旬暮雨飛。"]', '["今年通閏月，入夏展春輝。","楼下风光晚，城隅宴賞归。","九歌揚政要，六舞散朝衣。","天喜时相合，人和事不違。","禮中推意厚，乐处感心微。","別賞陽台乐，前旬暮雨飞。"]', '诗', 'shi', '', NULL, '首夏花萼樓觀羣臣宴寧王山亭回樓下又申之以賞樂賦詩 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4db72c93-5036-478a-8ce9-bf6f87469198', '同二相已下羣官樂遊園宴', '同二相已下羣官乐游园宴', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["撰日巖廊暇，需雲宴樂初。","萬方朝玉帛，千品會簪裾。","地入南山近，城分北斗餘。","池塘垂柳密，原隰野花疎。","帟幕看逾暗，歌鐘聽自虛。","興闌歸騎轉，還奏弼違書。"]', '["撰日巖廊暇，需云宴乐初。","万方朝玉帛，千品會簪裾。","地入南山近，城分北斗餘。","池塘垂柳密，原隰野花疎。","帟幕看逾暗，歌鐘听自虛。","兴闌归騎轉，還奏弼違书。"]', '诗', 'shi', '', NULL, '同二相已下羣官樂遊園宴 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40b8cae3-f68b-4e8a-ad5f-fc33d8644185', '集賢書院成送張說上集賢學士賜宴得珍字', '集賢书院成送張说上集賢学士賜宴得珍字', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["廣學開書院，崇儒引席珍。","集賢招衮職，論道命台臣。","禮樂沿今古，文章革舊新。","獻酬尊俎列，賓主位班陳。","節變雲初夏，時移氣尚春。","所希光史冊，千載仰茲晨。"]', '["廣学开书院，崇儒引席珍。","集賢招衮職，論道命台臣。","禮乐沿今古，文章革旧新。","獻酬尊俎列，賓主位班陳。","節变云初夏，时移氣尚春。","所希光史冊，千載仰茲晨。"]', '诗', 'shi', '', NULL, '集賢書院成送張說上集賢學士賜宴得珍字 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f894b7c-19a6-43d2-9f59-2fdc76cf6579', '王屋山送道士司馬承禎還天台', '王屋山送道士司马承禎還天台', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["紫府求賢士，清谿祖逸人。","江湖與城闕，異跡且殊倫。","間有幽棲者，居然厭俗塵。","林泉先得性，芝桂欲調神。","地道踰稽嶺，天台接海濱。","音徽從此間，萬古一芳春。"]', '["紫府求賢士，清谿祖逸人。","江湖與城闕，異跡且殊倫。","间有幽棲者，居然厭俗塵。","林泉先得性，芝桂欲調神。","地道踰稽嶺，天台接海濱。","音徽從此间，万古一芳春。"]', '诗', 'shi', '', NULL, '王屋山送道士司馬承禎還天台 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('099ccd32-ce26-4dd2-83e8-da38093c303f', '早度蒲津關', '早度蒲津关', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["鐘鼓嚴更曙，山河野望通。","鳴鑾下蒲坂，飛斾入秦中。","地險關逾壯，天平鎮尚雄。","春來津樹合，月落戍樓空。","馬色分朝景，雞聲逐曉風。","所希常道泰，非復候繻同。"]', '["鐘鼓嚴更曙，山河野望通。","鳴鑾下蒲坂，飞斾入秦中。","地險关逾壯，天平鎮尚雄。","春来津樹合，月落戍楼空。","马色分朝景，雞声逐晓风。","所希常道泰，非复候繻同。"]', '诗', 'shi', '', NULL, '早度蒲津關 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dedf14b9-362c-435a-b206-bdccc02811e3', '途經華嶽', '途經华嶽', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["飭駕去京邑，鳴鸞指洛川。","循途經太華，回蹕暫周旋。","翠崿留斜影，懸巖冒夕煙。","四方皆石壁，五位配金天。","彷彿看高掌，依稀聽子先。","終當銘歲月，從此記靈仙。"]', '["飭駕去京邑，鳴鸾指洛川。","循途經太华，回蹕暫周旋。","翠崿留斜影，懸巖冒夕煙。","四方皆石壁，五位配金天。","彷彿看高掌，依稀听子先。","終當銘歲月，從此記靈仙。"]', '诗', 'shi', '', NULL, '途經華嶽 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20bfd036-c115-4eef-9a08-927a697c870c', '喜雪', '喜雪', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["日觀卜先征，時巡順物情。","風行未備禮，雲密遽飄霙。","委樹寒花發，縈空落絮輕。","朝如玉已會，庭似月猶明。","既覩膚先合，還欣尺有盈。","登封何以報？因此謝功成。"]', '["日观卜先征，时巡順物情。","风行未備禮，云密遽飄霙。","委樹寒花發，縈空落絮轻。","朝如玉已會，庭似月猶明。","既覩膚先合，還欣尺有盈。","登封何以報？因此謝功成。"]', '诗', 'shi', '', NULL, '喜雪 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b49d25c-69a8-49d2-926c-203141e28410', '幸鳳泉湯', '幸鳳泉湯', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["西狩觀周俗，南山歷漢宮。","薦鮮知路近，省斂覺年豐。","陰谷含神爨，湯泉養聖功。","益齡仙井合，愈疾醴源通。","不重鳴岐鳳，誰矜陳寶雄。","願將無限澤，霑沐衆心同。"]', '["西狩观周俗，南山歷漢宮。","薦鲜知路近，省斂覺年豐。","陰谷含神爨，湯泉養聖功。","益齡仙井合，愈疾醴源通。","不重鳴岐鳳，誰矜陳寶雄。","願將無限澤，霑沐衆心同。"]', '诗', 'shi', '', NULL, '幸鳳泉湯 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5ff7429-35fd-4f63-9e75-f4cfd9f750c2', '南出雀鼠谷答張說', '南出雀鼠谷答張说', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["雷出應乾象，風行順國人。","川途猶在晉，車馬漸歸秦。","背陝關山險，橫汾鼓吹頻。","草依陽谷變，花待北巖春。","聞有鵷鸞客，清詞雅調新。","求音思欲報，心跡竟難陳。"]', '["雷出應乾象，风行順国人。","川途猶在晉，车马漸归秦。","背陝关山險，橫汾鼓吹頻。","草依陽谷变，花待北巖春。","闻有鵷鸾客，清词雅調新。","求音思欲報，心跡竟难陳。"]', '诗', 'shi', '', NULL, '南出雀鼠谷答張說 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c46b77-4c2d-456e-bf07-3414a6ff0d5f', '賜崔日知往潞州', '賜崔日知往潞州', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["潞國開新府，壺關寵舊林。","妙旌循吏德，持悅庶氓心。","禮樂中朝貴，神明列郡欽。","揚風非贈扇，易俗是張琴。","藩鎮謳謠滿，行宮雨露深。","會書丞相策，先賜潁川金。"]', '["潞国开新府，壺关寵旧林。","妙旌循吏德，持悅庶氓心。","禮乐中朝貴，神明列郡欽。","揚风非贈扇，易俗是張琴。","藩鎮謳謠满，行宮雨露深。","會书丞相策，先賜潁川金。"]', '诗', 'shi', '', NULL, '賜崔日知往潞州 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c02660f-f015-42fb-85be-a7a1420add8d', '爲趙法師別造精院過院賦詩', '爲趙法師別造精院過院賦诗', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["宗師心物外，爲道運虛舟。","不戀巖泉賞，來從宮禁遊。","探玄知幾歲，習靜更宜秋。","煙樹辨朝色，風湍聞夜流。","坐朝繁聽覽，尋勝在清幽。","欲廣無爲化，因茲庶可求。"]', '["宗師心物外，爲道運虛舟。","不戀巖泉賞，来從宮禁游。","探玄知幾歲，習静更宜秋。","煙樹辨朝色，风湍闻夜流。","坐朝繁听覽，尋勝在清幽。","欲廣無爲化，因茲庶可求。"]', '诗', 'shi', '', NULL, '爲趙法師別造精院過院賦詩 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac93ab8-f32b-49b6-8f72-938e414c9cca', '端午', '端午', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["端午臨中夏，時清日復長。","鹽梅已佐鼎，麯糵且傳觴。","事古人留迹，年深縷積長。","當軒知槿茂，向水覺蘆香。","億兆同歸壽，羣公共保昌。","忠貞如不替，貽厥後昆芳。"]', '["端午臨中夏，时清日复长。","鹽梅已佐鼎，麯糵且傳觴。","事古人留迹，年深縷積长。","當軒知槿茂，向水覺蘆香。","億兆同归壽，羣公共保昌。","忠貞如不替，貽厥後昆芳。"]', '诗', 'shi', '', NULL, '端午 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7afe8f0f-5f85-4b83-a957-e3bfa0a29587', '春中興慶宮酺宴', '春中兴慶宮酺宴', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["九達長安道，三陽別館春。","還將聽朝暇，回作豫遊晨。","不戰要荒服，無刑禮樂新。","合酺覃土宇，歡宴接羣臣。","玉斝飛千日，瓊筵薦八珍。","舞衣雲曳影，歌扇月開輪。","伐鼓魚龍雜，撞鐘角觝陳。","曲終酣興晚，須有醉歸人。"]', '["九達长安道，三陽別館春。","還將听朝暇，回作豫游晨。","不戰要荒服，無刑禮乐新。","合酺覃土宇，歡宴接羣臣。","玉斝飞千日，瓊筵薦八珍。","舞衣云曳影，歌扇月开輪。","伐鼓鱼龙杂，撞鐘角觝陳。","曲終酣兴晚，須有醉归人。"]', '诗', 'shi', '', NULL, '春中興慶宮酺宴 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('746656b4-b41f-4ef8-ad6d-02a30edc5fc5', '千秋節宴', '千秋節宴', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["蘭殿千秋節，稱名萬壽觴。","風傳率土慶，日表繼天祥。","玉宇開花蕚，宮縣動會昌。","衣冠白鷺下，帟幕翠雲長。","獻遺成新俗，朝儀入舊章。","月銜花綬鏡，露綴綵絲囊。","處處祠田祖，年年宴杖鄉。","深思一德事，小獲萬人康。"]', '["蘭殿千秋節，稱名万壽觴。","风傳率土慶，日表繼天祥。","玉宇开花蕚，宮縣动會昌。","衣冠白鷺下，帟幕翠云长。","獻遺成新俗，朝儀入旧章。","月銜花綬镜，露綴綵絲囊。","处处祠田祖，年年宴杖乡。","深思一德事，小獲万人康。"]', '诗', 'shi', '', NULL, '千秋節宴 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ba29c5-333c-4b5d-978f-d5bfdf29a89b', '左丞相說右丞相璟太子少傅乾曜同日上官命宴東堂賜詩', '左丞相说右丞相璟太子少傅乾曜同日上官命宴东堂賜诗', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["赤帝收三傑，黃軒舉二臣。","由來丞相重，分掌國之鈞。","我有握中璧，雙飛席上珍。","子房推道要，仲子訝風神。","復輟台衡老，將爲調護人。","鵷鸞同拜日，車騎擁行塵。","樂聚南宮宴，觴連北斗醇。","俾予成百揆，垂拱問彝倫。"]', '["赤帝收三傑，黄軒舉二臣。","由来丞相重，分掌国之鈞。","我有握中璧，雙飞席上珍。","子房推道要，仲子訝风神。","复輟台衡老，將爲調護人。","鵷鸾同拜日，车騎擁行塵。","乐聚南宮宴，觴連北斗醇。","俾予成百揆，垂拱问彝倫。"]', '诗', 'shi', '', NULL, '左丞相說右丞相璟太子少傅乾曜同日上官命宴東堂賜詩 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b721d41-b555-48ff-8c1d-c81104498e39', '早登太行山中言志', '早登太行山中言志', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["清蹕度河陽，凝笳上太行。","火龍明鳥道，鐵騎繞羊腸。","白霧埋陰壑，丹霞助曉光。","澗泉含宿凍，山木帶餘霜。","野老茅爲屋，樵人薜作裳。","宣風問耆艾，敦俗勸耕桑。","涼德慙先哲，徽猷慕昔皇。"]', '["清蹕度河陽，凝笳上太行。","火龙明鸟道，鐵騎繞羊腸。","白霧埋陰壑，丹霞助晓光。","澗泉含宿凍，山木带餘霜。","野老茅爲屋，樵人薜作裳。","宣风问耆艾，敦俗勸耕桑。","涼德慙先哲，徽猷慕昔皇。"]', '诗', 'shi', '', NULL, '早登太行山中言志 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d6d713f-e241-4cc9-b332-733225339044', '平胡', '平胡', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["雜虜忽猖狂，無何敢亂常。","羽書朝繼入，烽火夜相望。","將出凶門勇，兵因死地強。","蒙輪皆突騎，按劒盡鷹揚。","鼓角雄山野，龍蛇入戰場。","流膏潤沙漠，濺血染鋒鋩。","霧掃清玄塞，雲開靜朔方。","武功今已立，文德愧前王。"]', '["杂虜忽猖狂，無何敢亂常。","羽书朝繼入，烽火夜相望。","將出凶门勇，兵因死地強。","蒙輪皆突騎，按劒尽鷹揚。","鼓角雄山野，龙蛇入戰場。","流膏潤沙漠，濺血染鋒鋩。","霧掃清玄塞，云开静朔方。","武功今已立，文德愧前王。"]', '诗', 'shi', '', NULL, '平胡 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcaab812-5769-4667-b564-92fcd3180956', '遊興慶宮作', '游兴慶宮作', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["代邸青門右，離宮紫陌陲。","庭如過沛日，水若渡江時。","綺觀連雞岫，朱樓接雁池。","從來敦棣蕚，今此茂荆枝。","萬葉傳餘慶，千年志不移。","凭軒聊屬目，輕輦共追隨。","務本方崇訓，相輝保羽儀。","時康俗易漸，德薄政難施。","鼓吹迎飛蓋，弦歌送羽巵。","所希覃率土，孝弟一同規。"]', '["代邸青门右，離宮紫陌陲。","庭如過沛日，水若渡江时。","綺观連雞岫，朱楼接雁池。","從来敦棣蕚，今此茂荆枝。","万葉傳餘慶，千年志不移。","凭軒聊屬目，轻輦共追隨。","務本方崇訓，相輝保羽儀。","时康俗易漸，德薄政难施。","鼓吹迎飞蓋，弦歌送羽巵。","所希覃率土，孝弟一同規。"]', '诗', 'shi', '', NULL, '遊興慶宮作 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1748c5bc-f20c-42f0-87e2-b7b78fce31cb', '送張說巡邊', '送張说巡邊', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["端拱復垂裳，長懷御遠方。","股肱申教義，戈劒靖要荒。","命將綏邊服，雄圖出廟堂。","三台入武帳，八座起文昌。","寶胄匡韓主，華宗輔漢王。","茂先慙博物，平子謝文章。","盡節恢時佐，輸誠禦寇場。","三軍臨朔野，駟馬即戎行。","鼓吹威夷狄，旌軒溢洛陽。","雲臺先著美，今日更貽芳。"]', '["端拱复垂裳，长懷御远方。","股肱申教義，戈劒靖要荒。","命將綏邊服，雄圖出廟堂。","三台入武帳，八座起文昌。","寶胄匡韓主，华宗輔漢王。","茂先慙博物，平子謝文章。","尽節恢时佐，輸誠禦寇場。","三軍臨朔野，駟马即戎行。","鼓吹威夷狄，旌軒溢洛陽。","云台先著美，今日更貽芳。"]', '诗', 'shi', '', NULL, '送張說巡邊 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99dbd2f9-5430-4250-8073-6925811afb72', '餞王晙巡邊', '餞王晙巡邊', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["振武威荒服，揚文肅遠墟。","金壇申將禮，玉節授軍符。","免胄三方外，銜刀萬里餘。","昔時吳會靜，今日虜庭虛。","分閫仍推轂，援桴且訓車。","風揚旌斾遠，雨洗甲兵初。","坐見台階謐，行聞祅祲除。","檄來雖插羽，箭去亦飛書。","舟檝功須著，鹽梅望匪疎。","不應陳七德，欲使化先敷。"]', '["振武威荒服，揚文肅远墟。","金壇申將禮，玉節授軍符。","免胄三方外，銜刀万里餘。","昔时吳會静，今日虜庭虛。","分閫仍推轂，援桴且訓车。","风揚旌斾远，雨洗甲兵初。","坐见台階謐，行闻祅祲除。","檄来雖插羽，箭去亦飞书。","舟檝功須著，鹽梅望匪疎。","不應陳七德，欲使化先敷。"]', '诗', 'shi', '', NULL, '餞王晙巡邊 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3e09dbc-9565-4d64-a1e3-92f22726430f', '巡省途次上黨舊宮賦', '巡省途次上黨旧宮賦', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["三千初擊浪，九萬欲摶空。","天地猶驚否，陰陽始遇蒙。","存貞期歷試，佐貳佇昭融。","多謝時康理，良慙實賴功。","長懷問鼎氣，夙負拔山雄。","不學劉琨舞，先歌漢祖風。","英髦既包括，豪傑自牢籠。","人事一朝異，謳歌四海同。","如何昔朱邸，今此作離宮？","雁沼澄瀾翠，猿巖落照紅。","小山秋桂馥，長坂舊蘭叢。","即是淹留處，乘歡樂未窮。"]', '["三千初擊浪，九万欲摶空。","天地猶驚否，陰陽始遇蒙。","存貞期歷試，佐貳佇昭融。","多謝时康理，良慙實賴功。","长懷问鼎氣，夙負拔山雄。","不学劉琨舞，先歌漢祖风。","英髦既包括，豪傑自牢籠。","人事一朝異，謳歌四海同。","如何昔朱邸，今此作離宮？","雁沼澄瀾翠，猿巖落照紅。","小山秋桂馥，长坂旧蘭叢。","即是淹留处，乘歡乐未窮。"]', '诗', 'shi', '', NULL, '巡省途次上黨舊宮賦 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cabdbd9c-d957-4881-aff2-479d08c3c583', '潼關口號', '潼关口號', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["河曲回千里，關門限二京。","所嗟非恃德，設險到天平。"]', '["河曲回千里，关门限二京。","所嗟非恃德，設險到天平。"]', '诗', 'shi', '', NULL, '潼關口號 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('275ae461-9263-47e1-8a47-d477e519c3a9', '千秋節賜羣臣鏡', '千秋節賜羣臣镜', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["瑞露垂花綬，寒冰澈寶輸。","對茲臺上月，聊以慶佳辰。"]', '["瑞露垂花綬，寒冰澈寶輸。","对茲台上月，聊以慶佳辰。"]', '诗', 'shi', '', NULL, '千秋節賜羣臣鏡 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4567287-ed9d-4ae9-b24a-69740afc9222', '續薛令之題壁', '續薛令之題壁', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["啄木觜距長，鳳皇羽毛短。","苦嫌松桂寒，任逐桑榆煖。"]', '["啄木觜距长，鳳皇羽毛短。","苦嫌松桂寒，任逐桑榆煖。"]', '诗', 'shi', '', NULL, '續薛令之題壁 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfebde8-4ae5-47f8-9cd6-536c584fb6f6', '送胡真師還西山', '送胡真師還西山', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["仙客厭人間，孤雲比性閒。","話離情未已，煙水萬重山。"]', '["仙客厭人间，孤云比性閒。","話離情未已，煙水万重山。"]', '诗', 'shi', '', NULL, '送胡真師還西山 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66f8c48a-f6c8-4247-9863-4ee9d832b202', '過大哥山池題石壁', '過大哥山池題石壁', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["澄潭皎鏡石崔巍，萬壑千巖暗綠苔。","林亭自有幽貞趣，況復秋深爽氣來。"]', '["澄潭皎镜石崔巍，万壑千巖暗綠苔。","林亭自有幽貞趣，況复秋深爽氣来。"]', '诗', 'shi', '', NULL, '過大哥山池題石壁 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b0a3511-24ee-414c-a93f-b561d791f545', '題梅妃畫真', '題梅妃畫真', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["憶昔嬌妃在紫宸，鉛華不御得天真。","霜綃雖似當時態，爭奈嬌波不顧人。"]', '["憶昔嬌妃在紫宸，鉛华不御得天真。","霜綃雖似當时態，爭奈嬌波不顧人。"]', '诗', 'shi', '', NULL, '題梅妃畫真 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e455ec15-d04b-4797-8a01-da7fa5a5c367', '鶺鴒頌', '鶺鴒頌', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["伊我軒宮，奇樹青葱。","藹周廬兮，冒霜停雪，以茂以悅。","恣卷舒兮，連枝同榮，吐綠含英。","曜春初兮，蓐收御節，寒露微結。","氣清虛兮，桂宮蘭殿，唯所息宴。","棲雍渠兮，行搖飛鳴，急難有情。","情有餘兮，顧惟德涼，夙夜兢惶。","慙化疎兮，上之所教，下之所效。","實在予兮，天倫之性，魯衛分政。","親賢居兮，爰遊爰處，爰笑爰語。","巡庭除兮，觀此翔禽，以悅我心，良史書兮。"]', '["伊我軒宮，奇樹青葱。","藹周廬兮，冒霜停雪，以茂以悅。","恣卷舒兮，連枝同榮，吐綠含英。","曜春初兮，蓐收御節，寒露微結。","氣清虛兮，桂宮蘭殿，唯所息宴。","棲雍渠兮，行搖飞鳴，急难有情。","情有餘兮，顧惟德涼，夙夜兢惶。","慙化疎兮，上之所教，下之所效。","實在予兮，天倫之性，魯衛分政。","親賢居兮，爰游爰处，爰笑爰語。","巡庭除兮，观此翔禽，以悅我心，良史书兮。"]', '诗', 'shi', '', NULL, '鶺鴒頌 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7cf9007-f2af-4954-a355-045c9589a7a8', '傀儡吟', '傀儡吟', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["刻木牽絲作老翁，雞皮鶴髮與真同。","須臾弄罷寂無事，還似人生一夢中。"]', '["刻木牽絲作老翁，雞皮鹤髮與真同。","須臾弄罷寂無事，還似人生一梦中。"]', '诗', 'shi', '', NULL, '傀儡吟 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63e5f845-6aac-4453-9bc0-23b81643aebd', '句', '句', '20a8a766-a18a-4193-85fb-04eb4aeb9e60', '唐', '["昔見漳濱臥，言將人事違。","今逢慶誕日，猶謂學仙歸。","棠棣花重發，鴒原鳥再飛。","德比代雲布，心如晉水清。"]', '["昔见漳濱臥，言將人事違。","今逢慶誕日，猶謂学仙归。","棠棣花重發，鴒原鸟再飞。","德比代云布，心如晉水清。"]', '诗', 'shi', '', NULL, '句 明皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8390b439-f7e4-42c1-b6c7-cdf9d9480f57', '延英殿玉靈芝詩三章章八句 一', '延英殿玉靈芝诗三章章八句 一', 'fecb4aa8-a9a7-401b-bb21-4e8ac50ae478', '唐', '["玉殿肅肅，靈芝煌煌。","重英發秀，連葉分房。","宗廟之福，垂其耿光。"]', '["玉殿肅肅，靈芝煌煌。","重英發秀，連葉分房。","宗廟之福，垂其耿光。"]', '诗', 'shi', '', NULL, '延英殿玉靈芝詩三章章八句 一 肅宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('247aeb58-ca1c-46e4-8bf3-81c400f0ec8a', '延英殿玉靈芝詩三章章八句 二', '延英殿玉靈芝诗三章章八句 二', 'fecb4aa8-a9a7-401b-bb21-4e8ac50ae478', '唐', '["元氣產芝，明神合德。","紫微間采，白蕣呈色。","載啓瑞圖，庶符皇極。","天心有眷，王道惟直。"]', '["元氣產芝，明神合德。","紫微间采，白蕣呈色。","載啓瑞圖，庶符皇極。","天心有眷，王道惟直。"]', '诗', 'shi', '', NULL, '延英殿玉靈芝詩三章章八句 二 肅宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4b77a86-2d4a-4e4b-815e-cd6e7d4b127a', '延英殿玉靈芝詩三章章八句 三', '延英殿玉靈芝诗三章章八句 三', 'fecb4aa8-a9a7-401b-bb21-4e8ac50ae478', '唐', '["幸生芳本，當我扆旒。","效此靈質，賁其王猷。","神惟不愛，道亦無求。","端拱思惟，永荷天休。"]', '["幸生芳本，當我扆旒。","效此靈質，賁其王猷。","神惟不愛，道亦無求。","端拱思惟，永荷天休。"]', '诗', 'shi', '', NULL, '延英殿玉靈芝詩三章章八句 三 肅宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3120b8ba-bc2b-40a0-a768-8aeef43eee6b', '賜棃李泌與諸王聯句', '賜棃李泌與諸王聯句', 'fecb4aa8-a9a7-401b-bb21-4e8ac50ae478', '唐', '["先生年幾許，顏色似童兒。","夜抱九仙骨，朝披一品衣。","不食千鍾粟，唯餐兩顆棃。","天生此間氣，助我化無爲。"]', '["先生年幾許，顏色似童兒。","夜抱九仙骨，朝披一品衣。","不食千鍾粟，唯餐兩顆棃。","天生此间氣，助我化無爲。"]', '诗', 'shi', '', NULL, '賜棃李泌與諸王聯句 肅宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba2c561-9752-49e3-9575-b1b3d935ab05', '中和節日宴百僚賜詩', '中和節日宴百僚賜诗', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["韶年啓仲序，初吉諧良辰。","肇茲中和節，式慶天地春。","歡酣朝野同，生德區宇均。","雲開灑膏露，草疏芳河津。","歲華今載陽，東作方肆勤。","慙非熏風唱，曷用慰吾人。"]', '["韶年啓仲序，初吉諧良辰。","肇茲中和節，式慶天地春。","歡酣朝野同，生德區宇均。","云开灑膏露，草疏芳河津。","歲华今載陽，东作方肆勤。","慙非熏风唱，曷用慰吾人。"]', '诗', 'shi', '', NULL, '中和節日宴百僚賜詩 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cac5a624-4332-4200-9b3d-735cb790e16d', '中和節賜百官燕集因示所懷', '中和節賜百官燕集因示所懷', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["至化恆在宥，保和茲息人。","推誠撫諸夏，與物長爲春。","仲月風景暖，禁城花柳新。","芳時協金奏，賜宴同羣臣。","絲竹豈云樂，忠賢惟所親。","庶洽朝野意，曠然天地均。"]', '["至化恆在宥，保和茲息人。","推誠撫諸夏，與物长爲春。","仲月风景暖，禁城花柳新。","芳时協金奏，賜宴同羣臣。","絲竹豈云乐，忠賢惟所親。","庶洽朝野意，曠然天地均。"]', '诗', 'shi', '', NULL, '中和節賜百官燕集因示所懷 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0fbc276-8bbc-4f26-a0e9-efc8696f9351', '重陽日賜宴曲江亭賦六韻詩用清字', '重陽日賜宴曲江亭賦六韻诗用清字', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["早衣對庭燎，躬化勤意誠。","時此萬機暇，適與佳節幷。","曲池潔寒流，芳菊舒金英。","乾坤爽氣滿，臺殿秋光清。","朝野慶年豐，高會多歡聲。","永懷無荒戒，良士同斯情。"]', '["早衣对庭燎，躬化勤意誠。","时此万機暇，適與佳節幷。","曲池潔寒流，芳菊舒金英。","乾坤爽氣满，台殿秋光清。","朝野慶年豐，高會多歡声。","永懷無荒戒，良士同斯情。"]', '诗', 'shi', '', NULL, '重陽日賜宴曲江亭賦六韻詩用清字 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aaa5f00-4541-4d06-a915-0e71b2306c98', '九月十八賜百僚追賞因書所懷', '九月十八賜百僚追賞因书所懷', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["雨霽霜氣肅，天高雲日明。","繁林已墜葉，寒菊仍舒榮。","懿此秋節時，更延追賞情。","池臺列廣宴，絲竹傳新聲。","至樂非外獎，浹歡同中誠。","庶敦朝野意，永使風化清。"]', '["雨霽霜氣肅，天高云日明。","繁林已墜葉，寒菊仍舒榮。","懿此秋節时，更延追賞情。","池台列廣宴，絲竹傳新声。","至乐非外獎，浹歡同中誠。","庶敦朝野意，永使风化清。"]', '诗', 'shi', '', NULL, '九月十八賜百僚追賞因書所懷 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73f35093-8a40-44ba-ba98-6b4457303408', '送徐州張建封還鎮', '送徐州張建封還鎮', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["牧守寄所重，才賢生爲時。","宣風自淮甸，授鉞膺藩維。","入覲展遐戀，臨軒慰來思。","忠誠在方寸，感激陳情詞。","報國爾所向，恤人予是資。","歡宴不盡懷，車馬當還期。","穀雨將應候，行春猶未遲。","勿以千里遙，而云無己知。"]', '["牧守寄所重，才賢生爲时。","宣风自淮甸，授鉞膺藩維。","入覲展遐戀，臨軒慰来思。","忠誠在方寸，感激陳情词。","報国爾所向，恤人予是資。","歡宴不尽懷，车马當還期。","穀雨將應候，行春猶未遲。","勿以千里遙，而云無己知。"]', '诗', 'shi', '', NULL, '送徐州張建封還鎮 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac02826d-1549-4338-83cc-a58238ea737d', '麟德殿宴百僚', '麟德殿宴百僚', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["憂勤承聖緒，開泰喜時康。","恭己臨羣后，垂衣御八荒。","務閑春向暮，朝罷日猶長。","紫殿初筵列，彤庭廣樂張。","成功歸輔弼，致理賴忠良。","共此歡娛事，千秋樂未央。"]', '["憂勤承聖緒，开泰喜时康。","恭己臨羣后，垂衣御八荒。","務闲春向暮，朝罷日猶长。","紫殿初筵列，彤庭廣乐張。","成功归輔弼，致理賴忠良。","共此歡娛事，千秋乐未央。"]', '诗', 'shi', '', NULL, '麟德殿宴百僚 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f2b9e3-e7c6-4049-84d1-2a585f98c4a2', '元日退朝觀軍仗歸營', '元日退朝观軍仗归營', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["獻歲視元朔，萬方咸在庭。","端旒揖羣后，回輦閱師貞。","綵仗宿華殿，退朝歸禁營。","分行左右出，轉斾風雲生。","歷歷趨複道，容容映層城。","勇餘矜捷技，令肅無喧聲。","眷此戎旅節，載嘉良士誠。","順時傾宴賞，亦以助文經。"]', '["獻歲視元朔，万方咸在庭。","端旒揖羣后，回輦閱師貞。","綵仗宿华殿，退朝归禁營。","分行左右出，轉斾风云生。","歷歷趨複道，容容映層城。","勇餘矜捷技，令肅無喧声。","眷此戎旅節，載嘉良士誠。","順时傾宴賞，亦以助文經。"]', '诗', 'shi', '', NULL, '元日退朝觀軍仗歸營 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f07ad1d-8a95-4e2f-984d-b2f35a057ca6', '中和節賜羣臣宴賦七韻', '中和節賜羣臣宴賦七韻', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["東風變梅柳，萬彙生春光。","中和紀月令，方與天地長。","耽樂豈予尚，懿茲時景良。","庶遂亭育恩，同致寰海康。","君臣永終始，交泰符陰陽。","曲沼水新碧，華林桃稍芳。","勝賞信多歡，戒之在無荒。"]', '["东风变梅柳，万彙生春光。","中和紀月令，方與天地长。","耽乐豈予尚，懿茲时景良。","庶遂亭育恩，同致寰海康。","君臣永終始，交泰符陰陽。","曲沼水新碧，华林桃稍芳。","勝賞信多歡，戒之在無荒。"]', '诗', 'shi', '', NULL, '中和節賜羣臣宴賦七韻 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fa19519-78a9-494b-b6f2-2a22a48ba3f3', '三日書懷因示百僚', '三日书懷因示百僚', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["佳節上元巳，芳時屬暮春。","流觴想蘭亭，捧劒得金人。","風輕水初綠，日晴花更新。","天文信昭回，皇道頗敷陳。","恭己每從儉，清心常保真。","戒茲游衍樂，書以示羣臣。"]', '["佳節上元巳，芳时屬暮春。","流觴想蘭亭，捧劒得金人。","风轻水初綠，日晴花更新。","天文信昭回，皇道頗敷陳。","恭己每從儉，清心常保真。","戒茲游衍乐，书以示羣臣。"]', '诗', 'shi', '', NULL, '三日書懷因示百僚 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26bda590-69ee-4667-88e4-07e217c0ebaf', '重陽日中外同歡以詩言志因示羣官', '重陽日中外同歡以诗言志因示羣官', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["[爽]節在重九，物華新雨餘。","清秋黃葉下，菊散金潭初。","萬實行就稔，百工欣所如。","歡心暢遐邇，殊俗同車書。","至化自敦睦，佳辰宜宴胥。","鏘鏘間絲竹，濟濟羅簪裾。","此樂匪足耽，此誠期永孚。"]', '["[爽]節在重九，物华新雨餘。","清秋黄葉下，菊散金潭初。","万實行就稔，百工欣所如。","歡心暢遐邇，殊俗同车书。","至化自敦睦，佳辰宜宴胥。","鏘鏘间絲竹，濟濟羅簪裾。","此乐匪足耽，此誠期永孚。"]', '诗', 'shi', '', NULL, '重陽日中外同歡以詩言志因示羣官 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea2b7e59-3d59-4f78-ac87-e06e9526950b', '重陽日即事', '重陽日即事', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["令節曉澄霽，四郊煙靄空。","天清白露潔，菊散黃金叢。","寡德荷天貺，順時休百工。","豈懷歌鐘樂，思爲君臣同。","至化在亭育，相成資始終。","未知康衢詠，所仰惟年豐。"]', '["令節晓澄霽，四郊煙靄空。","天清白露潔，菊散黄金叢。","寡德荷天貺，順时休百工。","豈懷歌鐘乐，思爲君臣同。","至化在亭育，相成資始終。","未知康衢詠，所仰惟年豐。"]', '诗', 'shi', '', NULL, '重陽日即事 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('776916a8-bf58-4662-9596-e233239efdec', '豐年多慶九日示懷', '豐年多慶九日示懷', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["爽氣肅時令，早衣聞朔鴻。","重陽有佳節，具物欣年豐。","皎潔暮潭色，芬敷新菊叢。","芳尊滿衢室，繁吹凝煙空。","惠合信吾道，保和惟爾同。","推誠至玄化，天下期爲公。"]', '["爽氣肅时令，早衣闻朔鴻。","重陽有佳節，具物欣年豐。","皎潔暮潭色，芬敷新菊叢。","芳尊满衢室，繁吹凝煙空。","惠合信吾道，保和惟爾同。","推誠至玄化，天下期爲公。"]', '诗', 'shi', '', NULL, '豐年多慶九日示懷 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5197293d-6d7e-48f7-9387-f992e9c3a2ee', '七月十五日題章敬寺', '七月十五日題章敬寺', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["招提邇皇邑，複道連重城。","法筵會早秋，駕言訪禪扃。","嘗聞大仙教，清淨宗無生。","七物匪吾寶，萬行先求成。","名相既雙寂，繁華奚所榮。","金風扇微涼，遠煙凝翠晶。","松院靜苔色，竹房深磬聲。","境幽真慮恬，道勝外物輕。","意適本非說，含毫空復情。"]', '["招提邇皇邑，複道連重城。","法筵會早秋，駕言訪禪扃。","嘗闻大仙教，清淨宗無生。","七物匪吾寶，万行先求成。","名相既雙寂，繁华奚所榮。","金风扇微涼，远煙凝翠晶。","松院静苔色，竹房深磬声。","境幽真慮恬，道勝外物轻。","意適本非说，含毫空复情。"]', '诗', 'shi', '', NULL, '七月十五日題章敬寺 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88f88d70-f0cb-4250-8926-4d31d42abc44', '中春麟德殿會百僚觀新樂詩一章章十六句', '中春麟德殿會百僚观新乐诗一章章十六句', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["芳歲肇佳節，物華當仲春。","乾坤既昭泰，煙景含氤氳。","德淺荷玄貺，樂成思治人。","前庭列鐘鼓，廣殿延羣臣。","八卦隨舞意，五音轉曲新。","顧非咸池奏，庶協南風熏。","式宴禮所重，浹歡情必均。","同和諒在茲，萬國希可親。"]', '["芳歲肇佳節，物华當仲春。","乾坤既昭泰，煙景含氤氳。","德淺荷玄貺，乐成思治人。","前庭列鐘鼓，廣殿延羣臣。","八卦隨舞意，五音轉曲新。","顧非咸池奏，庶協南风熏。","式宴禮所重，浹歡情必均。","同和諒在茲，万国希可親。"]', '诗', 'shi', '', NULL, '中春麟德殿會百僚觀新樂詩一章章十六句 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1b0eaa8-b5f7-4fd4-8431-2cb0bb304f54', '九日絕句', '九日絕句', '92a37482-aa8f-4c45-99f7-e8ba28d4b0c5', '唐', '["禁苑秋來爽氣多，昆明風動起滄波。","中流簫鼓誠堪賞，詎假橫汾發櫂歌。"]', '["禁苑秋来爽氣多，昆明风动起滄波。","中流簫鼓誠堪賞，詎假橫汾發櫂歌。"]', '诗', 'shi', '', NULL, '九日絕句 德宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30cd14b3-98fd-4a64-b57f-6d2cc05f52d9', '暮春喜雨詩', '暮春喜雨诗', '06b99b3e-7287-4c99-ab14-ade5fa5edb6c', '唐', '["風雲喜際會，雷雨遂流滋。","薦幣虛陳禮，動天實精思。","漸侵九夏節，復在三春時。","霢霂垂朱闕，飄颻入綠墀。","郊坰既霑足，黍稷有豐期。","百辟同康樂，萬方佇雍熙。"]', '["风云喜際會，雷雨遂流滋。","薦幣虛陳禮，动天實精思。","漸侵九夏節，复在三春时。","霢霂垂朱闕，飄颻入綠墀。","郊坰既霑足，黍稷有豐期。","百辟同康乐，万方佇雍熙。"]', '诗', 'shi', '', NULL, '暮春喜雨詩 文宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a0d85ba-b322-48e5-8dbc-4ce3f6efac5e', '題程修己竹障', '題程修己竹障', '06b99b3e-7287-4c99-ab14-ade5fa5edb6c', '唐', '["良工運精思，巧極似有神。","臨窗忽覩繁陰合，再盼真假殊未分。"]', '["良工運精思，巧極似有神。","臨窗忽覩繁陰合，再盼真假殊未分。"]', '诗', 'shi', '', NULL, '題程修己竹障 文宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('534288d0-412e-44e5-aff6-b38879e01cd8', '宮中題', '宮中題', '06b99b3e-7287-4c99-ab14-ade5fa5edb6c', '唐', '["輦路生春草，上林花發時。","憑高何限意，無復侍臣知。"]', '["輦路生春草，上林花發时。","憑高何限意，無复侍臣知。"]', '诗', 'shi', '', NULL, '宮中題 文宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b99f129-4039-41f1-b8db-b12d21035fc2', '上巳日賜裴度', '上巳日賜裴度', '06b99b3e-7287-4c99-ab14-ade5fa5edb6c', '唐', '["注想待元老，識君恨不早。","我家柱石衰，憂來學丘禱。"]', '["注想待元老，識君恨不早。","我家柱石衰，憂来学丘禱。"]', '诗', 'shi', '', NULL, '上巳日賜裴度 文宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6edbac82-339f-45d9-908d-89dd67f941e5', '上元日二首 一', '上元日二首 一', '06b99b3e-7287-4c99-ab14-ade5fa5edb6c', '唐', '["上元高會集羣仙，心齋何事欲祈年。","丹誠儻徹玉帝座，且共吾人慶大田。"]', '["上元高會集羣仙，心斋何事欲祈年。","丹誠儻徹玉帝座，且共吾人慶大田。"]', '诗', 'shi', '', NULL, '上元日二首 一 文宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78b979f0-9d59-4905-ae9a-5ba2445d0cf8', '上元日二首 二', '上元日二首 二', '06b99b3e-7287-4c99-ab14-ade5fa5edb6c', '唐', '["蓂生三五葉初齊，上元羽客出桃蹊。","不愛仙家登真訣，願蒙四海福黔黎。"]', '["蓂生三五葉初齊，上元羽客出桃蹊。","不愛仙家登真訣，願蒙四海福黔黎。"]', '诗', 'shi', '', NULL, '上元日二首 二 文宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('078cc610-552e-4224-8413-3dda0ac3c0f5', '夏日聯句', '夏日聯句', '06b99b3e-7287-4c99-ab14-ade5fa5edb6c', '唐', '["人皆苦炎熱，我愛夏日長。","熏風自南來，殿閣生微涼。"]', '["人皆苦炎熱，我愛夏日长。","熏风自南来，殿閣生微涼。"]', '诗', 'shi', '', NULL, '夏日聯句 文宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc12092-e338-458d-a730-5ee07b08d888', '百丈山', '百丈山', '004b8cf8-4ce4-4226-af20-28fddd009d90', '唐', '["大雄真跡枕危巒，梵宇層樓聳萬般。","日月每從肩上過，山河長在掌中看。","仙峰不間三春秀，靈境何時六月寒？","更有上方人罕到，暮鐘朝磬碧雲端。"]', '["大雄真跡枕危巒，梵宇層楼聳万般。","日月每從肩上過，山河长在掌中看。","仙峰不间三春秀，靈境何时六月寒？","更有上方人罕到，暮鐘朝磬碧云端。"]', '诗', 'shi', '', NULL, '百丈山 宣宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f129bf81-4ca2-41c1-912e-4348dfb7956e', '弔白居易', '弔白居易', '004b8cf8-4ce4-4226-af20-28fddd009d90', '唐', '["綴玉聯珠六十年，誰教冥路作詩仙。","浮雲不繫名居易，造化無爲字樂天。","童子解吟《長恨曲》，胡兒能唱《琵琶篇》。","文章已滿行人耳，一度思卿一愴然。"]', '["綴玉聯珠六十年，誰教冥路作诗仙。","浮云不繫名居易，造化無爲字乐天。","童子解吟《长恨曲》，胡兒能唱《琵琶篇》。","文章已满行人耳，一度思卿一愴然。"]', '诗', 'shi', '', NULL, '弔白居易 宣宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbc8ea5e-53eb-4a81-b9af-5a7db544fb1c', '幸華嚴寺', '幸华嚴寺', '004b8cf8-4ce4-4226-af20-28fddd009d90', '唐', '["雲散晴山幾萬重，煙收春色更沖融。","帳殿出空登碧漢，遐川俯望色藍籠。","林光入戶低韶景，嶺氣通宵展霽風。","今日追遊何所似，莫慙漢武賞汾中。"]', '["云散晴山幾万重，煙收春色更沖融。","帳殿出空登碧漢，遐川俯望色藍籠。","林光入戶低韶景，嶺氣通宵展霽风。","今日追游何所似，莫慙漢武賞汾中。"]', '诗', 'shi', '', NULL, '幸華嚴寺 宣宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afecb511-1ff4-415f-ba1b-4a6136513d17', '重陽錫宴羣臣', '重陽錫宴羣臣', '004b8cf8-4ce4-4226-af20-28fddd009d90', '唐', '["款塞旋征騎，和戎委廟賢。","傾心方倚注，叶力共安邊。"]', '["款塞旋征騎，和戎委廟賢。","傾心方倚注，叶力共安邊。"]', '诗', 'shi', '', NULL, '重陽錫宴羣臣 宣宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9abf192a-34e2-410d-addc-68171f00c3f0', '題涇縣水西寺', '題涇縣水西寺', '004b8cf8-4ce4-4226-af20-28fddd009d90', '唐', '["大殿連雲接爽溪，鐘聲還與鼓聲齊。","長安若問江南事，說道風光在水西。"]', '["大殿連云接爽溪，鐘声還與鼓声齊。","长安若问江南事，说道风光在水西。"]', '诗', 'shi', '', NULL, '題涇縣水西寺 宣宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79b4be2b-65d5-412f-82ed-48d8b804fabc', '瀑布聯句', '瀑布聯句', '004b8cf8-4ce4-4226-af20-28fddd009d90', '唐', '["千巖萬壑不辭勞，遠看方知出處高。","溪澗豈能留得住，終歸大海作波濤。"]', '["千巖万壑不辞勞，远看方知出处高。","溪澗豈能留得住，終归大海作波濤。"]', '诗', 'shi', '', NULL, '瀑布聯句 宣宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ffd7a8b-f55f-4dff-955f-d3a95fc5abfb', '句', '句', '004b8cf8-4ce4-4226-af20-28fddd009d90', '唐', '["海岳宴咸通，七載秉鈞調四序。","一方獄市獲來蘇。"]', '["海岳宴咸通，七載秉鈞調四序。","一方獄市獲来蘇。"]', '诗', 'shi', '', NULL, '句 宣宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0413c53-4729-431f-ae31-51ba5902dfe7', '詠雷句', '詠雷句', '35062aa9-2daf-40af-ac23-7dc63ea1a1ec', '唐', '["只解劈牛兼劈樹，不能誅惡與誅兇。"]', '["只解劈牛兼劈樹，不能誅惡與誅兇。"]', '诗', 'shi', '', NULL, '詠雷句 昭宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a25186df-0de3-49e6-81f2-2cc5c0853b43', '春遊曲', '春游曲', 'd630d1f7-be95-4074-901b-33d7aa9fb07f', '唐', '["上苑桃花朝日明，蘭閨豔妾動春情。","井上新桃偷面色，檐邊嫩柳學身輕。","花中來去看舞蝶，樹上長短聽啼鶯。","林下何須遠借問，出衆風流舊有名。"]', '["上苑桃花朝日明，蘭閨豔妾动春情。","井上新桃偷面色，檐邊嫩柳学身轻。","花中来去看舞蝶，樹上长短听啼鶯。","林下何須远借问，出衆风流旧有名。"]', '诗', 'shi', '', NULL, '春遊曲 文德皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('623de378-ac00-4dec-99c2-10e4668ff7ce', '曳鼎歌', '曳鼎歌', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["羲農首出，軒昊膺期。","唐虞繼踵，湯禹乘時。","天下光宅，海內雍熙。","上玄降鑒，方建隆基。"]', '["羲農首出，軒昊膺期。","唐虞繼踵，湯禹乘时。","天下光宅，海內雍熙。","上玄降鑒，方建隆基。"]', '诗', 'shi', '', NULL, '曳鼎歌 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23c871de-760f-4030-a5f2-3abe14c67d01', '唐享昊天樂 第一', '唐享昊天乐 第一', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["太陰凝至化，真耀蘊軒儀。","德邁娥臺敞，仁高[姒]幄披。","捫天遂啓極，夢日乃昇曦。"]', '["太陰凝至化，真耀蘊軒儀。","德邁娥台敞，仁高[姒]幄披。","捫天遂啓極，梦日乃昇曦。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第一 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3715888-a6cc-4332-b3fe-d8fa4a2f27be', '唐享昊天樂 第二', '唐享昊天乐 第二', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["瞻紫極，望玄穹。","翹至懇，罄深衷。","聽雖遠，誠必通。","垂厚澤，降雲宮。"]', '["瞻紫極，望玄穹。","翹至懇，罄深衷。","听雖远，誠必通。","垂厚澤，降云宮。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第二 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1644c7db-cc77-421d-a0bb-beed6030406e', '唐享昊天樂 第三', '唐享昊天乐 第三', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["乾儀混成沖邃，天道下濟高明。","闓陽晨披紫闕，太一曉降黃庭。","圜壇敢申昭報，方璧冀展虔情。","丹襟式敷衷懇，玄鑒庶察微誠。"]', '["乾儀混成沖邃，天道下濟高明。","闓陽晨披紫闕，太一晓降黄庭。","圜壇敢申昭報，方璧冀展虔情。","丹襟式敷衷懇，玄鑒庶察微誠。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第三 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fab579bd-1352-4182-94b7-884e42c83bc4', '唐享昊天樂 第四', '唐享昊天乐 第四', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["巍巍叡業廣，赫赫聖基隆。","菲德承先顧，禎符萃眇躬。","銘開武巖側，圖薦洛川中。","微誠詎幽感，景命忽昭融。","有懷慙紫極，無以謝玄穹。"]', '["巍巍叡業廣，赫赫聖基隆。","菲德承先顧，禎符萃眇躬。","銘开武巖側，圖薦洛川中。","微誠詎幽感，景命忽昭融。","有懷慙紫極，無以謝玄穹。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第四 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ceac26c-7518-4ff2-994d-106b88c860e3', '唐享昊天樂 第五', '唐享昊天乐 第五', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["朝壇霧卷，曙嶺煙沈。","爰設筐幣，式表誠心。","筵輝麗璧，樂暢和音。","仰惟靈鑒，俯察翹襟。"]', '["朝壇霧卷，曙嶺煙沈。","爰設筐幣，式表誠心。","筵輝丽璧，乐暢和音。","仰惟靈鑒，俯察翹襟。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第五 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c638cf2-866e-4573-aadf-ea5aaf6da04e', '唐享昊天樂 第六', '唐享昊天乐 第六', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["昭昭上帝，穆穆下臨。","禮崇備物，樂奏鏘金。","蘭羞委薦，桂醑盈斟。","敢希明德，幸罄莊心。"]', '["昭昭上帝，穆穆下臨。","禮崇備物，乐奏鏘金。","蘭羞委薦，桂醑盈斟。","敢希明德，幸罄莊心。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第六 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e5a7471-21a3-42f3-91ea-51700910fbb3', '唐享昊天樂 第七', '唐享昊天乐 第七', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["尊浮九醞，禮備三周。","陳誠菲奠，契福神猷。"]', '["尊浮九醞，禮備三周。","陳誠菲奠，契福神猷。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第七 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0704ea2-1e40-4d08-ba3e-0ec7e73169ee', '唐享昊天樂 第八', '唐享昊天乐 第八', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["奠璧郊壇昭大禮，鏘金拊石表虔誠。","始奏承雲娛帝賞，復歌調露暢韶英。"]', '["奠璧郊壇昭大禮，鏘金拊石表虔誠。","始奏承云娛帝賞，复歌調露暢韶英。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第八 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20970cd3-7041-486e-b7b5-3ec719f181b3', '唐享昊天樂 第九', '唐享昊天乐 第九', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["荷恩承顧託，執契恭臨撫。","廟略靜邊荒，天兵曜神武。","有截資先化，無爲遵舊矩。","禎符降昊穹，大業光寰宇。"]', '["荷恩承顧託，執契恭臨撫。","廟略静邊荒，天兵曜神武。","有截資先化，無爲遵旧矩。","禎符降昊穹，大業光寰宇。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第九 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20286700-303e-4d6f-96a8-39e528e2a9df', '唐享昊天樂 第十', '唐享昊天乐 第十', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["肅肅祀典，邕邕禮秩。","三獻已周，九成斯畢。","爰撤其俎，載遷其實。","或升或降，惟誠惟質。"]', '["肅肅祀典，邕邕禮秩。","三獻已周，九成斯畢。","爰撤其俎，載遷其實。","或升或降，惟誠惟質。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第十 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f14b9577-28a8-47e4-9085-9ffac7012bbc', '唐享昊天樂 第十一', '唐享昊天乐 第十一', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["禮終肆類，樂闋九成。","仰惟明德，敢薦非馨。","顧慙菲奠，久馳雲軿。","瞻荷靈澤，悚戀兼盈。"]', '["禮終肆類，乐闋九成。","仰惟明德，敢薦非馨。","顧慙菲奠，久驰云軿。","瞻荷靈澤，悚戀兼盈。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第十一 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94e6de39-7468-4b6a-9cb0-7be23b7a5ee4', '唐享昊天樂 第十二', '唐享昊天乐 第十二', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["式乾路，闢天扉。","迴日馭，動雲衣。","登金闕，入紫微。","望仙駕，仰恩徽。"]', '["式乾路，闢天扉。","迴日馭，动云衣。","登金闕，入紫微。","望仙駕，仰恩徽。"]', '诗', 'shi', '', NULL, '唐享昊天樂 第十二 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1d98eb6-0c36-429e-9646-32e9893e16ec', '唐明堂樂章 外辦將出', '唐明堂乐章 外辦將出', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["總章陳昔典，衢室禮惟神。","宏規則天地，神用叶陶鈞。","負扆三春旦，充庭萬宇賓。","顧己誠虛薄，空慙馭兆人。"]', '["總章陳昔典，衢室禮惟神。","宏規則天地，神用叶陶鈞。","負扆三春旦，充庭万宇賓。","顧己誠虛薄，空慙馭兆人。"]', '诗', 'shi', '', NULL, '唐明堂樂章 外辦將出 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96964fe2-9087-42a4-abe9-87cc8e846c59', '唐明堂樂章 皇帝行', '唐明堂乐章 皇帝行', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["仰膺曆數，俯順謳歌。","遠安邇肅，俗阜時和。","化光玉鏡，訟息金科。","方興典禮，永戢干戈。"]', '["仰膺曆數，俯順謳歌。","远安邇肅，俗阜时和。","化光玉镜，訟息金科。","方兴典禮，永戢干戈。"]', '诗', 'shi', '', NULL, '唐明堂樂章 皇帝行 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8800914f-7b85-488c-a18b-9cd4b51992f2', '唐明堂樂章 皇嗣出入升降', '唐明堂乐章 皇嗣出入升降', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["至人光俗，大孝通神。","謙以表性，恭惟立身。","洪規載啓，茂典方陳。","譽隆三善，祥開萬春。"]', '["至人光俗，大孝通神。","謙以表性，恭惟立身。","洪規載啓，茂典方陳。","譽隆三善，祥开万春。"]', '诗', 'shi', '', NULL, '唐明堂樂章 皇嗣出入升降 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9ad1795-2a0b-4397-8589-cb53fb7f65f1', '唐明堂樂章 迎送王公', '唐明堂乐章 迎送王公', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["千官肅事，萬國朝宗。","載延百辟，爰集三宮。","君臣德合，魚水斯同。","睿圖方永，周曆長隆。"]', '["千官肅事，万国朝宗。","載延百辟，爰集三宮。","君臣德合，鱼水斯同。","睿圖方永，周曆长隆。"]', '诗', 'shi', '', NULL, '唐明堂樂章 迎送王公 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e50e0711-540a-4496-a911-8118d2cb7250', '唐明堂樂章 登歌', '唐明堂乐章 登歌', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["禮崇宗祀，志表嚴禋。","笙鏞合奏，文物惟新。","敬遵茂典，敢擇良辰。","絜誠斯著，奠謁方申。"]', '["禮崇宗祀，志表嚴禋。","笙鏞合奏，文物惟新。","敬遵茂典，敢擇良辰。","絜誠斯著，奠謁方申。"]', '诗', 'shi', '', NULL, '唐明堂樂章 登歌 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f23da9b-b91b-4673-b628-562e0a371b16', '唐明堂樂章 配饗', '唐明堂乐章 配饗', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["笙鏞間玉宇，文物昭清輝。","晬影臨芳奠，休光下太微。","孝思期有感，明絜庶無違。"]', '["笙鏞间玉宇，文物昭清輝。","晬影臨芳奠，休光下太微。","孝思期有感，明絜庶無違。"]', '诗', 'shi', '', NULL, '唐明堂樂章 配饗 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1c6b056-1c6a-44d9-9e61-9fa5ef3029fb', '唐明堂樂章 宮音', '唐明堂乐章 宮音', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["履艮包羣望，居中冠百靈。","萬方資廣運，庶品荷財成。","神功諒匪測，盛德實難名。","藻奠申誠敬，恭祀表惟馨。"]', '["履艮包羣望，居中冠百靈。","万方資廣運，庶品荷財成。","神功諒匪測，盛德實难名。","藻奠申誠敬，恭祀表惟馨。"]', '诗', 'shi', '', NULL, '唐明堂樂章 宮音 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a692624e-ab66-4525-a082-b0e0a1025912', '唐明堂樂章 角音', '唐明堂乐章 角音', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["出震位，開平秩。","扇條風，乘甲乙。","龍德盛，鳥星出。","薦珪篚，陳誠實。"]', '["出震位，开平秩。","扇條风，乘甲乙。","龙德盛，鸟星出。","薦珪篚，陳誠實。"]', '诗', 'shi', '', NULL, '唐明堂樂章 角音 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6804729b-e657-4b19-b04a-300fcc6307ed', '唐明堂樂章 徵音', '唐明堂乐章 徵音', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["赫赫離精御炎陸，滔滔熾景開隆暑。","冀延神鑒俯蘭尊，式表虔襟陳桂俎。"]', '["赫赫離精御炎陸，滔滔熾景开隆暑。","冀延神鑒俯蘭尊，式表虔襟陳桂俎。"]', '诗', 'shi', '', NULL, '唐明堂樂章 徵音 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b61beb-de06-436f-8073-8b31ba88ec9a', '唐明堂樂章 商音', '唐明堂乐章 商音', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["律中夷則，序應收成。","功宣建武，義表惟明。","爰申禮奠，庶展翹誠。","九秋是式，百穀斯盈。"]', '["律中夷則，序應收成。","功宣建武，義表惟明。","爰申禮奠，庶展翹誠。","九秋是式，百穀斯盈。"]', '诗', 'shi', '', NULL, '唐明堂樂章 商音 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0fdbeaf-ac46-407c-a611-24775a378981', '唐明堂樂章 羽音', '唐明堂乐章 羽音', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["葭律肇啓隆冬，蘋藻攸陳饗祭。","黃鍾既陳玉燭，紅粒方殷稔歲。"]', '["葭律肇啓隆冬，蘋藻攸陳饗祭。","黄鍾既陳玉燭，紅粒方殷稔歲。"]', '诗', 'shi', '', NULL, '唐明堂樂章 羽音 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b838cc4b-fb09-4800-8a2b-e2de4ed1441a', '唐大饗拜洛樂章 昭和', '唐大饗拜洛乐章 昭和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["九玄眷命，三聖基隆。","奉成先旨，明臺畢功。","宗祀展敬，冀表深衷。","永昌帝業，式播淳風。"]', '["九玄眷命，三聖基隆。","奉成先旨，明台畢功。","宗祀展敬，冀表深衷。","永昌帝業，式播淳风。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 昭和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('095016f5-ecaf-4787-bb95-f971534eeaf9', '唐大饗拜洛樂章 致和', '唐大饗拜洛乐章 致和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["神功不測兮運陰陽，包藏萬宇兮孕八荒。","天符既出兮帝業昌，願臨明祀兮降禎祥。"]', '["神功不測兮運陰陽，包藏万宇兮孕八荒。","天符既出兮帝業昌，願臨明祀兮降禎祥。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 致和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64575578-6e0b-47f9-921e-0ec2ba44bd5e', '唐大饗拜洛樂章 咸和', '唐大饗拜洛乐章 咸和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["坎澤祠容備舉，坤壇祭典爰申。","靈睠遙行祕躅，嘉貺薦委殊珍。","肅禮恭禋載展，翹襟邈志逾殷。","方期交際懸應。"]', '["坎澤祠容備舉，坤壇祭典爰申。","靈睠遙行祕躅，嘉貺薦委殊珍。","肅禮恭禋載展，翹襟邈志逾殷。","方期交際懸應。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 咸和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c84ce639-d85c-45be-95c2-aac639e85efc', '唐大饗拜洛樂章 九和', '唐大饗拜洛乐章 九和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["祗荷坤德，欽若乾靈。","慙惕罔寘，興居匪寧。","恭崇禮則，肅奉儀形。","惟憑展敬，敢薦非馨。"]', '["祗荷坤德，欽若乾靈。","慙惕罔寘，兴居匪寧。","恭崇禮則，肅奉儀形。","惟憑展敬，敢薦非馨。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 九和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('245cb870-8fa7-4da0-9c49-ad680d1c38db', '唐大饗拜洛樂章 拜洛', '唐大饗拜洛乐章 拜洛', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["菲躬承睿顧，薄德忝坤儀。","乾乾遵後命，翼翼奉先規。","撫俗勤雖切，還淳化尚虧。","未能弘至道，何以契明祇。"]', '["菲躬承睿顧，薄德忝坤儀。","乾乾遵後命，翼翼奉先規。","撫俗勤雖切，還淳化尚虧。","未能弘至道，何以契明祇。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 拜洛 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('396fd7fa-de45-48e7-b379-0937f6429019', '唐大饗拜洛樂章 顯和', '唐大饗拜洛乐章 显和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["顧德有慙虛菲，明祇屢降禎符。","汜水初呈祕象，溫洛薦表昌圖。","玄澤流恩載洽，丹襟荷渥增愉。"]', '["顧德有慙虛菲，明祇屢降禎符。","汜水初呈祕象，溫洛薦表昌圖。","玄澤流恩載洽，丹襟荷渥增愉。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 顯和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a58856d5-d424-405a-957d-9b3206583c18', '唐大饗拜洛樂章 昭和', '唐大饗拜洛乐章 昭和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["舒云致養，合大資生。","德以恆固，功由永貞。","升歌薦序，垂幣翹誠。","虹開玉照，鳳引金聲。"]', '["舒云致養，合大資生。","德以恆固，功由永貞。","升歌薦序，垂幣翹誠。","虹开玉照，鳳引金声。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 昭和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c3546fa-1331-49aa-8f8e-4e5776359ef7', '唐大饗拜洛樂章 敬和', '唐大饗拜洛乐章 敬和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["蘭俎既升，蘋羞可薦。","金石載設，咸英已變。","林澤斯總，山川是徧。","敢用敷誠，實惟忘倦。"]', '["蘭俎既升，蘋羞可薦。","金石載設，咸英已变。","林澤斯總，山川是徧。","敢用敷誠，實惟忘倦。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 敬和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2578f05-3b91-436d-82b7-4f0ee3c3941f', '唐大饗拜洛樂章 齊和', '唐大饗拜洛乐章 齊和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["沈潛演貺分三極，廣大凝禎總萬方。","既薦羽旌文化啓，還呈干戚武威揚。"]', '["沈潛演貺分三極，廣大凝禎總万方。","既薦羽旌文化啓，還呈干戚武威揚。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 齊和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dcc4325-2ddf-44a9-b397-b33b9d084cb3', '唐大饗拜洛樂章 德和', '唐大饗拜洛乐章 德和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["夕惕同龍契，晨兢當鳳扆。","崇儒習舊規，偃伯循先旨。","絕壤飛冠蓋，遐區麗山水。","幸承三聖餘，忻屬千年始。"]', '["夕惕同龙契，晨兢當鳳扆。","崇儒習旧規，偃伯循先旨。","絕壤飞冠蓋，遐區丽山水。","幸承三聖餘，忻屬千年始。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 德和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('169ff044-695d-4889-b2d0-3c1bd70dfc6c', '唐大饗拜洛樂章 禋和', '唐大饗拜洛乐章 禋和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["百禮崇容，千官肅事。","靈降舞兆，神凝有粹。","奠享咸周，威儀畢備。","奏夏登列，歌雍撤肆。"]', '["百禮崇容，千官肅事。","靈降舞兆，神凝有粹。","奠享咸周，威儀畢備。","奏夏登列，歌雍撤肆。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 禋和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ee6bcb7-cb08-467c-91bd-ece8e555228c', '唐大饗拜洛樂章 通和', '唐大饗拜洛乐章 通和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["皇皇靈睠，穆穆神心。","暫動凝質，還歸積陰。","功玄樞紐，理寂高深。","銜恩佩德，聳志翹襟。"]', '["皇皇靈睠，穆穆神心。","暫动凝質，還归積陰。","功玄樞紐，理寂高深。","銜恩佩德，聳志翹襟。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 通和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d12c520-fd3c-4db1-ac44-f8475130ab63', '唐大饗拜洛樂章 歸和', '唐大饗拜洛乐章 归和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["言旋雲洞兮躡煙塗，永寧中宇兮安下都。","包涵動植兮順榮枯，長貽寶貺兮贊璇圖。"]', '["言旋云洞兮躡煙塗，永寧中宇兮安下都。","包涵动植兮順榮枯，长貽寶貺兮贊璇圖。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 歸和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab15b93a-75c9-4665-89a5-7c64bf2dc484', '唐大饗拜洛樂章 歸和', '唐大饗拜洛乐章 归和', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["調雲闋兮神座興，驂雲駕兮儼將升。","騰絳霄兮垂景祜，翹丹懇兮荷休徵。"]', '["調云闋兮神座兴，驂云駕兮儼將升。","腾絳霄兮垂景祜，翹丹懇兮荷休徵。"]', '诗', 'shi', '', NULL, '唐大饗拜洛樂章 歸和 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('167be2a8-7084-403c-b072-27a62233625e', '唐武氏享先廟樂章', '唐武氏享先廟乐章', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["先德謙撝冠昔，嚴規節素超今。","奉國忠誠每竭，承家至孝純深。","追崇懼乖尊意，顯號恐玷徽音。","既迫王公屢請，方乃俯遂羣心。","有限無由展敬，奠醑每闕親斟。","大禮虔申典冊，蘋藻敬薦翹襟。"]', '["先德謙撝冠昔，嚴規節素超今。","奉国忠誠每竭，承家至孝純深。","追崇懼乖尊意，显號恐玷徽音。","既迫王公屢請，方乃俯遂羣心。","有限無由展敬，奠醑每闕親斟。","大禮虔申典冊，蘋藻敬薦翹襟。"]', '诗', 'shi', '', NULL, '唐武氏享先廟樂章 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50321411-cd02-476d-bb62-f1e3f753481d', '早春夜宴', '早春夜宴', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["九春開上節，千門敞夜扉。","蘭燈吐新燄，桂魄朗圓輝。","送酒惟須滿，流杯不用稀。","務使霞漿興，方乘汎洛歸。"]', '["九春开上節，千门敞夜扉。","蘭灯吐新燄，桂魄朗圓輝。","送酒惟須满，流杯不用稀。","務使霞漿兴，方乘汎洛归。"]', '诗', 'shi', '', NULL, '早春夜宴 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b349c17-dac3-4bd8-9673-05f49cb96d0c', '遊九龍潭', '游九龙潭', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["山窗遊玉女，澗戶對瓊峰。","巖頂翔雙鳳，潭心倒九龍。","酒中浮竹葉，杯上寫芙蓉。","故驗家山賞，惟有風入松。"]', '["山窗游玉女，澗戶对瓊峰。","巖頂翔雙鳳，潭心倒九龙。","酒中浮竹葉，杯上寫芙蓉。","故驗家山賞，惟有风入松。"]', '诗', 'shi', '', NULL, '遊九龍潭 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebc91c19-1486-4a61-84fb-649eadef3f51', '贈胡天師', '贈胡天師', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["高人叶高志，山服往山家。","迢迢間風月，去去隔煙霞。","碧岫窺玄洞，玉竈鍊丹砂。","今日星津上，延首望靈槎。"]', '["高人叶高志，山服往山家。","迢迢间风月，去去隔煙霞。","碧岫窺玄洞，玉竈鍊丹砂。","今日星津上，延首望靈槎。"]', '诗', 'shi', '', NULL, '贈胡天師 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b4284f7-cfab-4ec2-abcf-11255250f325', '從駕幸少林寺', '從駕幸少林寺', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["陪鑾遊禁苑，侍賞出蘭闈。","雲偃攢峰蓋，霞低插浪旂。","日宮疏澗戶，月殿啓巖扉。","金輪轉金地，香閣曳香衣。","鐸吟輕吹發，幡搖薄霧霏。","昔遇焚芝火，山紅連野飛。","花臺無半影，蓮塔有全輝。","實賴能仁力，攸資善世威。","慈緣興福緒，於此罄歸依。","風枝不可靜，泣血竟何追。"]', '["陪鑾游禁苑，侍賞出蘭闈。","云偃攢峰蓋，霞低插浪旂。","日宮疏澗戶，月殿啓巖扉。","金輪轉金地，香閣曳香衣。","鐸吟轻吹發，幡搖薄霧霏。","昔遇焚芝火，山紅連野飞。","花台無半影，蓮塔有全輝。","實賴能仁力，攸資善世威。","慈緣兴福緒，於此罄归依。","风枝不可静，泣血竟何追。"]', '诗', 'shi', '', NULL, '從駕幸少林寺 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22a81685-1b2f-447b-aca0-27646037db90', '石淙', '石淙', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["三山十洞光玄籙，玉嶠金巒鎮紫微。","均露均霜標勝壤，交風交雨列皇畿。","萬仞高巖藏日色，千尋幽澗浴雲衣。","且駐歡筵賞仁智，琱鞍薄晚雜塵飛。"]', '["三山十洞光玄籙，玉嶠金巒鎮紫微。","均露均霜標勝壤，交风交雨列皇畿。","万仞高巖藏日色，千尋幽澗浴云衣。","且駐歡筵賞仁智，琱鞍薄晚杂塵飞。"]', '诗', 'shi', '', NULL, '石淙 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2b0e927-1ed7-4df6-9747-2c0d1f559cf0', '臘日宣詔幸上苑', '臘日宣詔幸上苑', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["明朝遊上苑，火急報春知。","花須連夜發，莫待曉風吹。"]', '["明朝游上苑，火急報春知。","花須連夜發，莫待晓风吹。"]', '诗', 'shi', '', NULL, '臘日宣詔幸上苑 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec37a853-d136-4093-9dc8-cfde84fae230', '如意娘', '如意娘', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["看朱成碧思紛紛，顦顇支離爲憶君。","不信比來長下淚，開箱驗取石榴裙。"]', '["看朱成碧思紛紛，顦顇支離爲憶君。","不信比来长下泪，开箱驗取石榴裙。"]', '诗', 'shi', '', NULL, '如意娘 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44493567-505b-484b-91b4-df069b09fc88', '製袍字賜狄仁傑', '製袍字賜狄仁傑', 'a9467a04-4b98-43ef-9f6b-79b13c0249ca', '唐', '["敷政術，守清勤。","升顯位，勵相臣。"]', '["敷政術，守清勤。","升显位，勵相臣。"]', '诗', 'shi', '', NULL, '製袍字賜狄仁傑 則天皇后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed8056df-5365-4a99-9364-34e685253390', '擬小山篇', '擬小山篇', 'f4b485ca-1544-40be-a2bd-c0c4f6e9c93b', '唐', '["仰幽巖而流盼，撫桂枝以凝想。","將千齡兮此遇，荃何爲兮獨往。"]', '["仰幽巖而流盼，撫桂枝以凝想。","將千齡兮此遇，荃何爲兮独往。"]', '诗', 'shi', '', NULL, '擬小山篇 徐賢妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac98d23-849c-4cdc-9c66-72fc3d6c87c7', '長門怨', '长门怨', 'f4b485ca-1544-40be-a2bd-c0c4f6e9c93b', '唐', '["舊愛柏梁臺，新寵昭陽殿。","守分辭芳輦，含情泣團扇。","一朝歌舞榮，夙昔詩書賤。","頹恩誠已矣，覆水難重薦。"]', '["旧愛柏梁台，新寵昭陽殿。","守分辞芳輦，含情泣團扇。","一朝歌舞榮，夙昔诗书賤。","頹恩誠已矣，覆水难重薦。"]', '诗', 'shi', '', NULL, '長門怨 徐賢妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a891f80d-fe12-429e-a820-3890a3c6af9e', '秋風函谷應詔', '秋风函谷應詔', 'f4b485ca-1544-40be-a2bd-c0c4f6e9c93b', '唐', '["秋風起函谷，勁氣動河山。","偃松千嶺上，雜雨二陵間。","低雲愁廣隰，落日慘重關。","此時飄紫氣，應驗真人還。"]', '["秋风起函谷，勁氣动河山。","偃松千嶺上，杂雨二陵间。","低云愁廣隰，落日慘重关。","此时飄紫氣，應驗真人還。"]', '诗', 'shi', '', NULL, '秋風函谷應詔 徐賢妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d46b6ce-5c89-4a0b-b496-c1718293fa90', '賦得北方有佳人', '賦得北方有佳人', 'f4b485ca-1544-40be-a2bd-c0c4f6e9c93b', '唐', '["由來稱獨立，本自號傾城。","柳葉眉間發，桃花臉上生。","腕搖金釧響，步轉玉環鳴。","纖腰宜寶袜，紅衫豔織成。","懸知一顧重，別覺舞腰輕。"]', '["由来稱独立，本自號傾城。","柳葉眉间發，桃花臉上生。","腕搖金釧响，步轉玉环鳴。","纖腰宜寶袜，紅衫豔织成。","懸知一顧重，別覺舞腰轻。"]', '诗', 'shi', '', NULL, '賦得北方有佳人 徐賢妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8410fa94-bfb9-4217-8bbd-f20a35b357fe', '進太宗', '進太宗', 'f4b485ca-1544-40be-a2bd-c0c4f6e9c93b', '唐', '["朝來臨鏡臺，粧罷暫裴回。","千金始一笑，一召詎能來。"]', '["朝来臨镜台，粧罷暫裴回。","千金始一笑，一召詎能来。"]', '诗', 'shi', '', NULL, '進太宗 徐賢妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595cdc85-b376-45d2-97fc-fb7e946ab5fd', '奉和聖製立春日侍宴內殿出翦綵花應制', '奉和聖製立春日侍宴內殿出翦綵花應制', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["密葉因裁吐，新花逐翦舒。","攀條雖不謬，摘橤詎知虛。","春至由來發，秋還未肯疎。"]', '["密葉因裁吐，新花逐翦舒。","攀條雖不謬，摘橤詎知虛。","春至由来發，秋還未肯疎。"]', '诗', 'shi', '', NULL, '奉和聖製立春日侍宴內殿出翦綵花應制 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81981192-77b7-407d-ab89-18ebf00d8de4', '九月九日上幸慈恩寺登浮圖羣臣上菊花壽酒', '九月九日上幸慈恩寺登浮圖羣臣上菊花壽酒', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["帝里重陽節，香園萬乘來。","卻邪萸入佩，獻壽菊傳杯。","墖類承天湧，門疑待佛開。","睿詞懸日月，長得仰昭回。"]', '["帝里重陽節，香园万乘来。","卻邪萸入佩，獻壽菊傳杯。","墖類承天湧，门疑待佛开。","睿词懸日月，长得仰昭回。"]', '诗', 'shi', '', NULL, '九月九日上幸慈恩寺登浮圖羣臣上菊花壽酒 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e0d5bc9-dc63-4c00-9409-8ff3c7e66140', '綵書怨', '綵书怨', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["葉下洞庭初，思君萬里餘。","露濃香被冷，月落錦屏虛。","欲奏江南曲，貪封薊北書。","書中無別意，惟悵久離居。"]', '["葉下洞庭初，思君万里餘。","露濃香被冷，月落錦屏虛。","欲奏江南曲，貪封薊北书。","书中無別意，惟悵久離居。"]', '诗', 'shi', '', NULL, '綵書怨 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f1f308b-60d8-4cd0-987b-a8c0d02801cd', '駕幸三會寺應制', '駕幸三會寺應制', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["釋子談經處，軒臣刻字留。","故臺遺老識，殘簡聖皇求。","駐蹕懷千古，開襟望九州。","四山緣塞合，二水夾城流。","宸翰陪瞻仰，天杯接獻酬。","太平詞藻盛，長願紀鴻休。"]', '["釋子談經处，軒臣刻字留。","故台遺老識，殘簡聖皇求。","駐蹕懷千古，开襟望九州。","四山緣塞合，二水夾城流。","宸翰陪瞻仰，天杯接獻酬。","太平词藻盛，长願紀鴻休。"]', '诗', 'shi', '', NULL, '駕幸三會寺應制 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcad32a8-54b7-4b67-b811-bb0f46d1428b', '駕幸新豐溫泉宮獻詩三首 一', '駕幸新豐溫泉宮獻诗三首 一', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["三冬季月景[龍]年，萬乘觀風出灞川。","遙看電躍龍爲馬，回矚霜原玉作田。"]', '["三冬季月景[龙]年，万乘观风出灞川。","遙看電躍龙爲马，回矚霜原玉作田。"]', '诗', 'shi', '', NULL, '駕幸新豐溫泉宮獻詩三首 一 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47e4501e-c5e4-4074-90db-2cd50aeaf708', '駕幸新豐溫泉宮獻詩三首 二', '駕幸新豐溫泉宮獻诗三首 二', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["鸞旂掣曳拂空回，羽騎驂驔躡景來。","隱隱驪山雲外聳，迢迢御帳日邊開。"]', '["鸾旂掣曳拂空回，羽騎驂驔躡景来。","隐隐驪山云外聳，迢迢御帳日邊开。"]', '诗', 'shi', '', NULL, '駕幸新豐溫泉宮獻詩三首 二 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9686d740-a96f-4a0c-834b-c83db48d33e4', '駕幸新豐溫泉宮獻詩三首 三', '駕幸新豐溫泉宮獻诗三首 三', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["翠幕珠幃敞月營，金罍玉斝泛蘭英。","歲歲年年常扈蹕，長長久久樂升平。"]', '["翠幕珠幃敞月營，金罍玉斝泛蘭英。","歲歲年年常扈蹕，长长久久乐升平。"]', '诗', 'shi', '', NULL, '駕幸新豐溫泉宮獻詩三首 三 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('788b3936-5fdc-4ee4-b414-f9ab803c95f9', '遊長寧公主流杯池二十五首 一', '游长寧公主流杯池二十五首 一', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["逐仙賞，展幽情。","踰崑閬，邁蓬瀛。"]', '["逐仙賞，展幽情。","踰崑閬，邁蓬瀛。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 一 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39d21a74-e45e-4c99-bd65-40a41a38ed7e', '遊長寧公主流杯池二十五首 二', '游长寧公主流杯池二十五首 二', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["遊魯館，陟秦臺。","汚山壁，媿瓊瓌。"]', '["游魯館，陟秦台。","汚山壁，媿瓊瓌。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 二 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06f8cae4-3045-45f8-ae8b-01eddcfd4fcf', '遊長寧公主流杯池二十五首 三', '游长寧公主流杯池二十五首 三', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["檀欒竹影，飆䫻松聲。","不煩歌吹，自足娛情。"]', '["檀欒竹影，飆䫻松声。","不煩歌吹，自足娛情。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 三 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f696fcf6-52a5-4637-bf2e-0feda4325bc6', '遊長寧公主流杯池二十五首 四', '游长寧公主流杯池二十五首 四', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["仰循茅宇，俯眄喬枝。","煙霞問訊，風月相知。"]', '["仰循茅宇，俯眄喬枝。","煙霞问訊，风月相知。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 四 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87f585dd-729d-45be-bdba-a6ea474ceefb', '遊長寧公主流杯池二十五首 五', '游长寧公主流杯池二十五首 五', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["枝條鬱鬱，文質彬彬。","山林作伴，松桂爲鄰。"]', '["枝條鬱鬱，文質彬彬。","山林作伴，松桂爲鄰。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 五 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2387aa85-45b4-4884-baf8-83de0d071285', '遊長寧公主流杯池二十五首 六', '游长寧公主流杯池二十五首 六', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["清波洶湧，碧樹冥蒙。","莫怪留步，因攀桂叢。"]', '["清波洶湧，碧樹冥蒙。","莫怪留步，因攀桂叢。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 六 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c43d47da-630c-4a86-bcf4-f9abf991b6c7', '遊長寧公主流杯池二十五首 七', '游长寧公主流杯池二十五首 七', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["莫論圓嶠，休說方壺。","何如魯館，即是仙都。"]', '["莫論圓嶠，休说方壺。","何如魯館，即是仙都。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 七 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6bc732b-e080-4c0c-b1a1-9902374c0372', '遊長寧公主流杯池二十五首 八', '游长寧公主流杯池二十五首 八', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["玉環騰遠創，金埒荷殊榮。","弗玩珠璣飾，仍留仁智情。","鑿山便作室，憑樹即爲楹。","公輸與班爾，從此遂韜聲。"]', '["玉环腾远創，金埒荷殊榮。","弗玩珠璣飾，仍留仁智情。","鑿山便作室，憑樹即爲楹。","公輸與班爾，從此遂韜声。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 八 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11e3a24-c739-4054-b66f-2d7ae8ca09dd', '遊長寧公主流杯池二十五首 九', '游长寧公主流杯池二十五首 九', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["登山一長望，正遇九春初。","結駟填街術，閭閻滿邑居。","鬬雪梅先吐，驚風柳未舒。","直愁斜日落，不畏酒尊虛。"]', '["登山一长望，正遇九春初。","結駟填街術，閭閻满邑居。","鬬雪梅先吐，驚风柳未舒。","直愁斜日落，不畏酒尊虛。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 九 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('050572f1-02f6-40f3-8318-dbe7f8353a84', '遊長寧公主流杯池二十五首 十', '游长寧公主流杯池二十五首 十', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["霽曉氣清和，披襟賞薜蘿。","玳瑁凝春色，琉璃漾水波。","跂石聊長嘯，攀松乍短歌。","除非物外者，誰就此經過。"]', '["霽晓氣清和，披襟賞薜蘿。","玳瑁凝春色，琉璃漾水波。","跂石聊长嘯，攀松乍短歌。","除非物外者，誰就此經過。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 十 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cec1b138-6e5a-4e43-963b-7dae24a295fc', '遊長寧公主流杯池二十五首 十一', '游长寧公主流杯池二十五首 十一', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["暫爾遊山第，淹留惜未歸。","霞窗明月滿，澗戶白雲飛。","書引藤爲架，人將薜作衣。","此真攀玩所，臨睨賞光輝。"]', '["暫爾游山第，淹留惜未归。","霞窗明月满，澗戶白云飞。","书引藤爲架，人將薜作衣。","此真攀玩所，臨睨賞光輝。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 十一 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c9271d7-7837-4f32-ac69-2d78708665f6', '遊長寧公主流杯池二十五首 十二', '游长寧公主流杯池二十五首 十二', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["放曠出煙雲，蕭條自不羣。","漱流清意府，隱几避嚻氛。","石畫妝苔色，風梭織水文。","山室何爲貴？唯餘蘭桂熏。"]', '["放曠出煙云，蕭條自不羣。","漱流清意府，隐几避嚻氛。","石畫妝苔色，风梭织水文。","山室何爲貴？唯餘蘭桂熏。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 十二 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('202f8187-f247-41cc-84dc-29c91d4ba11c', '遊長寧公主流杯池二十五首 十三', '游长寧公主流杯池二十五首 十三', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["策杖臨霞岫，危步下霜蹊。","志逐深山靜，途隨曲澗迷。","漸覺心神逸，俄看雲霧低。","莫怪人題樹，祗爲賞幽棲。"]', '["策杖臨霞岫，危步下霜蹊。","志逐深山静，途隨曲澗迷。","漸覺心神逸，俄看云霧低。","莫怪人題樹，祗爲賞幽棲。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 十三 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75cab210-6be6-4de7-905e-4ca56e574ac5', '遊長寧公主流杯池二十五首 十四', '游长寧公主流杯池二十五首 十四', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["攀藤招逸客，偃桂協幽情。","水中看樹影，風裏聽松聲。"]', '["攀藤招逸客，偃桂協幽情。","水中看樹影，风裏听松声。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 十四 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d54a5d9e-3996-4c1a-b83f-921c73221c4b', '遊長寧公主流杯池二十五首 十五', '游长寧公主流杯池二十五首 十五', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["攜琴侍叔夜，負局訪安期。","不應題石壁，爲記賞山時。"]', '["携琴侍叔夜，負局訪安期。","不應題石壁，爲記賞山时。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 十五 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f44c2a8c-9a5a-4056-a0f0-a6b06e943b1e', '遊長寧公主流杯池二十五首 十六', '游长寧公主流杯池二十五首 十六', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["泉石多仙趣，巖壑寫奇形。","欲知堪悅耳，唯聽水泠泠。"]', '["泉石多仙趣，巖壑寫奇形。","欲知堪悅耳，唯听水泠泠。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 十六 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f7d5fe-12aa-4b61-bc09-5a53316f474f', '遊長寧公主流杯池二十五首 十七', '游长寧公主流杯池二十五首 十七', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["巖壑恣登臨，瑩目復怡心。","風篁類長笛，流水當鳴琴。"]', '["巖壑恣登臨，瑩目复怡心。","风篁類长笛，流水當鳴琴。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 十七 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55c1a855-991d-44ed-8671-73733b0697fa', '遊長寧公主流杯池二十五首 十八', '游长寧公主流杯池二十五首 十八', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["嬾步天台路，惟登地肺山。","幽巖仙桂滿，今日恣情攀。"]', '["嬾步天台路，惟登地肺山。","幽巖仙桂满，今日恣情攀。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 十八 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd4c3198-29e8-4d2a-bdb1-184ba15f7d3d', '遊長寧公主流杯池二十五首 十九', '游长寧公主流杯池二十五首 十九', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["暫遊仁智所，蕭然松桂情。","寄言棲遯客，勿復訪蓬瀛。"]', '["暫游仁智所，蕭然松桂情。","寄言棲遯客，勿复訪蓬瀛。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 十九 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ba02423-e8b6-491d-8478-4d2fe15eca91', '遊長寧公主流杯池二十五首 二十', '游长寧公主流杯池二十五首 二十', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["瀑溜晴疑雨，叢篁晝似昏。","山中真可玩，暫請報王孫。"]', '["瀑溜晴疑雨，叢篁晝似昏。","山中真可玩，暫請報王孫。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 二十 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0279adf4-af13-41e9-b12a-a094f2860a06', '遊長寧公主流杯池二十五首 二十一', '游长寧公主流杯池二十五首 二十一', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["傍池聊試筆，倚石旋題詩。","豫彈山水調，終擬從鍾期。"]', '["傍池聊試笔，倚石旋題诗。","豫彈山水調，終擬從鍾期。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 二十一 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38bcda3c-a23f-4906-acd7-bcda8ec8bc2c', '遊長寧公主流杯池二十五首 二十二', '游长寧公主流杯池二十五首 二十二', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["橫鋪豹皮褥，側帶鹿胎巾。","借問何爲者，山中有逸人。"]', '["橫鋪豹皮褥，側带鹿胎巾。","借问何爲者，山中有逸人。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 二十二 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfbe3236-35b2-48c1-b9e2-8785bfbc2e09', '遊長寧公主流杯池二十五首 二十三', '游长寧公主流杯池二十五首 二十三', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["沁水田園先自多，齊城樓觀更無過。","倩語張騫莫辛苦，人今從此識天河。"]', '["沁水田园先自多，齊城楼观更無過。","倩語張騫莫辛苦，人今從此識天河。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 二十三 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('991314e4-fee9-4758-9d63-917d9283f3f8', '遊長寧公主流杯池二十五首 二十四', '游长寧公主流杯池二十五首 二十四', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["參差碧岫聳蓮花，潺湲綠水瑩金沙。","何須遠訪三山路，人今已到九仙家。"]', '["參差碧岫聳蓮花，潺湲綠水瑩金沙。","何須远訪三山路，人今已到九仙家。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 二十四 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1247751-df1c-4685-af76-18058f7df051', '遊長寧公主流杯池二十五首 二十五', '游长寧公主流杯池二十五首 二十五', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["憑高瞰險足怡心，菌閣桃源不暇尋。","餘雪依林成玉樹，殘霙點岫即瑤岑。"]', '["憑高瞰險足怡心，菌閣桃源不暇尋。","餘雪依林成玉樹，殘霙点岫即瑤岑。"]', '诗', 'shi', '', NULL, '遊長寧公主流杯池二十五首 二十五 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce68cb98-d933-4ddd-a4f5-6ced5062c361', '句', '句', 'bd995deb-f5be-465f-bc1f-9348f0ae3631', '唐', '["勢如連璧友，心似臭蘭人。"]', '["勢如連璧友，心似臭蘭人。"]', '诗', 'shi', '', NULL, '句 上官昭容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('225f48d3-f1c0-4917-bbee-32aa163d5077', '贈張雲容舞', '贈張云容舞', '02ab63b8-2a8c-4205-aa8b-df59281a4a34', '唐', '["羅袖動香香不已，紅蕖褭褭秋煙裏。","輕雲嶺上乍搖風，嫩柳池邊初拂水。"]', '["羅袖动香香不已，紅蕖褭褭秋煙裏。","轻云嶺上乍搖风，嫩柳池邊初拂水。"]', '诗', 'shi', '', NULL, '贈張雲容舞 楊貴妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06c84041-b4d9-4317-8d51-863fe37b087b', '謝賜珍珠', '謝賜珍珠', '22a1cda8-b2f5-493c-b71b-0885512b4bfd', '唐', '["桂葉雙眉久不描，殘妝和淚汚紅綃。","長門盡日無梳洗，何必珍珠慰寂寥。"]', '["桂葉雙眉久不描，殘妝和泪汚紅綃。","长门尽日無梳洗，何必珍珠慰寂寥。"]', '诗', 'shi', '', NULL, '謝賜珍珠 江妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef8c04bf-a29b-4537-bebb-256c6604126c', '黃臺瓜辭', '黄台瓜辞', '0fc43481-64f8-4539-82e0-3dc7c4038e96', '唐', '["種瓜黃臺下，瓜熟子離離。","一摘使瓜好，再摘使瓜稀。","三摘猶自可，摘絕抱蔓歸。"]', '["種瓜黄台下，瓜熟子離離。","一摘使瓜好，再摘使瓜稀。","三摘猶自可，摘絕抱蔓归。"]', '诗', 'shi', '', NULL, '黃臺瓜辭 章懷太子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aee9434-79c4-44ec-a455-d3b9749a4ac6', '奉和同太子監守違戀', '奉和同太子監守違戀', '95a60ce7-b2b7-44e2-a176-bb3b4ddcdf42', '唐', '["乾象開層構，離明啓少陽。","卜征從獻吉，守器屬元良。","逖矣凌周誦，遙哉掩漢莊。","好士傾南洛，多才盛北場。","地分丹鷲嶺，途間白雲鄉。","儲誠虔曉夕，宸愛積炎涼。","珠璧連霄漢，萬物仰重光。"]', '["乾象开層構，離明啓少陽。","卜征從獻吉，守器屬元良。","逖矣凌周誦，遙哉掩漢莊。","好士傾南洛，多才盛北場。","地分丹鷲嶺，途间白云乡。","儲誠虔晓夕，宸愛積炎涼。","珠璧連霄漢，万物仰重光。"]', '诗', 'shi', '', NULL, '奉和同太子監守違戀 韓王元嘉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98d6b63d-b3c2-4875-95d1-00bf11b0cff1', '奉和聖製過溫湯', '奉和聖製過溫湯', '5582aaf6-e865-44b4-97d4-1a4f2f7e3d1e', '唐', '["鳳輦騰宸駕，驪籞次乾遊。","坎德疎溫液，山隈派暖流。","寒氛空外擁，蒸氣沼中浮。","林凋帷影散，雲斂蓋陰收。","霜郊暢玄覽，參差落景遒。"]', '["鳳輦腾宸駕，驪籞次乾游。","坎德疎溫液，山隈派暖流。","寒氛空外擁，蒸氣沼中浮。","林凋帷影散，云斂蓋陰收。","霜郊暢玄覽，參差落景遒。"]', '诗', 'shi', '', NULL, '奉和聖製過溫湯 越王貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a02904-d561-4be5-9d9a-296456744bcf', '石橋', '石橋', '11b1b1bf-0ff9-4978-9b81-b09fe3bc9c22', '唐', '["別有經行所，迥跨重巒側。","粵因求瘼餘，倏想尋真域。","放情恣披拂，杖策聊□□。","□□□□□，□□□□色。","亂幡霧中見，雁塔雲間識。","薄煙冪遠郊，遙峰沒歸翼。","仙橋危石架，幽洞乘□□。","□□□□□，□□□易測。","二教無先後，一相平而直。","冀茲捐俗心，永懷依妙力。"]', '["別有經行所，迥跨重巒側。","粵因求瘼餘，倏想尋真域。","放情恣披拂，杖策聊□□。","□□□□□，□□□□色。","亂幡霧中见，雁塔云间識。","薄煙冪远郊，遙峰沒归翼。","仙橋危石架，幽洞乘□□。","□□□□□，□□□易測。","二教無先後，一相平而直。","冀茲捐俗心，永懷依妙力。"]', '诗', 'shi', '', NULL, '石橋 信安王禕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c19167f-da19-47bb-94d1-dc3b6d648acf', '虛池驛題屏風', '虛池驛題屏风', '4d94a062-239f-4a74-b13c-3702e66a33bd', '唐', '["出嫁辭鄉國，由來此別難。","聖恩愁遠道，行路泣相看。","沙塞容顏盡，邊隅粉黛殘。","妾心何所斷，他日望長安。"]', '["出嫁辞乡国，由来此別难。","聖恩愁远道，行路泣相看。","沙塞容顏尽，邊隅粉黛殘。","妾心何所斷，他日望长安。"]', '诗', 'shi', '', NULL, '虛池驛題屏風 宜芬公主 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b0e2a03-4c0b-4808-a4d4-9752daad3ca4', '嘲陸暢', '嘲陸暢', '6e18dba1-0735-49c2-8c28-dcf9942b4749', '唐', '["十二層樓倚翠空，鳳鸞相對立梧桐。","雙成走報監門衛，莫使吳歈入漢宮。"]', '["十二層楼倚翠空，鳳鸾相对立梧桐。","雙成走報監门衛，莫使吳歈入漢宮。"]', '诗', 'shi', '', NULL, '嘲陸暢 女學士宋氏若華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a5d0a21-2700-46ec-b018-e7dc9329251e', '奉和御製麟德殿宴百僚應制', '奉和御製麟德殿宴百僚應制', 'f7cb7b8a-0fc0-4f95-9449-222a0f26f6f3', '唐', '["垂衣臨八極，肅穆四門通。","自是無爲化，非關輔弼功。","修文招隱伏，尚武殄妖兇。","德炳韶光熾，恩霑雨露濃。","衣冠陪御宴，禮樂盛朝宗。","萬壽稱觴舉，千年信一同。"]', '["垂衣臨八極，肅穆四门通。","自是無爲化，非关輔弼功。","修文招隐伏，尚武殄妖兇。","德炳韶光熾，恩霑雨露濃。","衣冠陪御宴，禮乐盛朝宗。","万壽稱觴舉，千年信一同。"]', '诗', 'shi', '', NULL, '奉和御製麟德殿宴百僚應制 尚宮宋氏若昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d4d8cf5-599f-45b8-bc1d-f337a1f7e5ba', '奉和御製麟德殿宴百官', '奉和御製麟德殿宴百官', '8cd7d86d-8de4-4e43-abe9-cc8e9141e501', '唐', '["端拱承休命，時清荷聖皇。","四聰聞受諫，五服遠朝王。","景媚鶯初囀，春殘日更長。","命筵多濟濟，盛樂復鏘鏘。","酆鎬誰將敵，橫汾未可方。","願齊山嶽壽，祉福永無疆。"]', '["端拱承休命，时清荷聖皇。","四聰闻受諫，五服远朝王。","景媚鶯初囀，春殘日更长。","命筵多濟濟，盛乐复鏘鏘。","酆鎬誰將敵，橫汾未可方。","願齊山嶽壽，祉福永無疆。"]', '诗', 'shi', '', NULL, '奉和御製麟德殿宴百官 尚宮宋氏若憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c495ed-8887-4294-9e38-2499b629c3e9', '奉和麟德殿宴百僚應[制]', '奉和麟德殿宴百僚應[制]', '14d66dc8-3116-4818-8808-0ccc3f2f9a9a', '唐', '["睿澤先寰海，功成展武韶。","戈鋋清外壘，文物盛中朝。","聖祚山河固，宸章日月昭。","玉筵鸞鵠集，仙管鳳皇調。","御柳新低綠，宮鶯乍囀嬌。","願將[億]兆慶，千祀奉神堯。"]', '["睿澤先寰海，功成展武韶。","戈鋋清外壘，文物盛中朝。","聖祚山河固，宸章日月昭。","玉筵鸾鵠集，仙管鳳皇調。","御柳新低綠，宮鶯乍囀嬌。","願將[億]兆慶，千祀奉神堯。"]', '诗', 'shi', '', NULL, '奉和麟德殿宴百僚應[制] 鮑氏君徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59e2fe4b-c925-4b3e-851d-e1c355c43b98', '關山月', '关山月', '14d66dc8-3116-4818-8808-0ccc3f2f9a9a', '唐', '["高高秋月明，北照遼陽城。","塞迥光初滿，風多暈更生。","征人望鄉思，戰馬聞鼙驚。","朔風悲邊草，胡沙暗虜營。","霜凝匣中劒，風憊原上旌。","早晚謁金闕，不聞刁斗聲。"]', '["高高秋月明，北照遼陽城。","塞迥光初满，风多暈更生。","征人望乡思，戰马闻鼙驚。","朔风悲邊草，胡沙暗虜營。","霜凝匣中劒，风憊原上旌。","早晚謁金闕，不闻刁斗声。"]', '诗', 'shi', '', NULL, '關山月 鮑氏君徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ff83e4f-cf78-4123-8a0c-4e39cb867020', '惜花吟', '惜花吟', '14d66dc8-3116-4818-8808-0ccc3f2f9a9a', '唐', '["枝上花，花下人，可憐顏色俱青春。","昨日看花花灼灼，今朝看花花欲落。","不如盡此花下歡，莫待春風總吹卻。","鶯歌蝶舞韶光長，紅爐煑茗松花香。","妝成罷吟恣遊後，獨把芳枝歸洞房。"]', '["枝上花，花下人，可怜顏色俱青春。","昨日看花花灼灼，今朝看花花欲落。","不如尽此花下歡，莫待春风總吹卻。","鶯歌蝶舞韶光长，紅爐煑茗松花香。","妝成罷吟恣游後，独把芳枝归洞房。"]', '诗', 'shi', '', NULL, '惜花吟 鮑氏君徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e01605-620b-4b86-acd4-02e10ae12e89', '東亭茶宴', '东亭茶宴', '14d66dc8-3116-4818-8808-0ccc3f2f9a9a', '唐', '["閑朝向曉出簾櫳，茗宴東亭四望通。","遠眺城池山色裏，俯聆絃管水聲中。","幽篁引沼新抽翠，芳槿低檐欲吐紅。","坐久此中無限興，更憐團扇起清風。"]', '["闲朝向晓出簾櫳，茗宴东亭四望通。","远眺城池山色裏，俯聆絃管水声中。","幽篁引沼新抽翠，芳槿低檐欲吐紅。","坐久此中無限兴，更怜團扇起清风。"]', '诗', 'shi', '', NULL, '東亭茶宴 鮑氏君徽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bc25c25-81f9-4003-8592-9f413774e85f', '夜夢', '夜梦', 'ce52be3d-02e4-482a-aa83-db157bb14517', '唐', '["昨日夢君歸，賤妾下鳴機。","極知意氣薄，不著去時衣。","故言如夢裏，賴得雁書飛。"]', '["昨日梦君归，賤妾下鳴機。","極知意氣薄，不著去时衣。","故言如梦裏，賴得雁书飞。"]', '诗', 'shi', '', NULL, '夜夢 蕭妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a4385e9-97c5-4425-8c96-472b0fea4cf9', '詠燈', '詠灯', 'b52bd799-9942-47b6-b1bc-066528e44c99', '唐', '["一點分明值萬金，開時惟怕冷風侵。","主人若也勤挑撥，敢向尊前不盡心。"]', '["一点分明值万金，开时惟怕冷风侵。","主人若也勤挑撥，敢向尊前不尽心。"]', '诗', 'shi', '', NULL, '詠燈 南唐先主李昪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1ea09bb-0ca8-4ec2-b9ee-f1299f878734', '遊後湖賞蓮花', '游後湖賞蓮花', '3ff153ed-63bb-4b78-824b-4476266c29bf', '唐', '["蓼花蘸水火不滅，水鳥驚魚銀梭投。","滿目荷花千萬頃，紅碧相雜敷清流。","孫武已斬吳宮女，琉璃池上佳人頭。"]', '["蓼花蘸水火不滅，水鸟驚鱼銀梭投。","满目荷花千万頃，紅碧相杂敷清流。","孫武已斬吳宮女，琉璃池上佳人头。"]', '诗', 'shi', '', NULL, '遊後湖賞蓮花 嗣主璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6631944-18f1-4767-a2d4-77b1516758cd', '保大五年元日大雪同太弟景遂汪王景逷齊王景逵進士李建勳中書徐鉉勤政殿學士張義方登樓賦', '保大五年元日大雪同太弟景遂汪王景逷齊王景逵進士李建勳中书徐鉉勤政殿学士張義方登楼賦', '3ff153ed-63bb-4b78-824b-4476266c29bf', '唐', '["珠簾高卷莫輕遮，往往相逢隔歲華。","春氣昨宵飄律管，東風今日放梅花。","素姿好把芳姿掩，落勢還同舞勢斜。","坐有賓朋尊有酒，可憐清味屬儂家。"]', '["珠簾高卷莫轻遮，往往相逢隔歲华。","春氣昨宵飄律管，东风今日放梅花。","素姿好把芳姿掩，落勢還同舞勢斜。","坐有賓朋尊有酒，可怜清味屬儂家。"]', '诗', 'shi', '', NULL, '保大五年元日大雪同太弟景遂汪王景逷齊王景逵進士李建勳中書徐鉉勤政殿學士張義方登樓賦 嗣主璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c236f02-7a4d-41c6-ac4f-ae6f2cc9887f', '句', '句', '3ff153ed-63bb-4b78-824b-4476266c29bf', '唐', '["靈槎思浩蕩，老鶴倚崆峒。","蒼苔迷古道，紅葉亂朝霞。","棲鳳枝梢猶輭弱，化龍形狀已依稀。"]', '["靈槎思浩蕩，老鹤倚崆峒。","蒼苔迷古道，紅葉亂朝霞。","棲鳳枝梢猶輭弱，化龙形狀已依稀。"]', '诗', 'shi', '', NULL, '句 嗣主璟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89667d89-cd91-4777-b087-e51873cc3823', '九月十日偶書', '九月十日偶书', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["晚雨秋陰酒乍醒，感時心緒杳難平。","黃花冷落不成豔，紅葉颼飀競鼓聲。","背世返能厭俗態，偶緣猶未忘多情。","自從雙鬢斑斑白，不學安仁卻自驚。"]', '["晚雨秋陰酒乍醒，感时心緒杳难平。","黄花冷落不成豔，紅葉颼飀競鼓声。","背世返能厭俗態，偶緣猶未忘多情。","自從雙鬢斑斑白，不学安仁卻自驚。"]', '诗', 'shi', '', NULL, '九月十日偶書 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05d03b46-d786-4acf-995e-a20721f16583', '秋鶯', '秋鶯', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["殘鶯何事不知秋，橫過幽林尚獨遊。","老舌百般傾耳聽，深黃一點入煙流。","棲遲背世同悲魯，瀏亮如笙碎在緱。","莫更留連好歸去，露華淒冷蓼花愁。"]', '["殘鶯何事不知秋，橫過幽林尚独游。","老舌百般傾耳听，深黄一点入煙流。","棲遲背世同悲魯，瀏亮如笙碎在緱。","莫更留連好归去，露华淒冷蓼花愁。"]', '诗', 'shi', '', NULL, '秋鶯 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5067fb0b-3f4d-4498-a7a6-a49dd0446067', '病起題山舍壁', '病起題山舍壁', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["山舍初成病乍輕，杖藜巾褐稱閑情。","爐開小火深回暖，溝引新流幾曲聲。","暫約彭涓安朽質，終期宗遠問無生。","誰能役役塵中累，貪合魚龍搆強名。"]', '["山舍初成病乍轻，杖藜巾褐稱闲情。","爐开小火深回暖，溝引新流幾曲声。","暫約彭涓安朽質，終期宗远问無生。","誰能役役塵中累，貪合鱼龙搆強名。"]', '诗', 'shi', '', NULL, '病起題山舍壁 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae40f021-8209-4019-a612-4c477e4c12be', '送鄧王二十弟從益牧宣城', '送鄧王二十弟從益牧宣城', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["且維輕舸更遲遲，別酒重傾惜解攜。","浩浪侵愁光蕩漾，亂山凝恨色高低。","君馳檜楫情何極，我凭闌干日向西。","咫尺煙江幾多地，不須懷抱重淒淒。"]', '["且維轻舸更遲遲，別酒重傾惜解携。","浩浪侵愁光蕩漾，亂山凝恨色高低。","君驰檜楫情何極，我凭闌干日向西。","咫尺煙江幾多地，不須懷抱重淒淒。"]', '诗', 'shi', '', NULL, '送鄧王二十弟從益牧宣城 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6533dc36-cc73-4798-b24a-fbff04fc2a85', '渡中江望石城泣下', '渡中江望石城泣下', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["江南江北舊家鄉，三十年來夢一場。","吳苑宮闈今冷落，廣陵臺殿已荒涼。","雲籠遠岫愁千片，雨打歸舟淚萬行。","兄弟四人三百口，不堪閑坐細思量。"]', '["江南江北旧家乡，三十年来梦一場。","吳苑宮闈今冷落，廣陵台殿已荒涼。","云籠远岫愁千片，雨打归舟泪万行。","兄弟四人三百口，不堪闲坐細思量。"]', '诗', 'shi', '', NULL, '渡中江望石城泣下 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('018cab44-8167-40eb-8934-09667eb405da', '輓辭 一', '輓辞 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["珠碎眼前珍，花凋世外春。","未銷心裏恨，又失掌中身。","玉笥猶殘藥，香匳已染塵。","前哀將後感，無淚可霑巾。"]', '["珠碎眼前珍，花凋世外春。","未銷心裏恨，又失掌中身。","玉笥猶殘藥，香匳已染塵。","前哀將後感，無泪可霑巾。"]', '诗', 'shi', '', NULL, '輓辭 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aaa5f58-ec89-4cdc-b96a-2717e03edf95', '輓辭 二', '輓辞 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["豔質同芳樹，浮危道略同。","正悲春落實，又苦雨傷叢。","穠麗今何在？飄零事已空。","沈沈無問處，千載謝東風。"]', '["豔質同芳樹，浮危道略同。","正悲春落實，又苦雨傷叢。","穠丽今何在？飄零事已空。","沈沈無问处，千載謝东风。"]', '诗', 'shi', '', NULL, '輓辭 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('932de3da-b56d-4987-b9cc-3b2d5956a4ff', '悼詩', '悼诗', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["永念難消釋，孤懷痛自嗟。","雨深秋寂莫，愁引病增加。","咽絕風前思，昏濛眼上花。","空王應念我，窮子正迷家。"]', '["永念难消釋，孤懷痛自嗟。","雨深秋寂莫，愁引病增加。","咽絕风前思，昏濛眼上花。","空王應念我，窮子正迷家。"]', '诗', 'shi', '', NULL, '悼詩 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4efebbe9-a40d-4428-b82a-752c48f67793', '感懷 一', '感懷 一', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["又見桐花發舊枝，一樓煙雨暮淒淒。","凭闌惆悵人誰會，不覺澘然淚眼低。"]', '["又见桐花發旧枝，一楼煙雨暮淒淒。","凭闌惆悵人誰會，不覺澘然泪眼低。"]', '诗', 'shi', '', NULL, '感懷 一 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad067534-b1c5-4baa-8454-3dc50c11e1c3', '感懷 二', '感懷 二', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["層城無復見嬌姿，佳節纏哀不自持。","空有當年舊煙月，芙蓉城上哭蛾眉。"]', '["層城無复见嬌姿，佳節纏哀不自持。","空有當年旧煙月，芙蓉城上哭蛾眉。"]', '诗', 'shi', '', NULL, '感懷 二 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8881d860-4e39-4a12-97f0-a222687988d5', '梅花', '梅花', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["殷勤移植地，曲檻小闌邊。","共約重芳日，還憂不盛妍。","阻風開步障，乘月溉寒泉。","誰料花前後，蛾眉卻不全。"]', '["殷勤移植地，曲檻小闌邊。","共約重芳日，還憂不盛妍。","阻风开步障，乘月溉寒泉。","誰料花前後，蛾眉卻不全。"]', '诗', 'shi', '', NULL, '梅花 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82f109d2-3bc1-447a-a73e-018133ac8929', '梅花', '梅花', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["失却煙花主，東君自不知。","清香更何用，猶發去年枝。"]', '["失却煙花主，东君自不知。","清香更何用，猶發去年枝。"]', '诗', 'shi', '', NULL, '梅花 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1bfef77-89cd-4e38-90b7-bc41784d58de', '書靈筵手巾', '书靈筵手巾', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["浮生共顦顇，壯歲失嬋娟。","汗手遺香漬，痕眉染黛煙。"]', '["浮生共顦顇，壯歲失嬋娟。","汗手遺香漬，痕眉染黛煙。"]', '诗', 'shi', '', NULL, '書靈筵手巾 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbf02817-86a8-42de-b8bf-9d13c764fdb3', '書琵琶背', '书琵琶背', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["侁自肩如削，難勝數縷絛。","天香留鳳尾，餘煖在檀槽。"]', '["侁自肩如削，难勝數縷絛。","天香留鳳尾，餘煖在檀槽。"]', '诗', 'shi', '', NULL, '書琵琶背 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a7dd159-6c84-4436-a9a0-99e2e86d426f', '病中感懷', '病中感懷', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["顦顇年來甚，蕭條益自傷。","風威侵病骨，雨氣咽愁腸。","夜鼎唯煎藥，朝髭半染霜。","前緣竟何似，誰與問空王。"]', '["顦顇年来甚，蕭條益自傷。","风威侵病骨，雨氣咽愁腸。","夜鼎唯煎藥，朝髭半染霜。","前緣竟何似，誰與问空王。"]', '诗', 'shi', '', NULL, '病中感懷 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8244187-a87e-4e80-a3fe-8092bcf48107', '病中書事', '病中书事', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["病身堅固道情深，宴坐清香思自任。","月照靜居唯擣藥，門扃幽院只來禽。","庸醫嬾聽詞何取，小婢將行力未禁。","賴問空門知氣味，不然煩惱萬塗侵。"]', '["病身堅固道情深，宴坐清香思自任。","月照静居唯擣藥，门扃幽院只来禽。","庸醫嬾听词何取，小婢將行力未禁。","賴问空门知氣味，不然煩惱万塗侵。"]', '诗', 'shi', '', NULL, '病中書事 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2240c7b5-5ea2-43de-baa8-24fc03aa97cd', '賜宮人慶奴', '賜宮人慶奴', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["風情漸老見春羞，到處消魂感舊遊。","多謝長條似相識，強垂煙態拂人頭。"]', '["风情漸老见春羞，到处消魂感旧游。","多謝长條似相識，強垂煙態拂人头。"]', '诗', 'shi', '', NULL, '賜宮人慶奴 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba0ab762-8e4e-4965-a7dd-d47b6958adfb', '題金樓子後', '題金楼子後', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["牙籤萬軸裹紅綃，王粲書同付火燒。","不於祖龍留面目，遺篇那得到今朝。"]', '["牙籤万軸裹紅綃，王粲书同付火燒。","不於祖龙留面目，遺篇那得到今朝。"]', '诗', 'shi', '', NULL, '題金樓子後 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef4b782-4495-49dc-9da5-b022da15c2a6', '句', '句', 'de1de699-3955-416a-b123-75f650048e6f', '唐', '["迢迢牽牛星，杳在河之陽。","粲粲黃姑女，耿耿遙相望。","鸎狂應有恨，蝶舞已無多。","揖讓月在手，動搖風滿懷。","病態如衰弱，厭厭向五年。","衰顏一病難牽復，曉殿君臨頗自羞。","冷笑秦皇經遠略，靜憐姬滿苦時巡。","鬢從今日添新白，菊是去年依舊黃。","萬古到頭歸一死，醉鄉葬地有高原。","人生不滿百，剛作千年畫。","日暎仙雲薄，秋高天碧深。","烏照始潛輝，龍燭便爭秉。","凝珠滿露枝，遊颺日已西。","肅穆寒初至，九重開扇鵠。","四牖炳燈魚，羽觴無算酌。","傾盌更爲壽，深卮遞酬賓。"]', '["迢迢牽牛星，杳在河之陽。","粲粲黄姑女，耿耿遙相望。","鸎狂應有恨，蝶舞已無多。","揖讓月在手，动搖风满懷。","病態如衰弱，厭厭向五年。","衰顏一病难牽复，晓殿君臨頗自羞。","冷笑秦皇經远略，静怜姬满苦时巡。","鬢從今日添新白，菊是去年依旧黄。","万古到头归一死，醉乡葬地有高原。","人生不满百，剛作千年畫。","日暎仙云薄，秋高天碧深。","烏照始潛輝，龙燭便爭秉。","凝珠满露枝，游颺日已西。","肅穆寒初至，九重开扇鵠。","四牖炳灯鱼，羽觴無算酌。","傾盌更爲壽，深卮遞酬賓。"]', '诗', 'shi', '', NULL, '句 後主煜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2468fbd-1835-4a66-a3a6-6f27f6d6417d', '薔薇詩一首十八韻呈東海侍郎徐鉉', '薔薇诗一首十八韻呈东海侍郎徐鉉', 'bd2c80be-c21b-4625-b1b9-0c160dc83723', '唐', '["綠影覆幽池，芳菲四月時。","管弦朝夕興，組繡百千枝。","盛引牆看徧，高煩架屢移。","露輕濡綵筆，蜂誤拂吟髭。","日照玲瓏幔，風搖翡翠帷。","早紅飄蘚地，狂蔓挂蛛絲。","嫩刺牽衣細，新條窣草垂。","晚香難暫捨，嬌態自相窺。","深淺分前後，榮華互盛衰。","尊前留客久，月下欲歸遲。","何處繁臨砌？誰家密映籬。","絳羅房燦爛，碧玉葉參差。","分得殷勤種，開來遠近知。","晶熒歌袖袂，柔弱舞腰支。","膏麝誰將比，庭萱自合嗤。","勻妝低水鑑，泣淚滴煙𩅰。","畫擬憑梁廣，名宜亞楚姬。","寄君十八韻，思拙媿新奇。"]', '["綠影覆幽池，芳菲四月时。","管弦朝夕兴，組繡百千枝。","盛引牆看徧，高煩架屢移。","露轻濡綵笔，蜂誤拂吟髭。","日照玲瓏幔，风搖翡翠帷。","早紅飄蘚地，狂蔓挂蛛絲。","嫩刺牽衣細，新條窣草垂。","晚香难暫捨，嬌態自相窺。","深淺分前後，榮华互盛衰。","尊前留客久，月下欲归遲。","何处繁臨砌？誰家密映籬。","絳羅房燦爛，碧玉葉參差。","分得殷勤種，开来远近知。","晶熒歌袖袂，柔弱舞腰支。","膏麝誰將比，庭萱自合嗤。","勻妝低水鑑，泣泪滴煙𩅰。","畫擬憑梁廣，名宜亞楚姬。","寄君十八韻，思拙媿新奇。"]', '诗', 'shi', '', NULL, '薔薇詩一首十八韻呈東海侍郎徐鉉 韓王從善 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19466825-f62c-4d59-a528-b04de00054fd', '觀棊', '观棊', '90030281-cdd7-4500-9400-637401109449', '唐', '["竹林二君子，盡日竟沈吟。","相對終無語，爭先各有心。","恃強斯有失，守分固無侵。","若算機籌處，滄滄海未深。"]', '["竹林二君子，尽日竟沈吟。","相对終無語，爭先各有心。","恃強斯有失，守分固無侵。","若算機籌处，滄滄海未深。"]', '诗', 'shi', '', NULL, '觀棊 吉王從謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63107f94-980b-4fb4-93c1-1815654b77bd', '贈別唐太師道襲', '贈別唐太師道襲', '88c59fad-2cc7-43bf-82b1-3c7ee8fb8ddf', '唐', '["丱歲便將爲肘腋，二紀何曾離一日。","更深猶尚立案前，敷奏柔和不傷物。","今朝榮貴慰我心，雙旌引向重城出。","褒斜舊地委勳賢，從此生靈永泰息。"]', '["丱歲便將爲肘腋，二紀何曾離一日。","更深猶尚立案前，敷奏柔和不傷物。","今朝榮貴慰我心，雙旌引向重城出。","褒斜旧地委勳賢，從此生靈永泰息。"]', '诗', 'shi', '', NULL, '贈別唐太師道襲 蜀高祖王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e66421b4-5322-4aa9-a64c-1bf8707decb7', '幸秦川上梓潼山', '幸秦川上梓潼山', 'c75bcb36-93b8-49e3-b8bd-e824b3c1d400', '唐', '["喬巖簇冷煙，幽徑上寒天。","下瞰峨眉嶺，上窺華岳巔。","驅馳非取樂，按幸爲憂邊。","此去如登陟，歌樓路幾千。"]', '["喬巖簇冷煙，幽徑上寒天。","下瞰峨眉嶺，上窺华岳巔。","驱驰非取乐，按幸爲憂邊。","此去如登陟，歌楼路幾千。"]', '诗', 'shi', '', NULL, '幸秦川上梓潼山 後主衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f26a4e37-57a6-4c7c-9d22-060e411a4424', '題劒門', '題劒门', 'c75bcb36-93b8-49e3-b8bd-e824b3c1d400', '唐', '["緩轡踰雙劒，行行躡石稜。","作千尋壁壘，爲萬祀依憑。","道德雖無取，江山粗可矜。","回看城闕路，雲疊樹層層。"]', '["緩轡踰雙劒，行行躡石稜。","作千尋壁壘，爲万祀依憑。","道德雖無取，江山粗可矜。","回看城闕路，云叠樹層層。"]', '诗', 'shi', '', NULL, '題劒門 後主衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61da3ad3-9e7f-4a1c-862d-7fdda6413288', '過白衛嶺和韓昭', '過白衛嶺和韓昭', 'c75bcb36-93b8-49e3-b8bd-e824b3c1d400', '唐', '["先朝神武力開邊，畫斷封疆四五千。","前望隴山屯劒戟，後憑巫峽鎖烽煙。","軒皇尚自親平寇，嬴政徒勞愛學仙。","想到隗宮尋勝處，正應鶯語暮春天。"]', '["先朝神武力开邊，畫斷封疆四五千。","前望隴山屯劒戟，後憑巫峽鎖烽煙。","軒皇尚自親平寇，嬴政徒勞愛学仙。","想到隗宮尋勝处，正應鶯語暮春天。"]', '诗', 'shi', '', NULL, '過白衛嶺和韓昭 後主衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecc1774b-988c-40ea-95f3-312889a6e2a3', '宮詞', '宮词', 'c75bcb36-93b8-49e3-b8bd-e824b3c1d400', '唐', '["輝輝赫赫浮玉雲，宣華池上月華新。","月華如水浸宮殿，有酒不醉真癡人。"]', '["輝輝赫赫浮玉云，宣华池上月华新。","月华如水浸宮殿，有酒不醉真癡人。"]', '诗', 'shi', '', NULL, '宮詞 後主衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f27f6d5d-9d1b-4e86-b88e-efd452c1d424', '醉妝詞', '醉妝词', 'c75bcb36-93b8-49e3-b8bd-e824b3c1d400', '唐', '["者邊走，那邊走，只是尋花柳。","那邊走，者邊走，莫厭金杯酒。"]', '["者邊走，那邊走，只是尋花柳。","那邊走，者邊走，莫厭金杯酒。"]', '诗', 'shi', '', NULL, '醉妝詞 後主衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10dd38a5-9bf1-4b83-b898-4692f718f0d7', '句', '句', 'c75bcb36-93b8-49e3-b8bd-e824b3c1d400', '唐', '["不緣朝闕去，好此結茅廬。"]', '["不緣朝闕去，好此結茅廬。"]', '诗', 'shi', '', NULL, '句 後主衍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8799ff64-1456-4567-929d-8cbcadd3919b', '巡衣錦軍製還鄉歌', '巡衣錦軍製還乡歌', '354d7887-e77f-4e2f-90a9-96ea7d0ab00b', '唐', '["三節還鄉兮挂錦衣，碧天朗朗兮愛日暉。","功成道上兮列旌旗，父老遠來兮相追隨。","家山鄉眷兮會時稀，今朝設宴兮觥散飛。","斗牛無孛兮民無欺，吳越一王兮駟馬歸。"]', '["三節還乡兮挂錦衣，碧天朗朗兮愛日暉。","功成道上兮列旌旗，父老远来兮相追隨。","家山乡眷兮會时稀，今朝設宴兮觥散飞。","斗牛無孛兮民無欺，吳越一王兮駟马归。"]', '诗', 'shi', '', NULL, '巡衣錦軍製還鄉歌 吳越王錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba8a1004-e3bc-4167-93e6-1adc22d3eedb', '沒了期歌 一', '沒了期歌 一', '354d7887-e77f-4e2f-90a9-96ea7d0ab00b', '唐', '["沒了期，沒了期，營基纔了又倉基。"]', '["沒了期，沒了期，營基纔了又倉基。"]', '诗', 'shi', '', NULL, '沒了期歌 一 吳越王錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a5dd0d4-f619-4303-b2ed-7e40061c58aa', '沒了期歌 二', '沒了期歌 二', '354d7887-e77f-4e2f-90a9-96ea7d0ab00b', '唐', '["沒了期，沒了期，春衣纔了又冬衣。"]', '["沒了期，沒了期，春衣纔了又冬衣。"]', '诗', 'shi', '', NULL, '沒了期歌 二 吳越王錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7081981c-0e2b-4d64-b610-1cf2d95d5fbe', '句', '句', '354d7887-e77f-4e2f-90a9-96ea7d0ab00b', '唐', '["須將一片地，付與有心人。","黃河信有澄清日，後代應難繼此才。","傳語龍王幷水府，錢塘借與築錢城。"]', '["須將一片地，付與有心人。","黄河信有澄清日，後代應难繼此才。","傳語龙王幷水府，錢塘借與築錢城。"]', '诗', 'shi', '', NULL, '句 吳越王錢鏐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c31e7431-36e9-461c-978c-66d83c065598', '宮中作', '宮中作', '9db47220-9eff-44a7-b55e-c8c4ea44b26c', '唐', '["廊廡周遭翠幕遮，禁林深處絕喧譁。","界開日影憐窗紙，穿破苔痕惡筍芽。","西第晚宜供露茗，小池寒欲結冰花。","謝公未是深沈量，猶把輸贏局上誇。"]', '["廊廡周遭翠幕遮，禁林深处絕喧譁。","界开日影怜窗紙，穿破苔痕惡筍芽。","西第晚宜供露茗，小池寒欲結冰花。","謝公未是深沈量，猶把輸贏局上誇。"]', '诗', 'shi', '', NULL, '宮中作 後王錢俶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a9b2767-706e-40b9-a423-2097e5f97d10', '避暑摩訶池上作', '避暑摩訶池上作', 'afcdc918-7a52-45f7-8911-92d74b8ede90', '唐', '["冰肌玉骨清無汗，水殿風來暗香暖。","簾開明月獨窺人，敧枕釵橫雲鬢亂。","起來瓊戶寂無聲，時見疎星渡河漢。","屈指西風幾時來，只恐流年暗中換。"]', '["冰肌玉骨清無汗，水殿风来暗香暖。","簾开明月独窺人，敧枕釵橫云鬢亂。","起来瓊戶寂無声，时见疎星渡河漢。","屈指西风幾时来，只恐流年暗中換。"]', '诗', 'shi', '', NULL, '避暑摩訶池上作 後蜀嗣主孟昶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e10bd711-4a4e-40e6-85a7-bcec617b61c0', '批葉翹諫書紙尾', '批葉翹諫书紙尾', 'd81d9341-6d9c-4ee7-9f4c-06297a9c8f18', '唐', '["春色曾看紫陌頭，亂紅飛盡不禁愁。","人情自厭芳華歇，一葉隨風落御溝。"]', '["春色曾看紫陌头，亂紅飞尽不禁愁。","人情自厭芳华歇，一葉隨风落御溝。"]', '诗', 'shi', '', NULL, '批葉翹諫書紙尾 閩王王繼鵬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b343ce20-fa91-4e0a-b3e5-c6e1acf3244e', '丈人觀', '丈人观', '1aa19702-43e6-489d-ba7d-ddd028064b40', '唐', '["早與元妃慕至化，同躋靈嶽訪真仙。","當時信有壺中景，今日親來洞裏天。","儀仗影空寥廓外，金絲聲揭翠微巔。","惟慙未致華胥理，徒卜升平萬萬年。"]', '["早與元妃慕至化，同躋靈嶽訪真仙。","當时信有壺中景，今日親来洞裏天。","儀仗影空寥廓外，金絲声揭翠微巔。","惟慙未致华胥理，徒卜升平万万年。"]', '诗', 'shi', '', NULL, '丈人觀 蜀太后徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b07e39b5-eafc-4493-a320-454e7a81149a', '玄都觀', '玄都观', '1aa19702-43e6-489d-ba7d-ddd028064b40', '唐', '["千尋綠嶂夾流溪，登眺因知海岳低。","瀑布迸舂青石碎，輪茵橫翦翠峰齊。","步黏苔蘚龍橋滑，日閉煙羅鳥徑迷。","莫道穹天無路到，此山便是碧雲梯。"]', '["千尋綠嶂夾流溪，登眺因知海岳低。","瀑布迸舂青石碎，輪茵橫翦翠峰齊。","步黏苔蘚龙橋滑，日閉煙羅鸟徑迷。","莫道穹天無路到，此山便是碧云梯。"]', '诗', 'shi', '', NULL, '玄都觀 蜀太后徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('288d5f1a-32d3-4be4-9aab-d266c1347c83', '丈人觀謁先帝御容', '丈人观謁先帝御容', '1aa19702-43e6-489d-ba7d-ddd028064b40', '唐', '["聖帝歸梧野，躬來謁聖顏。","旋登三徑路，似陟九嶷山。","日照堆嵐迥，雲橫積翠間。","期修封禪禮，方俟再躋攀。"]', '["聖帝归梧野，躬来謁聖顏。","旋登三徑路，似陟九嶷山。","日照堆嵐迥，云橫積翠间。","期修封禪禮，方俟再躋攀。"]', '诗', 'shi', '', NULL, '丈人觀謁先帝御容 蜀太后徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15bac88f-aae3-4249-861e-7d42a2120302', '題金華宮', '題金华宮', '1aa19702-43e6-489d-ba7d-ddd028064b40', '唐', '["再到金華頂，玄都訪道回。","雲披分景象，黛鎖顯樓臺。","雨滌前山淨，風吹去路開。","翠屏夾流水，何必羨蓬萊。"]', '["再到金华頂，玄都訪道回。","云披分景象，黛鎖显楼台。","雨滌前山淨，风吹去路开。","翠屏夾流水，何必羨蓬萊。"]', '诗', 'shi', '', NULL, '題金華宮 蜀太后徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('305a9001-cb99-4f20-a047-f44fa83e11c7', '丹景山至德寺', '丹景山至德寺', '1aa19702-43e6-489d-ba7d-ddd028064b40', '唐', '["周回雲水遊丹景，因與真妃眺上方。","晴日曉升金晃曜，寒泉夜落玉丁當。","松梢月轉琴栖影，柏徑風牽麝食香。","虔煠六銖宜鑄祝，惟祈聖祉保遐昌。"]', '["周回云水游丹景，因與真妃眺上方。","晴日晓升金晃曜，寒泉夜落玉丁當。","松梢月轉琴栖影，柏徑风牽麝食香。","虔煠六銖宜鑄祝，惟祈聖祉保遐昌。"]', '诗', 'shi', '', NULL, '丹景山至德寺 蜀太后徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a5cfac3-3860-49c0-8a54-089397403f6f', '題彭州陽平化', '題彭州陽平化', '1aa19702-43e6-489d-ba7d-ddd028064b40', '唐', '["尋真游勝境，巡禮到陽平。","水遠波瀾碧，山高氣象清。","殿嚴孫氏貌，碑暗係師名。","夜月登壇醮，松風森磬聲。"]', '["尋真游勝境，巡禮到陽平。","水远波瀾碧，山高氣象清。","殿嚴孫氏貌，碑暗係師名。","夜月登壇醮，松风森磬声。"]', '诗', 'shi', '', NULL, '題彭州陽平化 蜀太后徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fb2f812-c33e-41ec-91af-57bfb15e09e3', '三學山夜看聖燈', '三学山夜看聖灯', '1aa19702-43e6-489d-ba7d-ddd028064b40', '唐', '["虔禱游靈境，元妃夙志同。","玉香焚靜夜，銀燭炫遼空。","泉漱雲根月，鐘敲檜杪風。","印金標聖迹，飛石顯神功。","滿望天涯極，平臨日脚紅。","猿來齋石上，僧集講筵中。","頓作超三界，渾疑證六通。","願成修偃化，社稷保延洪。"]', '["虔禱游靈境，元妃夙志同。","玉香焚静夜，銀燭炫遼空。","泉漱云根月，鐘敲檜杪风。","印金標聖迹，飞石显神功。","满望天涯極，平臨日脚紅。","猿来斋石上，僧集講筵中。","頓作超三界，渾疑證六通。","願成修偃化，社稷保延洪。"]', '诗', 'shi', '', NULL, '三學山夜看聖燈 蜀太后徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6dff750-e7ff-414e-b31f-c463f81772ad', '題天迴驛', '題天迴驛', '1aa19702-43e6-489d-ba7d-ddd028064b40', '唐', '["周遊靈境散幽情，千里江山暫得行。","所恨風光看未足，卻驅金翠入龜城。"]', '["周游靈境散幽情，千里江山暫得行。","所恨风光看未足，卻驱金翠入龟城。"]', '诗', 'shi', '', NULL, '題天迴驛 蜀太后徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b4f56ae-a285-4052-add2-f0e99a4bd393', '丈人觀', '丈人观', '84e774ec-0789-4bd9-b828-c7c229a1a91b', '唐', '["獲陪翠輦喜殊常，同涉仙壇豈厭長。","不羨乘鸞入煙霧，此中便是五雲鄉。"]', '["獲陪翠輦喜殊常，同涉仙壇豈厭长。","不羨乘鸾入煙霧，此中便是五云乡。"]', '诗', 'shi', '', NULL, '丈人觀 蜀太妃徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('565cad9c-b5b6-425f-86bc-0f33fec6fbd2', '玄都觀', '玄都观', '84e774ec-0789-4bd9-b828-c7c229a1a91b', '唐', '["登尋丹壑到玄都，接日紅霞照座隅。","即向周回巖下看，似看曾進畫圖無。"]', '["登尋丹壑到玄都，接日紅霞照座隅。","即向周回巖下看，似看曾進畫圖無。"]', '诗', 'shi', '', NULL, '玄都觀 蜀太妃徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cdd3b0e-f6ff-4458-b49d-b81502e4d3cb', '游丈人觀謁先帝御容', '游丈人观謁先帝御容', '84e774ec-0789-4bd9-b828-c7c229a1a91b', '唐', '["共謁御容儀，還同在禁闈。","笙歌喧寶殿，彩仗耀金徽。","清淚霑羅袂，紅霞拂繡衣。","九疑山水遠，無路繼湘妃。"]', '["共謁御容儀，還同在禁闈。","笙歌喧寶殿，彩仗耀金徽。","清泪霑羅袂，紅霞拂繡衣。","九疑山水远，無路繼湘妃。"]', '诗', 'shi', '', NULL, '游丈人觀謁先帝御容 蜀太妃徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c225364-4e21-428e-ac41-013a9eb0d8bb', '題金華宮', '題金华宮', '84e774ec-0789-4bd9-b828-c7c229a1a91b', '唐', '["碧煙紅霧漾人衣，宿霧蒼苔石徑危。","風巧解吹松上曲，蝶嬌頻采臉邊脂。","同尋僻境思攜手，暗指遙山學畫眉。","好把身心清淨處，角冠霞帔事希夷。"]', '["碧煙紅霧漾人衣，宿霧蒼苔石徑危。","风巧解吹松上曲，蝶嬌頻采臉邊脂。","同尋僻境思携手，暗指遙山学畫眉。","好把身心清淨处，角冠霞帔事希夷。"]', '诗', 'shi', '', NULL, '題金華宮 蜀太妃徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7434702-2fb1-40ed-8ade-b3f21154f4d2', '和題丹景山至德寺', '和題丹景山至德寺', '84e774ec-0789-4bd9-b828-c7c229a1a91b', '唐', '["丹景山頭宿梵宮，玉輪金輅駐虛空。","軍持無水注寒碧，蘭若有花開晚紅。","武士盡排青嶂下，內人皆在講筵中。","我家帝子傳王業，積善終期四海同。"]', '["丹景山头宿梵宮，玉輪金輅駐虛空。","軍持無水注寒碧，蘭若有花开晚紅。","武士尽排青嶂下，內人皆在講筵中。","我家帝子傳王業，積善終期四海同。"]', '诗', 'shi', '', NULL, '和題丹景山至德寺 蜀太妃徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50636f43-c98e-4bfe-b3d4-e671b1d8b6c4', '題彭州陽平化', '題彭州陽平化', '84e774ec-0789-4bd9-b828-c7c229a1a91b', '唐', '["雲浮翠輦屆陽平，真似驂鸞到上清。","風起半厓聞虎嘯，雨來當面見龍行。","晚尋水澗聽松韻，夜上星壇看月明。","長恐前身居此境，玉皇教向錦城生。"]', '["云浮翠輦屆陽平，真似驂鸾到上清。","风起半厓闻虎嘯，雨来當面见龙行。","晚尋水澗听松韻，夜上星壇看月明。","长恐前身居此境，玉皇教向錦城生。"]', '诗', 'shi', '', NULL, '題彭州陽平化 蜀太妃徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca2145e0-816c-435b-8e7b-5bb087f6568c', '三學山夜看聖燈', '三学山夜看聖灯', '84e774ec-0789-4bd9-b828-c7c229a1a91b', '唐', '["聖燈千萬炬，旋向碧空生。","細雨溼不暗，好風吹更明。","磬敲金地響，僧唱梵天聲。","若說無心法，此光如有情。"]', '["聖灯千万炬，旋向碧空生。","細雨溼不暗，好风吹更明。","磬敲金地响，僧唱梵天声。","若说無心法，此光如有情。"]', '诗', 'shi', '', NULL, '三學山夜看聖燈 蜀太妃徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a2e95e9-217d-43dc-8056-7e0e9a44358a', '題天迴驛', '題天迴驛', '84e774ec-0789-4bd9-b828-c7c229a1a91b', '唐', '["翠驛紅亭近玉京，夢魂猶是在青城。","比來出看江山景，却被江山看出行。"]', '["翠驛紅亭近玉京，梦魂猶是在青城。","比来出看江山景，却被江山看出行。"]', '诗', 'shi', '', NULL, '題天迴驛 蜀太妃徐氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ac369e-db24-4cc6-9eb7-aedca7e8bdb9', '郊廟歌辭 祀圜丘樂章 豫和', '郊廟歌辞 祀圜丘乐章 豫和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["上靈睠命膺會昌，盛德殷薦叶辰良。","景福降兮聖德遠，玄化穆兮天曆長。"]', '["上靈睠命膺會昌，盛德殷薦叶辰良。","景福降兮聖德远，玄化穆兮天曆长。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀圜丘樂章 豫和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d15f1209-3fb8-4c84-b1cf-a6607092c74d', '郊廟歌辭 祀圜丘樂章 太和', '郊廟歌辞 祀圜丘乐章 太和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["穆穆我后，道應千齡。","登三處大，得一居貞。","禮惟崇德，樂以和聲。","百神仰止，天下文明。"]', '["穆穆我后，道應千齡。","登三处大，得一居貞。","禮惟崇德，乐以和声。","百神仰止，天下文明。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀圜丘樂章 太和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cba1afc6-35ad-43bd-a997-2eb2fb1d2105', '郊廟歌辭 祀圜丘樂章 肅和', '郊廟歌辞 祀圜丘乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["闓陽播氣，甄曜垂明。","有赫圜宰，深仁曲成。","日麗蒼璧，煙開紫營。","聿遵乾享，式降鴻禎。"]', '["闓陽播氣，甄曜垂明。","有赫圜宰，深仁曲成。","日丽蒼璧，煙开紫營。","聿遵乾享，式降鴻禎。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀圜丘樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92a8846f-c399-4145-a36b-4b8c0b7d9c14', '郊廟歌辭 祀圜丘樂章 雍和', '郊廟歌辞 祀圜丘乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["欽惟大帝，[載]仰皇穹。","始命田燭，爰啓郊宮。","雲門駭聽，雷鼓鳴空。","神其介祀，景祚斯融。"]', '["欽惟大帝，[載]仰皇穹。","始命田燭，爰啓郊宮。","云门駭听，雷鼓鳴空。","神其介祀，景祚斯融。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀圜丘樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c257fca7-3eb1-476c-b7bd-bb706269c904', '郊廟歌辭 祀圜丘樂章 壽和', '郊廟歌辞 祀圜丘乐章 壽和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["八音斯奏，三獻畢陳。","寶祚惟永，暉光日新。"]', '["八音斯奏，三獻畢陳。","寶祚惟永，暉光日新。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀圜丘樂章 壽和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6760691a-685c-4e01-9f8b-3e7384ed92fd', '郊廟歌辭 祀圜丘樂章 舒和', '郊廟歌辞 祀圜丘乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["疊璧凝影皇壇路，編珠流彩帝郊前。","已奏黃鍾歌大呂，還符寶曆祚昌年。"]', '["叠璧凝影皇壇路，編珠流彩帝郊前。","已奏黄鍾歌大呂，還符寶曆祚昌年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀圜丘樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fa4dd76-9d99-44fe-9b28-f16153115227', '郊廟歌辭 祀圜丘樂章 凱安', '郊廟歌辞 祀圜丘乐章 凱安', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["昔在炎運終，中華亂無象。","酆郊赤烏見，邙山黑雲上。","大賚下周車，禁暴開殷網。","幽明同叶贊，鼎祚齊天壤。"]', '["昔在炎運終，中华亂無象。","酆郊赤烏见，邙山黑云上。","大賚下周车，禁暴开殷網。","幽明同叶贊，鼎祚齊天壤。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀圜丘樂章 凱安 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1e8a4d5-2124-4eab-a15e-bec5d6f3e880', '郊廟歌辭 祀圜丘樂章 豫和', '郊廟歌辞 祀圜丘乐章 豫和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["歌奏畢兮禮獻終，六龍馭兮神將昇。","明德感兮非黍稷，降福簡兮祚休徵。"]', '["歌奏畢兮禮獻終，六龙馭兮神將昇。","明德感兮非黍稷，降福簡兮祚休徵。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀圜丘樂章 豫和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9acb90cb-451d-4c8c-8630-06dd81c45838', '郊廟歌辭 郊天舊樂章 豫和', '郊廟歌辞 郊天旧乐章 豫和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["蘋蘩禮著，黍稷誠微。","音盈鳳管，彩駐龍旂。","洪歆式就，介福攸歸。","送樂有闋，靈馭遄飛。"]', '["蘋蘩禮著，黍稷誠微。","音盈鳳管，彩駐龙旂。","洪歆式就，介福攸归。","送乐有闋，靈馭遄飞。"]', '诗', 'shi', '', NULL, '郊廟歌辭 郊天舊樂章 豫和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d9622c6-0120-4f70-ac8f-17996b69dd93', '郊廟歌辭 武后大享昊天樂章 一', '郊廟歌辞 武后大享昊天乐章 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["大陰凝至化，真耀蘊軒儀。","德邁娥臺敞，仁高姒幄披。","捫天遂啓極，夢日乃昇曦。"]', '["大陰凝至化，真耀蘊軒儀。","德邁娥台敞，仁高姒幄披。","捫天遂啓極，梦日乃昇曦。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9ef5ff3-9cfd-422b-9b0a-9b569826776f', '郊廟歌辭 武后大享昊天樂章 二', '郊廟歌辞 武后大享昊天乐章 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["瞻紫極，望玄穹。","翹至懇，罄深衷。","聽雖遠，誠必通。","垂厚澤，降雲宮。"]', '["瞻紫極，望玄穹。","翹至懇，罄深衷。","听雖远，誠必通。","垂厚澤，降云宮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86f014f5-1e88-4a78-9efe-8e6b9f923c7a', '郊廟歌辭 武后大享昊天樂章 三', '郊廟歌辞 武后大享昊天乐章 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["乾儀混成沖邃，天道下濟高明。","闓陽晨披紫闕，太一曉降黃庭。","圓壇敢[申]昭報，方璧冀展虔情。","丹禁式敷衷懇，玄鑒庶察微誠。"]', '["乾儀混成沖邃，天道下濟高明。","闓陽晨披紫闕，太一晓降黄庭。","圓壇敢[申]昭報，方璧冀展虔情。","丹禁式敷衷懇，玄鑒庶察微誠。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba7d411-0319-42c5-af8c-caa5c9373cf1', '郊廟歌辭 武后大享昊天樂章 四', '郊廟歌辞 武后大享昊天乐章 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["巍巍睿業廣，赫赫聖基隆。","菲德承先顧，禎符萃眇躬。","銘開武巖側，圖薦洛川中。","微誠詎幽感，景命忽昭融。","有懷慙紫極，無以謝玄穹。"]', '["巍巍睿業廣，赫赫聖基隆。","菲德承先顧，禎符萃眇躬。","銘开武巖側，圖薦洛川中。","微誠詎幽感，景命忽昭融。","有懷慙紫極，無以謝玄穹。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4a0253f-6331-4902-87e3-a4307347319d', '郊廟歌辭 武后大享昊天樂章 五', '郊廟歌辞 武后大享昊天乐章 五', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["朝壇霧卷，曙嶺煙沈。","爰設筐幣，式表誠心。","筵輝麗璧，樂暢和音。","仰惟靈鑒，俯察翹襟。"]', '["朝壇霧卷，曙嶺煙沈。","爰設筐幣，式表誠心。","筵輝丽璧，乐暢和音。","仰惟靈鑒，俯察翹襟。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 五 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab8a64ab-eefa-489f-9e1b-c7a0139d77d3', '郊廟歌辭 武后大享昊天樂章 六', '郊廟歌辞 武后大享昊天乐章 六', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昭昭上帝，穆穆下臨。","禮崇備物，樂奏鏘金。","蘭羞委薦，桂醑盈斟。","敢希[明]德，聿罄莊心。"]', '["昭昭上帝，穆穆下臨。","禮崇備物，乐奏鏘金。","蘭羞委薦，桂醑盈斟。","敢希[明]德，聿罄莊心。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 六 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48d76427-8d1c-425a-9425-e4d4a8751f74', '郊廟歌辭 武后大享昊天樂章 七', '郊廟歌辞 武后大享昊天乐章 七', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["樽浮九醞，禮備三周。","陳誠菲奠，契福神猷。"]', '["樽浮九醞，禮備三周。","陳誠菲奠，契福神猷。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 七 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed819c5a-6f20-4664-848c-026b360befff', '郊廟歌辭 武后大享昊天樂章 八', '郊廟歌辞 武后大享昊天乐章 八', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["奠璧郊壇昭大禮，鏘金拊石表虔誠。","始奏承雲娛帝賞，復歌調露暢韶英。"]', '["奠璧郊壇昭大禮，鏘金拊石表虔誠。","始奏承云娛帝賞，复歌調露暢韶英。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 八 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('795d1301-ccde-472c-b455-15ffe10b3004', '郊廟歌辭 武后大享昊天樂章 九', '郊廟歌辞 武后大享昊天乐章 九', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["荷恩承顧託，執契恭臨撫。","廟畧靜邊荒，天兵耀神武。","有截資先化，無爲遵舊矩。","禎符降昊穹，大業光寰宇。"]', '["荷恩承顧託，執契恭臨撫。","廟畧静邊荒，天兵耀神武。","有截資先化，無爲遵旧矩。","禎符降昊穹，大業光寰宇。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 九 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b1c3a1b-97f1-4ce5-8bf5-75b37731ddbd', '郊廟歌辭 武后大享昊天樂章 十', '郊廟歌辞 武后大享昊天乐章 十', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["肅肅祀典，邕邕禮秩。","三獻已周，九成斯畢。","爰撤其俎，載遷其實。","或升或降，唯誠唯質。"]', '["肅肅祀典，邕邕禮秩。","三獻已周，九成斯畢。","爰撤其俎，載遷其實。","或升或降，唯誠唯質。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 十 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e91f0e6-2031-46cf-95a8-0c4a5326929d', '郊廟歌辭 武后大享昊天樂章 十一', '郊廟歌辞 武后大享昊天乐章 十一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["禮終肆類，樂闋九成。","仰惟明德，敢薦非馨。","顧慙菲奠，久駐雲軿。","瞻荷靈澤，悚戀兼盈。"]', '["禮終肆類，乐闋九成。","仰惟明德，敢薦非馨。","顧慙菲奠，久駐云軿。","瞻荷靈澤，悚戀兼盈。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 十一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97918258-9ba8-4799-b271-650864515192', '郊廟歌辭 武后大享昊天樂章 十二', '郊廟歌辞 武后大享昊天乐章 十二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["式乾路，闢天扉。","迴日馭，動雲衣。","登金闕，入紫微。","望仙駕，仰恩徽。"]', '["式乾路，闢天扉。","迴日馭，动云衣。","登金闕，入紫微。","望仙駕，仰恩徽。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后大享昊天樂章 十二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba51429a-7ee2-44d2-a01f-61013d90419b', '郊廟歌辭 中宗祀昊天樂章 豫和', '郊廟歌辞 中宗祀昊天乐章 豫和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天之曆數歸睿唐，顧惟菲德欽昊蒼。","撰吉日兮表殷薦，冀神鑒兮降闓陽。"]', '["天之曆數归睿唐，顧惟菲德欽昊蒼。","撰吉日兮表殷薦，冀神鑒兮降闓陽。"]', '诗', 'shi', '', NULL, '郊廟歌辭 中宗祀昊天樂章 豫和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d845d3ba-d5d3-4ef3-a84b-4770683908db', '郊廟歌辭 中宗祀昊天樂章 太和', '郊廟歌辞 中宗祀昊天乐章 太和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["恭臨寶位，肅奉瑤圖。","恆思解網，每軫泣辜。","德慙巢燧，化劣唐虞。","期我良弼，式贊嘉謨。"]', '["恭臨寶位，肅奉瑤圖。","恆思解網，每軫泣辜。","德慙巢燧，化劣唐虞。","期我良弼，式贊嘉謨。"]', '诗', 'shi', '', NULL, '郊廟歌辭 中宗祀昊天樂章 太和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c0642c4-2103-4d80-bff2-3549978fb9f4', '郊廟歌辭 中宗祀昊天樂章 告謝', '郊廟歌辞 中宗祀昊天乐章 告謝', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["得一流玄澤，通三御紫宸。","遠叶千齡運，遐銷九域塵。","絕瑞駢闐集，殊祥絡繹臻。","登年慶棲畝，稔歲賀盈囷。"]', '["得一流玄澤，通三御紫宸。","远叶千齡運，遐銷九域塵。","絕瑞駢闐集，殊祥絡繹臻。","登年慶棲畝，稔歲賀盈囷。"]', '诗', 'shi', '', NULL, '郊廟歌辭 中宗祀昊天樂章 告謝 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a8ae628-df5e-4f11-b2a8-be2124d2ed93', '郊廟歌辭 中宗祀昊天樂章 肅和', '郊廟歌辞 中宗祀昊天乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["悠哉廣覆，大矣曲成。","九玄著象，七曜貞明。","珪璧是奠，醞酎斯盈。","作樂崇德，爰暢咸英。"]', '["悠哉廣覆，大矣曲成。","九玄著象，七曜貞明。","珪璧是奠，醞酎斯盈。","作乐崇德，爰暢咸英。"]', '诗', 'shi', '', NULL, '郊廟歌辭 中宗祀昊天樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6cc0718-825c-47a3-a19d-a0b1bfbe1331', '郊廟歌辭 中宗祀昊天樂章 雍和', '郊廟歌辞 中宗祀昊天乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["郊壇展敬，嚴配因心。","孤竹簫管，空桑瑟琴。","肅穆大禮，鏗鏘八音。","恭惟上帝，希降靈歆。"]', '["郊壇展敬，嚴配因心。","孤竹簫管，空桑瑟琴。","肅穆大禮，鏗鏘八音。","恭惟上帝，希降靈歆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 中宗祀昊天樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28dc3d1b-25a2-4533-a001-db852a669fd3', '郊廟歌辭 中宗祀昊天樂章 福和', '郊廟歌辞 中宗祀昊天乐章 福和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["九成爰奏，三獻式陳。","欽承景福，恭託明禋。"]', '["九成爰奏，三獻式陳。","欽承景福，恭託明禋。"]', '诗', 'shi', '', NULL, '郊廟歌辭 中宗祀昊天樂章 福和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b14702e8-e102-450b-b1d3-af3ab5e77d5e', '郊廟歌辭 中宗祀昊天樂章 中宮助祭升壇', '郊廟歌辞 中宗祀昊天乐章 中宮助祭升壇', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["坤元光至德，柔訓闡皇風。","芣苡芳聲遠，螽斯美化隆。","睿範超千載，嘉猷備六宮。","肅恭陪盛典，欽若薦禋宗。"]', '["坤元光至德，柔訓闡皇风。","芣苡芳声远，螽斯美化隆。","睿範超千載，嘉猷備六宮。","肅恭陪盛典，欽若薦禋宗。"]', '诗', 'shi', '', NULL, '郊廟歌辭 中宗祀昊天樂章 中宮助祭升壇 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bb1431e-2471-49d5-a033-e474d1731d34', '郊廟歌辭 中宗祀昊天樂章 亞獻', '郊廟歌辞 中宗祀昊天乐章 亞獻', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三靈降饗，三后配神。","虔敷藻奠，敬展郊禋。"]', '["三靈降饗，三后配神。","虔敷藻奠，敬展郊禋。"]', '诗', 'shi', '', NULL, '郊廟歌辭 中宗祀昊天樂章 亞獻 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c19f1e4c-2b6f-44cf-8ee2-0993f3ef2cf7', '郊廟歌辭 中宗祀昊天樂章 舒和', '郊廟歌辞 中宗祀昊天乐章 舒和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["已陳粢盛敷嚴祀，更奏笙鏞協雅聲。","璇圖寶曆欣寧謐，晏俗淳風樂太平。"]', '["已陳粢盛敷嚴祀，更奏笙鏞協雅声。","璇圖寶曆欣寧謐，晏俗淳风乐太平。"]', '诗', 'shi', '', NULL, '郊廟歌辭 中宗祀昊天樂章 舒和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07b5a141-ac22-4ade-8e0e-3266a8154880', '郊廟歌辭 中宗祀昊天樂章 凱安', '郊廟歌辞 中宗祀昊天乐章 凱安', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["堂堂聖祖興，赫赫昌基泰。","戎車盟津偃，玉帛塗山會。","舜日啓祥暉，堯雲卷征斾。","風猷被有截，聲教覃無外。"]', '["堂堂聖祖兴，赫赫昌基泰。","戎车盟津偃，玉帛塗山會。","舜日啓祥暉，堯云卷征斾。","风猷被有截，声教覃無外。"]', '诗', 'shi', '', NULL, '郊廟歌辭 中宗祀昊天樂章 凱安 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70860658-4a7c-4f94-b2cc-80a5afe07c67', '郊廟歌辭 明皇祀圜丘樂章 豫和', '郊廟歌辞 明皇祀圜丘乐章 豫和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["至矣丕搆，烝哉太平。","授犧膺籙，復禹繼明。","草木仁化，鳧鷖頌聲。","祀宗陳德，無媿斯誠。"]', '["至矣丕搆，烝哉太平。","授犧膺籙，复禹繼明。","草木仁化，鳧鷖頌声。","祀宗陳德，無媿斯誠。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 豫和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0f686a7-7573-4a32-a6fe-cffd5febe323', '郊廟歌辭 明皇祀圜丘樂章 太和', '郊廟歌辞 明皇祀圜丘乐章 太和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["郊壇齋帝，禮樂祀天。","丹青寰宇，宮徵山川。","神祇畢降，行止重旋。","融融穆穆，納祉洪延。"]', '["郊壇斋帝，禮乐祀天。","丹青寰宇，宮徵山川。","神祇畢降，行止重旋。","融融穆穆，納祉洪延。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 太和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57fe80f8-d358-44eb-9b4f-7b9af4148431', '郊廟歌辭 明皇祀圜丘樂章 肅和', '郊廟歌辞 明皇祀圜丘乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["止奏潛聆，登儀宿囀。","太玉躬奉，參鍾首奠。","簠簋聿昇，犧牲遰薦。","昭事顒若，存存以俔。"]', '["止奏潛聆，登儀宿囀。","太玉躬奉，參鍾首奠。","簠簋聿昇，犧牲遰薦。","昭事顒若，存存以俔。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06ba9596-90d1-44ce-aa16-bc7ba88cdb84', '郊廟歌辭 明皇祀圜丘樂章 雍和', '郊廟歌辞 明皇祀圜丘乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["爛雲普洽，律風無外。","千品其凝，九賓斯會。","禋尊晉燭，純犧滌汰。","玄覆攸廣，鴻休汪濊。"]', '["爛云普洽，律风無外。","千品其凝，九賓斯會。","禋尊晉燭，純犧滌汰。","玄覆攸廣，鴻休汪濊。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb0f308-c254-4a99-9204-638f271b76cd', '郊廟歌辭 明皇祀圜丘樂章 壽和', '郊廟歌辞 明皇祀圜丘乐章 壽和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["六變爰闋，八階載虔。","祐我皇祚，於萬斯年。"]', '["六变爰闋，八階載虔。","祐我皇祚，於万斯年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 壽和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d375ceb0-0d16-47bc-949f-92117c1345b5', '郊廟歌辭 明皇祀圜丘樂章 壽和', '郊廟歌辞 明皇祀圜丘乐章 壽和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["於赫聖祖，龍飛晉陽。","底定萬國，奄有四方。","功格上下，道冠農黃。","郊天配享，德合無疆。"]', '["於赫聖祖，龙飞晉陽。","底定万国，奄有四方。","功格上下，道冠農黄。","郊天配享，德合無疆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 壽和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff8a176-d073-43b5-91e6-02d651771f36', '郊廟歌辭 明皇祀圜丘樂章 壽和', '郊廟歌辞 明皇祀圜丘乐章 壽和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["崇崇泰畤，肅肅嚴禋。","粢盛既潔，金石畢陳。","上帝來享，介福爰臻。","受釐合祉，寶祚維新。"]', '["崇崇泰畤，肅肅嚴禋。","粢盛既潔，金石畢陳。","上帝来享，介福爰臻。","受釐合祉，寶祚維新。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 壽和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b182e586-b9ce-4809-bc35-1674c35735fa', '郊廟歌辭 明皇祀圜丘樂章 舒和', '郊廟歌辞 明皇祀圜丘乐章 舒和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["祝史正辭，人神叶慶。","福以德招，享以誠應。","六變云備，百禮斯浹。","祀事孔明，祚流萬葉。"]', '["祝史正辞，人神叶慶。","福以德招，享以誠應。","六变云備，百禮斯浹。","祀事孔明，祚流万葉。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 舒和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888bef78-958e-43fc-bd06-3e0acac0016d', '郊廟歌辭 明皇祀圜丘樂章 凱安', '郊廟歌辞 明皇祀圜丘乐章 凱安', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["馨香惟后德，明命光天保。","肅和崇聖靈，陳信表皇道。","玉鏚初蹈厲，金匏既靜好。"]', '["馨香惟后德，明命光天保。","肅和崇聖靈，陳信表皇道。","玉鏚初蹈厲，金匏既静好。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 凱安 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caf25139-a8d2-4ba1-83e2-2fcfe60ff6a9', '郊廟歌辭 明皇祀圜丘樂章 豫和', '郊廟歌辞 明皇祀圜丘乐章 豫和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["大號成命，思文配天。","神光肸蠁，龍駕言旋。","眇眇閶闔，昭昭上玄。","俾昌而大，於斯萬年。"]', '["大號成命，思文配天。","神光肸蠁，龙駕言旋。","眇眇閶闔，昭昭上玄。","俾昌而大，於斯万年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 豫和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac3f210-c74e-403b-ae09-f1f955c0642c', '郊廟歌辭 明皇祀圜丘樂章 太和', '郊廟歌辞 明皇祀圜丘乐章 太和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["六成既闋，三薦云終。","神心具醉，聖敬愈崇。","受釐皇邸，回蹕帷宮。","穰穰之福，永永無窮。"]', '["六成既闋，三薦云終。","神心具醉，聖敬愈崇。","受釐皇邸，回蹕帷宮。","穰穰之福，永永無窮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明皇祀圜丘樂章 太和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80b9bf77-80cf-41a1-8278-5e5b37dd5b3b', '郊廟歌辭 封泰山樂章 豫和 一', '郊廟歌辞 封泰山乐章 豫和 一', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["款泰壇，柴泰清。","受天命，報天成。","竦皇心，薦樂聲。","志上達，歌下迎。"]', '["款泰壇，柴泰清。","受天命，報天成。","竦皇心，薦乐声。","志上達，歌下迎。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 豫和 一 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4902d495-3ed3-4aa2-9c67-36a054455042', '郊廟歌辭 封泰山樂章 豫和 二', '郊廟歌辞 封泰山乐章 豫和 二', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["億上帝，臨下庭。","騎日月，陪列星。","嘉祝信，大糦馨。","澹神心，醉皇靈。"]', '["億上帝，臨下庭。","騎日月，陪列星。","嘉祝信，大糦馨。","澹神心，醉皇靈。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 豫和 二 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dedab53e-3cb6-4689-a4e9-538a0aaeb005', '郊廟歌辭 封泰山樂章 豫和 三', '郊廟歌辞 封泰山乐章 豫和 三', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["相百辟，貢八荒。","九歌敍，萬舞翔。","肅振振，鏗皇皇。","帝欣欣，福穰穰。"]', '["相百辟，貢八荒。","九歌敍，万舞翔。","肅振振，鏗皇皇。","帝欣欣，福穰穰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 豫和 三 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd353d00-a484-4bb1-a4d7-e595fac0ea52', '郊廟歌辭 封泰山樂章 豫和 四', '郊廟歌辞 封泰山乐章 豫和 四', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["高在上，道光明。","物資始，德難名。","承眷命，牧蒼生。","寰宇謐，太階平。"]', '["高在上，道光明。","物資始，德难名。","承眷命，牧蒼生。","寰宇謐，太階平。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 豫和 四 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e1b1d18-0810-4f49-a7d3-8a6332a51183', '郊廟歌辭 封泰山樂章 豫和 五', '郊廟歌辞 封泰山乐章 豫和 五', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["天道無親，至誠與鄰。","山川遍禮，宮徵維新。","玉帛非盛，聰明會真。","正斯一德，通乎百神。"]', '["天道無親，至誠與鄰。","山川遍禮，宮徵維新。","玉帛非盛，聰明會真。","正斯一德，通乎百神。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 豫和 五 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e12fbf7-ae7c-4b70-83b4-d442fe1b23da', '郊廟歌辭 封泰山樂章 豫和 六', '郊廟歌辞 封泰山乐章 豫和 六', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["饗帝饗親，維孝維聖。","緝熙懿德，敷揚成命。","華夷志同，笙鏞禮盛。","明靈降止，感此誠敬。"]', '["饗帝饗親，維孝維聖。","緝熙懿德，敷揚成命。","华夷志同，笙鏞禮盛。","明靈降止，感此誠敬。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 豫和 六 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22c07619-9423-4f39-be66-e5380527651b', '郊廟歌辭 封泰山樂章 太和', '郊廟歌辞 封泰山乐章 太和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["孝敬中發，和容外彰。","騰華照宇，如昇太陽。","貞璧就奠，玄靈垂光。","禮樂具舉，濟濟洋洋。"]', '["孝敬中發，和容外彰。","腾华照宇，如昇太陽。","貞璧就奠，玄靈垂光。","禮乐具舉，濟濟洋洋。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 太和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6497789f-342b-4c89-b330-b32ee23cb12f', '郊廟歌辭 封泰山樂章 肅和', '郊廟歌辞 封泰山乐章 肅和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["奠祖配天，承天享帝。","百靈咸秩，四海來祭。","植我蒼璧，布我玄製。","華日裴回，神煙容裔。"]', '["奠祖配天，承天享帝。","百靈咸秩，四海来祭。","植我蒼璧，布我玄製。","华日裴回，神煙容裔。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 肅和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bd61d48-95a3-4505-a201-27a22d06f17a', '郊廟歌辭 封泰山樂章 雍和', '郊廟歌辞 封泰山乐章 雍和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["俎豆有馥，粢盛潔豐。","亦有和羹，既戒既平。","鐘鼓管磬，肅唱和鳴。","皇皇后祖，來我思成。"]', '["俎豆有馥，粢盛潔豐。","亦有和羹，既戒既平。","鐘鼓管磬，肅唱和鳴。","皇皇后祖，来我思成。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 雍和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a9c0b9d-b051-4f1b-b4b7-c6b70db36ea7', '郊廟歌辭 封泰山樂章 壽和', '郊廟歌辞 封泰山乐章 壽和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["烝烝我后，享獻惟夤。","躬酌鬱鬯，跪奠明神。","孝莫孝乎，配上帝親。","敬莫敬乎，教天下臣。"]', '["烝烝我后，享獻惟夤。","躬酌鬱鬯，跪奠明神。","孝莫孝乎，配上帝親。","敬莫敬乎，教天下臣。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 壽和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6cb3848-f434-458b-aebf-8fb321d13ca6', '郊廟歌辭 封泰山樂章 壽和', '郊廟歌辞 封泰山乐章 壽和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["皇祖嚴配，配享皇天。","皇皇降嘏，天子萬年。"]', '["皇祖嚴配，配享皇天。","皇皇降嘏，天子万年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 壽和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edf071ea-ed26-4840-8842-fab95743a231', '郊廟歌辭 封泰山樂章 舒和', '郊廟歌辞 封泰山乐章 舒和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["六鐘翕協六變成，八佾倘佯八風生。","樂九[韶]兮人神感，美七德兮天地清。"]', '["六鐘翕協六变成，八佾倘佯八风生。","乐九[韶]兮人神感，美七德兮天地清。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 舒和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7004472-180b-418e-97e3-b8f7bbd9ccf3', '郊廟歌辭 封泰山樂章 凱安', '郊廟歌辞 封泰山乐章 凱安', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["烈祖順三靈，文宗威四海。","黃鉞誅羣盜，朱旗掃多罪。","戢兵天下安，約法人心改。","大哉干羽意，長見風雲在。"]', '["烈祖順三靈，文宗威四海。","黄鉞誅羣盜，朱旗掃多罪。","戢兵天下安，約法人心改。","大哉干羽意，长见风云在。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 凱安 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fd38e52-42e1-4989-ac16-985e840e8a59', '郊廟歌辭 封泰山樂章 豫和', '郊廟歌辞 封泰山乐章 豫和', '627c6adb-d828-48b5-b606-edd7c97eaf8f', '唐', '["樂已終，[煙]燎上。","懷靈惠，結皇想。","歸風疾，迴風爽。","百[福]來，衆神往。"]', '["乐已終，[煙]燎上。","懷靈惠，結皇想。","归风疾，迴风爽。","百[福]来，衆神往。"]', '诗', 'shi', '', NULL, '郊廟歌辭 封泰山樂章 豫和 張說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c8f3016-80c9-4796-bba1-e21c9ac19b74', '郊廟歌辭 祈穀樂章 肅和', '郊廟歌辞 祈穀乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["履艮斯繩，居中體正。","龍運垂祉，昭符啓聖。","式事嚴禋，聿懷嘉慶。","惟帝永錫，時皇休命。"]', '["履艮斯繩，居中體正。","龙運垂祉，昭符啓聖。","式事嚴禋，聿懷嘉慶。","惟帝永錫，时皇休命。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祈穀樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a14c322-d2dd-4c09-8802-7bb5a46eb943', '郊廟歌辭 祈穀樂章 雍和', '郊廟歌辞 祈穀乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["殷薦乘春，太壇臨曙。","八簋盈和，六瑚登御。","嘉稷匪歆，德馨斯飫。","祝嘏無易，靈心有豫。"]', '["殷薦乘春，太壇臨曙。","八簋盈和，六瑚登御。","嘉稷匪歆，德馨斯飫。","祝嘏無易，靈心有豫。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祈穀樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62b23907-8858-489e-b206-0179d59f0397', '郊廟歌辭 祈穀樂章 舒和', '郊廟歌辞 祈穀乐章 舒和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["玉帛犧牲申敬享，金絲鏚羽盛音容。","庶俾億齡禔景福，長欣萬宇洽時邕。"]', '["玉帛犧牲申敬享，金絲鏚羽盛音容。","庶俾億齡禔景福，长欣万宇洽时邕。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祈穀樂章 舒和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b7a780-78ba-4e4c-acee-b185d8f6571f', '郊廟歌辭 明堂樂章 肅和', '郊廟歌辞 明堂乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["象天御宇，乘時布政。","嚴配申虔，宗禋展敬。","罇罍盈列，樹羽交映。","玉幣通誠，祚隆皇聖。"]', '["象天御宇，乘时布政。","嚴配申虔，宗禋展敬。","罇罍盈列，樹羽交映。","玉幣通誠，祚隆皇聖。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明堂樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68c594bf-742b-445f-8541-434e48be08cc', '郊廟歌辭 明堂樂章 雍和', '郊廟歌辞 明堂乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["八牖晨披，五精朝奠。","霧凝璇篚，風清金縣。","神滌備全，明粢豐衍。","載絜彝俎，陳誠以薦。"]', '["八牖晨披，五精朝奠。","霧凝璇篚，风清金縣。","神滌備全，明粢豐衍。","載絜彝俎，陳誠以薦。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明堂樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e67fd622-4eb7-4829-be03-e300a4147f52', '郊廟歌辭 明堂樂章 舒和', '郊廟歌辞 明堂乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["御扆合宮承寶曆，席圖重館奉明靈。","偃武修文九圍泰，沈烽靜柝八荒寧。"]', '["御扆合宮承寶曆，席圖重館奉明靈。","偃武修文九圍泰，沈烽静柝八荒寧。"]', '诗', 'shi', '', NULL, '郊廟歌辭 明堂樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8be1788-d45c-47b6-a04e-480b4337dfe1', '郊廟歌辭 武后明堂樂章 外辦將出', '郊廟歌辞 武后明堂乐章 外辦將出', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["總章陳昔典，衢室禮惟神。","宏規則天地，神用叶陶鈞。","負扆三春旦，充庭萬宇賓。","顧己誠虛薄，空慙億兆人。"]', '["總章陳昔典，衢室禮惟神。","宏規則天地，神用叶陶鈞。","負扆三春旦，充庭万宇賓。","顧己誠虛薄，空慙億兆人。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 外辦將出 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5880c05-dba3-4d43-984e-11173bd45c36', '郊廟歌辭 武后明堂樂章 皇帝行', '郊廟歌辞 武后明堂乐章 皇帝行', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["仰膺曆數，俯順謳歌。","遠安邇肅，俗阜時和。","化光玉鏡，訟息金科。","方興典禮，永戢干戈。"]', '["仰膺曆數，俯順謳歌。","远安邇肅，俗阜时和。","化光玉镜，訟息金科。","方兴典禮，永戢干戈。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 皇帝行 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9975b6c-83a5-4d7d-be29-ae59be144e35', '郊廟歌辭 武后明堂樂章 皇嗣出入升降', '郊廟歌辞 武后明堂乐章 皇嗣出入升降', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["至人光俗，大孝通神。","謙以表性，恭惟立身。","洪規載啓，茂典方陳。","譽隆三善，祥開萬春。"]', '["至人光俗，大孝通神。","謙以表性，恭惟立身。","洪規載啓，茂典方陳。","譽隆三善，祥开万春。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 皇嗣出入升降 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feefaf2e-ee95-45c2-8ccb-6344d12750c4', '郊廟歌辭 武后明堂樂章 迎送王公', '郊廟歌辞 武后明堂乐章 迎送王公', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["千官肅事，萬國朝宗。","載延百辟，爰集三宮。","君臣德合，魚水斯同。","睿圖方永，周曆長隆。"]', '["千官肅事，万国朝宗。","載延百辟，爰集三宮。","君臣德合，鱼水斯同。","睿圖方永，周曆长隆。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 迎送王公 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8292b6b3-4cc1-413d-94ec-618799752ba7', '郊廟歌辭 武后明堂樂章 登歌', '郊廟歌辞 武后明堂乐章 登歌', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["禮崇宗祀，志表嚴禋。","笙鏞合奏，文物維新。","敬遵茂典，敢擇良辰。","絜誠斯著，奠謁方申。"]', '["禮崇宗祀，志表嚴禋。","笙鏞合奏，文物維新。","敬遵茂典，敢擇良辰。","絜誠斯著，奠謁方申。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 登歌 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c36d775d-bffa-4bf7-bbeb-fa0e6889a6f5', '郊廟歌辭 武后明堂樂章 配饗', '郊廟歌辞 武后明堂乐章 配饗', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["笙鏞間玉宇，文物昭清暉。","睟影臨芳奠，休光下太微。","孝思期有感，明絜庶無違。"]', '["笙鏞间玉宇，文物昭清暉。","睟影臨芳奠，休光下太微。","孝思期有感，明絜庶無違。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 配饗 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a71c4e67-69d8-48ce-96f9-3cec8d90fbc8', '郊廟歌辭 武后明堂樂章 宮音', '郊廟歌辞 武后明堂乐章 宮音', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["履艮包羣望，居中冠百靈。","萬方資廣運，庶品荷財成。","神功諒匪測，盛德實難名。","藻奠申誠敬，恭祀表惟馨。"]', '["履艮包羣望，居中冠百靈。","万方資廣運，庶品荷財成。","神功諒匪測，盛德實难名。","藻奠申誠敬，恭祀表惟馨。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 宮音 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cdb7f42-2482-475b-b8b9-2eb80480d922', '郊廟歌辭 武后明堂樂章 角音', '郊廟歌辞 武后明堂乐章 角音', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["出震位，開平秩。","扇條風，乘甲乙。","龍德盛，鳥星出。","薦珪篚，陳誠實。"]', '["出震位，开平秩。","扇條风，乘甲乙。","龙德盛，鸟星出。","薦珪篚，陳誠實。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 角音 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0cebd35-37bb-4506-8bf3-6da60bff17c4', '郊廟歌辭 武后明堂樂章 徵音', '郊廟歌辞 武后明堂乐章 徵音', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["赫赫離精御炎陸，滔滔熾景開隆暑。","冀延神鑒俯蘭罇，式表虔襟陳桂俎。"]', '["赫赫離精御炎陸，滔滔熾景开隆暑。","冀延神鑒俯蘭罇，式表虔襟陳桂俎。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 徵音 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a821d9f2-e0d2-4cae-b4c4-a4b98ff6eebc', '郊廟歌辭 武后明堂樂章 商音', '郊廟歌辞 武后明堂乐章 商音', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["律中夷則，序應收成。","功宣建武，義表惟明。","爰申禮奠，庶展翹誠。","九秋是式，百穀斯盈。"]', '["律中夷則，序應收成。","功宣建武，義表惟明。","爰申禮奠，庶展翹誠。","九秋是式，百穀斯盈。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 商音 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8348c6df-d5c2-46c1-9f5d-4b9ad210a033', '郊廟歌辭 武后明堂樂章 羽音', '郊廟歌辞 武后明堂乐章 羽音', '41078f43-3397-4c9a-bcab-09744260e078', '唐', '["葭律肇啓隆冬，蘋藻攸陳饗祭。","黃鍾既陳玉燭，紅粒方殷稔歲。"]', '["葭律肇啓隆冬，蘋藻攸陳饗祭。","黄鍾既陳玉燭，紅粒方殷稔歲。"]', '诗', 'shi', '', NULL, '郊廟歌辭 武后明堂樂章 羽音 武則天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d28776f-732f-41d4-bef1-52195b731076', '郊廟歌辭 雩祀樂章 肅和', '郊廟歌辞 雩祀乐章 肅和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["朱鳥開辰，蒼龍啓映。","大帝昭饗，羣生展敬。","禮備懷柔，功宣舞詠。","旬液應序，年祥協慶。"]', '["朱鸟开辰，蒼龙啓映。","大帝昭饗，羣生展敬。","禮備懷柔，功宣舞詠。","旬液應序，年祥協慶。"]', '诗', 'shi', '', NULL, '郊廟歌辭 雩祀樂章 肅和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e0a7c5c-190a-4793-8c50-83b71e364ad0', '郊廟歌辭 雩祀樂章 雍和', '郊廟歌辞 雩祀乐章 雍和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["紺筵分彩，珤圖吐絢。","風管晨凝，雲歌曉囀。","肅事蘭羞，虔申桂奠。","百穀斯登，萬箱攸薦。"]', '["紺筵分彩，珤圖吐絢。","风管晨凝，云歌晓囀。","肅事蘭羞，虔申桂奠。","百穀斯登，万箱攸薦。"]', '诗', 'shi', '', NULL, '郊廟歌辭 雩祀樂章 雍和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26bff9a0-801b-4f40-b3ef-2567d01373b0', '郊廟歌辭 雩祀樂章 舒和', '郊廟歌辞 雩祀乐章 舒和', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["鳳曲登歌調令序，龍雩集舞汎祥風。","綵旞雲迴昭睿德，朱干電發表神功。"]', '["鳳曲登歌調令序，龙雩集舞汎祥风。","綵旞云迴昭睿德，朱干電發表神功。"]', '诗', 'shi', '', NULL, '郊廟歌辭 雩祀樂章 舒和 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6d6aed8-06a1-48c8-b0b8-d964e1b899ca', '郊廟歌辭 雩祀樂章 豫和', '郊廟歌辞 雩祀乐章 豫和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鳥緯遷序，龍星見辰。","純陽在律，明德崇禋。","五方降帝，萬宇安人。","恭以致享，肅以迎神。"]', '["鸟緯遷序，龙星见辰。","純陽在律，明德崇禋。","五方降帝，万宇安人。","恭以致享，肅以迎神。"]', '诗', 'shi', '', NULL, '郊廟歌辭 雩祀樂章 豫和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f63a093f-1f9e-460d-92d4-3de2e2027233', '郊廟歌辭 雩祀樂章 豫和', '郊廟歌辞 雩祀乐章 豫和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["祀遵經設，享緣誠舉。","獻畢于樽，徹臨于俎。","舞止干戚，樂停柷敔。","歌以送神，神還其所。"]', '["祀遵經設，享緣誠舉。","獻畢于樽，徹臨于俎。","舞止干戚，乐停柷敔。","歌以送神，神還其所。"]', '诗', 'shi', '', NULL, '郊廟歌辭 雩祀樂章 豫和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1bc8482-e830-4ca2-bc88-ee8e88901090', '郊廟歌辭 五郊樂章 黃帝宮音', '郊廟歌辞 五郊乐章 黄帝宮音', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["黃中正位，含章居貞。","既長六律，兼和五聲。","畢陳萬舞，乃薦斯牲。","神其下降，永祚休平。"]', '["黄中正位，含章居貞。","既长六律，兼和五声。","畢陳万舞，乃薦斯牲。","神其下降，永祚休平。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 黃帝宮音 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e9c629-6367-4dc1-a5fc-e2a45d02e122', '郊廟歌辭 五郊樂章 黃帝宮音 肅和', '郊廟歌辞 五郊乐章 黄帝宮音 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["眇眇方輿，蒼蒼圜蓋。","至哉樞紐，宅中圖大。","氣調四序，風和萬籟。","祚我明德，時雍道泰。"]', '["眇眇方輿，蒼蒼圜蓋。","至哉樞紐，宅中圖大。","氣調四序，风和万籟。","祚我明德，时雍道泰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 黃帝宮音 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bc0a751-ff42-4312-8fa5-73171a67f3f5', '郊廟歌辭 五郊樂章 黃帝宮音 雍和', '郊廟歌辞 五郊乐章 黄帝宮音 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["金縣夕肆，玉俎朝陳。","饗薦黃道，芬流紫宸。","迺誠迺敬，載享載禋。","崇薦斯在，惟皇是賓。"]', '["金縣夕肆，玉俎朝陳。","饗薦黄道，芬流紫宸。","迺誠迺敬，載享載禋。","崇薦斯在，惟皇是賓。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 黃帝宮音 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a12c6ba-c4d8-4b41-9b67-b6c3be170ac4', '郊廟歌辭 五郊樂章 黃帝宮音 舒和', '郊廟歌辞 五郊乐章 黄帝宮音 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["御徵乘宮出郊甸，安歌率舞遞將迎。","自有雲門符帝賞，猶持雷鼓答天成。"]', '["御徵乘宮出郊甸，安歌率舞遞將迎。","自有云门符帝賞，猶持雷鼓答天成。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 黃帝宮音 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f133c999-dbed-4ab0-be7a-3b109e38f748', '郊廟歌辭 五郊樂章 青帝角音', '郊廟歌辞 五郊乐章 青帝角音', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["鶴雲旦起，鳥星昏集。","律候新風，陽開初蟄。","至德可饗，行潦斯挹。","錫以無疆，蒸人乃粒。"]', '["鹤云旦起，鸟星昏集。","律候新风，陽开初蟄。","至德可饗，行潦斯挹。","錫以無疆，蒸人乃粒。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 青帝角音 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3401b39-e0a0-4e57-a546-329f01238f50', '郊廟歌辭 五郊樂章 青帝角音 肅和', '郊廟歌辞 五郊乐章 青帝角音 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["玄鳥司春，蒼龍登歲。","節物變柳，光風轉蕙。","瑤席降神，朱弦饗帝。","誠備祝嘏，禮殫珪幣。"]', '["玄鸟司春，蒼龙登歲。","節物变柳，光风轉蕙。","瑤席降神，朱弦饗帝。","誠備祝嘏，禮殫珪幣。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 青帝角音 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f4bc315-4e28-43cc-aee2-71f15fc25436', '郊廟歌辭 五郊樂章 青帝角音 雍和', '郊廟歌辞 五郊乐章 青帝角音 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["大樂稀音，至誠簡禮。","文物棣棣，聲明濟濟。","六變有成，三登無體。","乃眷豐潔，恩覃愷悌。"]', '["大乐稀音，至誠簡禮。","文物棣棣，声明濟濟。","六变有成，三登無體。","乃眷豐潔，恩覃愷悌。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 青帝角音 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da5d4724-adca-4fa3-a364-6a7e79157a9a', '郊廟歌辭 五郊樂章 青帝角音 舒和', '郊廟歌辞 五郊乐章 青帝角音 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["笙歌籥舞屬年韶，鷺鼓鳧鐘展時豫。","調露初迎綺春節，承雲遽踐蒼霄馭。"]', '["笙歌籥舞屬年韶，鷺鼓鳧鐘展时豫。","調露初迎綺春節，承云遽踐蒼霄馭。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 青帝角音 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17fef454-d5fd-45a0-97d8-318fb7d4bcce', '郊廟歌辭 五郊樂章 赤帝徵音', '郊廟歌辞 五郊乐章 赤帝徵音', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["青陽告謝，朱明戒序。","延長是祈，敬陳椒醑。","博碩斯薦，笙鏞備舉。","庶盡肅恭，非馨稷黍。"]', '["青陽告謝，朱明戒序。","延长是祈，敬陳椒醑。","博碩斯薦，笙鏞備舉。","庶尽肅恭，非馨稷黍。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 赤帝徵音 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0ed62dc-9f4f-4f83-8ad0-0a57f3a2bf42', '郊廟歌辭 五郊樂章 赤帝徵音 肅和', '郊廟歌辞 五郊乐章 赤帝徵音 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["離位克明，火中宵見。","峰雲暮起，景風晨扇。","木槿初榮，含桃可薦。","芬馥百品，鏗鏘三變。"]', '["離位克明，火中宵见。","峰云暮起，景风晨扇。","木槿初榮，含桃可薦。","芬馥百品，鏗鏘三变。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 赤帝徵音 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a004ee68-bde3-4cad-a948-e8e74177cf31', '郊廟歌辭 五郊樂章 赤帝徵音 雍和', '郊廟歌辞 五郊乐章 赤帝徵音 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["昭昭丹陸，奕奕炎方。","禮陳牲幣，樂備篪簧。","瓊羞溢俎，玉醑浮觴。","恭惟正直，歆此馨香。"]', '["昭昭丹陸，奕奕炎方。","禮陳牲幣，乐備篪簧。","瓊羞溢俎，玉醑浮觴。","恭惟正直，歆此馨香。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 赤帝徵音 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('692f9d4e-0aea-47fe-a79b-1f3abeca49dd', '郊廟歌辭 五郊樂章 赤帝徵音 舒和', '郊廟歌辞 五郊乐章 赤帝徵音 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["千里溫風飄絳羽，十枝炎景賸朱干。","陳觴薦俎歌二獻，拊石摐金會七盤。"]', '["千里溫风飄絳羽，十枝炎景賸朱干。","陳觴薦俎歌二獻，拊石摐金會七盤。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 赤帝徵音 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eccb120b-354d-4048-a6a5-2a208e4b65a9', '郊廟歌辭 五郊樂章 白帝商音', '郊廟歌辞 五郊乐章 白帝商音', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["白藏應節，天高氣清。","歲功既阜，庶類收成。","萬方靜謐，九土和平。","馨香是薦，受祚聰明。"]', '["白藏應節，天高氣清。","歲功既阜，庶類收成。","万方静謐，九土和平。","馨香是薦，受祚聰明。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 白帝商音 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7a52713-a446-463f-9bd5-11c1fe2f7298', '郊廟歌辭 五郊樂章 白帝商音 肅和', '郊廟歌辞 五郊乐章 白帝商音 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["金行在節，素靈居正。","氣肅霜嚴，林彫草勁。","豺祭隼擊，潦收川鏡。","九穀已登，萬箱流詠。"]', '["金行在節，素靈居正。","氣肅霜嚴，林彫草勁。","豺祭隼擊，潦收川镜。","九穀已登，万箱流詠。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 白帝商音 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a55e18f-5023-4ded-ba7d-dc33f374e02e', '郊廟歌辭 五郊樂章 白帝商音 雍和', '郊廟歌辞 五郊乐章 白帝商音 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["律應西成，氣躔南呂。","珪幣咸列，笙竽備舉。","苾苾蘭羞，芬芬桂醑。","式資宴貺，用調霜序。"]', '["律應西成，氣躔南呂。","珪幣咸列，笙竽備舉。","苾苾蘭羞，芬芬桂醑。","式資宴貺，用調霜序。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 白帝商音 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e215855-e254-4e2b-8c3c-3f1f9610195e', '郊廟歌辭 五郊樂章 白帝商音 舒和', '郊廟歌辞 五郊乐章 白帝商音 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["璿儀氣爽驚緹籥，玉呂灰飛含素商。","鳴鞞奏管芳羞薦，會舞安歌葆眊揚。"]', '["璿儀氣爽驚緹籥，玉呂灰飞含素商。","鳴鞞奏管芳羞薦，會舞安歌葆眊揚。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 白帝商音 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('484621fd-eb0e-4699-a17c-a7b8944752b9', '郊廟歌辭 五郊樂章 黑帝羽音', '郊廟歌辞 五郊乐章 黑帝羽音', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["嚴冬季月，星迴風厲。","享祀報功，方祚來歲。"]', '["嚴冬季月，星迴风厲。","享祀報功，方祚来歲。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 黑帝羽音 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5da3266-8c45-4240-880d-148c9cd80acc', '郊廟歌辭 五郊樂章 黑帝羽音 肅和', '郊廟歌辞 五郊乐章 黑帝羽音 肅和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["律回玉琯，星周金度。","次極陽烏，紀窮陰兔。","火林霰雪，陽泉凝冱。","八蜡已登，三農息務。"]', '["律回玉琯，星周金度。","次極陽烏，紀窮陰兔。","火林霰雪，陽泉凝冱。","八蜡已登，三農息務。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 黑帝羽音 肅和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db05caa8-e760-4912-9bd2-d17b2764abe8', '郊廟歌辭 五郊樂章 黑帝羽音 雍和', '郊廟歌辞 五郊乐章 黑帝羽音 雍和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["陽月斯紀，應鍾在候。","載潔牲牷，爰登俎豆。","既高既遠，無聲無臭。","靜言格思，惟神保祐。"]', '["陽月斯紀，應鍾在候。","載潔牲牷，爰登俎豆。","既高既远，無声無臭。","静言格思，惟神保祐。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 黑帝羽音 雍和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df8bcf92-b106-4f25-8291-28bfa9a742a0', '郊廟歌辭 五郊樂章 黑帝羽音 舒和', '郊廟歌辞 五郊乐章 黑帝羽音 舒和', '4fd3b250-514a-445c-bbec-fa637b357834', '唐', '["執籥持羽初終曲，朱干玉鏚始分行。","七德九功咸已暢，明靈降福具穰穰。"]', '["執籥持羽初終曲，朱干玉鏚始分行。","七德九功咸已暢，明靈降福具穰穰。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 黑帝羽音 舒和 魏徵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d26460e4-8862-41a7-a757-7854ba81df18', '郊廟歌辭 五郊樂章 黃郊迎神', '郊廟歌辞 五郊乐章 黄郊迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["朱明季序，黃郊王辰。","厚以載物，甘以養人。","毓金爲體，稟火成身。","宮音式奏，奏以迎神。"]', '["朱明季序，黄郊王辰。","厚以載物，甘以養人。","毓金爲體，稟火成身。","宮音式奏，奏以迎神。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 黃郊迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd434d7-67ab-4501-8aac-e4a5e8b12dd2', '郊廟歌辭 五郊樂章 送神', '郊廟歌辞 五郊乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["春末冬暮，徂夏杪秋。","土王四月，時季一周。","黍稷已享，籩豆宜收。","送神有樂，神其賜休。"]', '["春末冬暮，徂夏杪秋。","土王四月，时季一周。","黍稷已享，籩豆宜收。","送神有乐，神其賜休。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd068ad5-f70a-41f7-a86d-5c0d996a8399', '郊廟歌辭 五郊樂章 青郊迎神', '郊廟歌辞 五郊乐章 青郊迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["緹幕移候，青郊啓蟄。","淑景遲遲，和風習習。","璧玉宵備，旌旄曙立。","張樂以迎，帝神其入。"]', '["緹幕移候，青郊啓蟄。","淑景遲遲，和风習習。","璧玉宵備，旌旄曙立。","張乐以迎，帝神其入。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 青郊迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de487473-c634-4314-9fda-e5e945a0a5ed', '郊廟歌辭 五郊樂章 送神', '郊廟歌辞 五郊乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["文物流彩，聲明動色。","人竭其恭，靈昭其飭。","歆薦不已，垂禎無極。","送禮有章，惟神還軾。"]', '["文物流彩，声明动色。","人竭其恭，靈昭其飭。","歆薦不已，垂禎無極。","送禮有章，惟神還軾。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7249156-73d3-4b95-b933-3459e0a25e81', '郊廟歌辭 五郊樂章 赤郊迎神', '郊廟歌辞 五郊乐章 赤郊迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["青陽節謝，朱明候改。","靡草彫華，含桃流彩。","虡列鐘磬，筵陳脯醢。","樂以迎神，神其如在。"]', '["青陽節謝，朱明候改。","靡草彫华，含桃流彩。","虡列鐘磬，筵陳脯醢。","乐以迎神，神其如在。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 赤郊迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef97a37d-c849-407d-b894-0d5df341d0ea', '郊廟歌辭 五郊樂章 送神', '郊廟歌辞 五郊乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["炎精式降，蒼生攸仰。","羞列豆籩，酒陳犧象。","昭祀有應，冥期不爽。","送樂張音，惟靈之往。"]', '["炎精式降，蒼生攸仰。","羞列豆籩，酒陳犧象。","昭祀有應，冥期不爽。","送乐張音，惟靈之往。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('460e1cd1-cc6c-494e-a20f-5197be96f3d7', '郊廟歌辭 五郊樂章 白郊迎神', '郊廟歌辞 五郊乐章 白郊迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["序移玉律，節應金商。","天嚴殺氣，吹警秋方。","槱燎既積，稷奠並芳。","樂以迎奏，庶降神光。"]', '["序移玉律，節應金商。","天嚴殺氣，吹警秋方。","槱燎既積，稷奠並芳。","乐以迎奏，庶降神光。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 白郊迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1de9de27-5232-4680-98d6-3e30c7966dcc', '郊廟歌辭 五郊樂章 送神', '郊廟歌辞 五郊乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["祀遵五禮，時屬三秋。","人懷肅敬，靈降禎休。","奠歆旨酒，薦享珍羞。","載張送樂，神其上遊。"]', '["祀遵五禮，时屬三秋。","人懷肅敬，靈降禎休。","奠歆旨酒，薦享珍羞。","載張送乐，神其上游。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67965bb4-4aa6-4bbd-969a-a032f1ddf24d', '郊廟歌辭 五郊樂章 黑郊迎神', '郊廟歌辞 五郊乐章 黑郊迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["玄英戒序，黑郊臨候。","掌禮陳彝，司筵執豆。","寒氛斂色，沍泉凝漏。","樂以迎神，八音斯奏。"]', '["玄英戒序，黑郊臨候。","掌禮陳彝，司筵執豆。","寒氛斂色，沍泉凝漏。","乐以迎神，八音斯奏。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 黑郊迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de1e351b-f879-43c8-9eea-a3f31c6372d0', '郊廟歌辭 五郊樂章 送神', '郊廟歌辞 五郊乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["北郊時冽，南陸輝處。","奠本虔誠，獻彌恭慮。","上延祉福，下承歡豫。","廣樂送神，神其整馭。"]', '["北郊时冽，南陸輝处。","奠本虔誠，獻彌恭慮。","上延祉福，下承歡豫。","廣乐送神，神其整馭。"]', '诗', 'shi', '', NULL, '郊廟歌辭 五郊樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce27f085-cc00-44d2-8bdd-2732050b6f44', '郊廟歌辭 朝日樂章 肅和', '郊廟歌辞 朝日乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["惟聖格天，惟明饗日。","帝郊肆類，王宮戒吉。","珪奠春舒，鐘歌曉溢。","禮云克備，斯文有秩。"]', '["惟聖格天，惟明饗日。","帝郊肆類，王宮戒吉。","珪奠春舒，鐘歌晓溢。","禮云克備，斯文有秩。"]', '诗', 'shi', '', NULL, '郊廟歌辭 朝日樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f47e595-f010-4776-a3d9-10ea28aebdcd', '郊廟歌辭 朝日樂章 雍和', '郊廟歌辞 朝日乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["晨儀式薦，明祀惟光。","神物爰止，靈暉載揚。","玄端肅事，紫幄興祥。","福履攸假，於昭允王。"]', '["晨儀式薦，明祀惟光。","神物爰止，靈暉載揚。","玄端肅事，紫幄兴祥。","福履攸假，於昭允王。"]', '诗', 'shi', '', NULL, '郊廟歌辭 朝日樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6db72031-e135-4ad6-a385-1c7ab06cd6db', '郊廟歌辭 朝日樂章 舒和', '郊廟歌辞 朝日乐章 舒和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["崇牙樹羽延調露，旋宮扣律掩承雲。","誕敷懿德昭神武，載集豐功表睿文。"]', '["崇牙樹羽延調露，旋宮扣律掩承云。","誕敷懿德昭神武，載集豐功表睿文。"]', '诗', 'shi', '', NULL, '郊廟歌辭 朝日樂章 舒和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c46d0f11-ff9a-402e-9306-cf79f7449187', '郊廟歌辭 朝日樂章 迎神', '郊廟歌辞 朝日乐章 迎神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["太陽朝序，王宮有儀。","蟠桃彩駕，細柳光馳。","軒祥表合，漢曆彰奇。","禮和樂備，神其降斯。"]', '["太陽朝序，王宮有儀。","蟠桃彩駕，細柳光驰。","軒祥表合，漢曆彰奇。","禮和乐備，神其降斯。"]', '诗', 'shi', '', NULL, '郊廟歌辭 朝日樂章 迎神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63eda8cd-8f40-4759-8fd6-7a3596f30a01', '郊廟歌辭 朝日樂章 送神', '郊廟歌辞 朝日乐章 送神', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["五齊兼酌，百羞具陳。","樂終廣奏，禮畢崇禋。","明鑑萬宇，照臨兆人。","永流洪慶，式動曦輪。"]', '["五齊兼酌，百羞具陳。","乐終廣奏，禮畢崇禋。","明鑑万宇，照臨兆人。","永流洪慶，式动曦輪。"]', '诗', 'shi', '', NULL, '郊廟歌辭 朝日樂章 送神 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('289d4243-4767-4538-acff-d018f3e7dd95', '郊廟歌辭 夕月樂章 肅和', '郊廟歌辞 夕月乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["測妙爲神，通微曰聖。","坎祀貽則，郊禋展敬。","璧薦登光，金歌動映。","以載嘉德，以流曾慶。"]', '["測妙爲神，通微曰聖。","坎祀貽則，郊禋展敬。","璧薦登光，金歌动映。","以載嘉德，以流曾慶。"]', '诗', 'shi', '', NULL, '郊廟歌辭 夕月樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f2bcb45-880b-4d5d-abae-57b90be48df8', '郊廟歌辭 夕月樂章 雍和', '郊廟歌辞 夕月乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["朏晨爭舉，天宗禮闢。","夜典涼秋，陰明湛夕。","有𨣧斯旨，有牲斯碩。","穆穆其暉，穰穰是積。"]', '["朏晨爭舉，天宗禮闢。","夜典涼秋，陰明湛夕。","有𨣧斯旨，有牲斯碩。","穆穆其暉，穰穰是積。"]', '诗', 'shi', '', NULL, '郊廟歌辭 夕月樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23fbd6da-fe7d-4df9-b81b-2e32ab64c239', '郊廟歌辭 夕月樂章 舒和', '郊廟歌辞 夕月乐章 舒和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["合吹八風金奏動，分容萬舞玉鞘驚。","詞昭茂典光前列，夕曜乘功表盛明。"]', '["合吹八风金奏动，分容万舞玉鞘驚。","词昭茂典光前列，夕曜乘功表盛明。"]', '诗', 'shi', '', NULL, '郊廟歌辭 夕月樂章 舒和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6925b93e-60a1-47f4-aad6-121caddd115d', '郊廟歌辭 祀九宮貴神樂章 豫和 一', '郊廟歌辞 祀九宮貴神乐章 豫和 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["於昭上穹，臨下有光。","羽翼五佐，周流八荒。","誰其饗之，時文對敭。","虞經夏典，茲禮未遑。"]', '["於昭上穹，臨下有光。","羽翼五佐，周流八荒。","誰其饗之，时文对敭。","虞經夏典，茲禮未遑。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 豫和 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74ad9d08-4bcb-4844-b9bf-897afeaeb5ad', '郊廟歌辭 祀九宮貴神樂章 豫和 二', '郊廟歌辞 祀九宮貴神乐章 豫和 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["黑帝旋馭，青躔導日。","金籙上玄，玉堂初吉。","鉤陳夕次，鑾和先蹕。","藹藹羣靈，昭昭咸秩。"]', '["黑帝旋馭，青躔導日。","金籙上玄，玉堂初吉。","鉤陳夕次，鑾和先蹕。","藹藹羣靈，昭昭咸秩。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 豫和 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c3567ec-56b5-4ca3-be4a-0be999fa4cfa', '郊廟歌辭 祀九宮貴神樂章 豫和 三', '郊廟歌辞 祀九宮貴神乐章 豫和 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["帝臨中壇，受釐元神。","皇靈萃止，羽旄肅陳。","攝提運衡，招搖移輪。","光光宇宙，電耀雷震。"]', '["帝臨中壇，受釐元神。","皇靈萃止，羽旄肅陳。","攝提運衡，招搖移輪。","光光宇宙，電耀雷震。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 豫和 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a859f0e3-355f-4385-bde8-1c793381a587', '郊廟歌辭 祀九宮貴神樂章 豫和 四', '郊廟歌辞 祀九宮貴神乐章 豫和 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["夜如何其，明星煌煌。","天清容衛，露結壇場。","樹羽幢幢，佩玉鏘鏘。","凝精駐目，瞻望神光。"]', '["夜如何其，明星煌煌。","天清容衛，露結壇場。","樹羽幢幢，佩玉鏘鏘。","凝精駐目，瞻望神光。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 豫和 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44c39cce-e882-45bc-bc05-8ab1f8c0baf7', '郊廟歌辭 祀九宮貴神樂章 豫和 五', '郊廟歌辞 祀九宮貴神乐章 豫和 五', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["九位既肅，萬靈畢會。","天門啓扄，日馭飛蓋。","煥兮棽離，儐兮暗靄。","如山之福，惟聖時對。"]', '["九位既肅，万靈畢會。","天门啓扄，日馭飞蓋。","煥兮棽離，儐兮暗靄。","如山之福，惟聖时对。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 豫和 五 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73235558-2399-4730-b8d9-d7dafb45ac29', '郊廟歌辭 祀九宮貴神樂章 豫和 六', '郊廟歌辞 祀九宮貴神乐章 豫和 六', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["崇崇泰壇，靈具臨兮。","鏗鍠大樂，振動心兮。","神之降矣，卿雲郁兮。","神之至止，清風肅兮。"]', '["崇崇泰壇，靈具臨兮。","鏗鍠大乐，振动心兮。","神之降矣，卿云郁兮。","神之至止，清风肅兮。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 豫和 六 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ead7ead-cc7f-410c-8767-d2b8083079fe', '郊廟歌辭 祀九宮貴神樂章 太和', '郊廟歌辞 祀九宮貴神乐章 太和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["帝在靈壇，大明登光。","天回雲粹，穆穆皇皇。","金奏九夏，圭陳八薌。","曠哉動植，如熙春陽。"]', '["帝在靈壇，大明登光。","天回云粹，穆穆皇皇。","金奏九夏，圭陳八薌。","曠哉动植，如熙春陽。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 太和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46ff4fd-f74e-4df3-81dd-5268b6ca2507', '郊廟歌辭 祀九宮貴神樂章 肅和', '郊廟歌辞 祀九宮貴神乐章 肅和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["歌工既奏，神位既秩。","天符衆星，運行太一。","聲和十管，氣應中律。","肅肅明廷，介茲元吉。"]', '["歌工既奏，神位既秩。","天符衆星，運行太一。","声和十管，氣應中律。","肅肅明廷，介茲元吉。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 肅和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca30b92d-722c-42dc-89fd-f9a3316d3b9d', '郊廟歌辭 祀九宮貴神樂章 雍和', '郊廟歌辞 祀九宮貴神乐章 雍和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["俎豆有踐，黃流在尊。","九宮之祀，三代莫存。","樂變六宮，壇開八門。","聖皇昭對，祐我黎元。"]', '["俎豆有踐，黄流在尊。","九宮之祀，三代莫存。","乐变六宮，壇开八门。","聖皇昭对，祐我黎元。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 雍和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9e99408-1966-4113-a6c0-10216d7de918', '郊廟歌辭 祀九宮貴神樂章 壽和', '郊廟歌辞 祀九宮貴神乐章 壽和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["時文哲后，肅事嚴禋。","馨我明德，享於貴神。","大庖載盈，旨酒斯醇。","精意所屬，期於利人。"]', '["时文哲后，肅事嚴禋。","馨我明德，享於貴神。","大庖載盈，旨酒斯醇。","精意所屬，期於利人。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 壽和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75ae8f5c-a3a8-4a62-9ad4-a0260250aa1f', '郊廟歌辭 祀九宮貴神樂章 福和', '郊廟歌辞 祀九宮貴神乐章 福和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["祀既云畢，明靈告旋。","禮洽和應，神歆福延。","動植咸若，陰陽不愆。","錫茲純嘏，天子萬年。"]', '["祀既云畢，明靈告旋。","禮洽和應，神歆福延。","动植咸若，陰陽不愆。","錫茲純嘏，天子万年。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 福和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7cca728-ddd3-41a8-b38b-a29a3bfd6ab9', '郊廟歌辭 祀九宮貴神樂章 舒和', '郊廟歌辞 祀九宮貴神乐章 舒和', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["羽籥既闋干戚陳，八音克諧六變新。","愉貴神兮般以樂，保皇祚兮萬斯春。"]', '["羽籥既闋干戚陳，八音克諧六变新。","愉貴神兮般以乐，保皇祚兮万斯春。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 舒和 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e02abcc5-bc03-4306-b0ab-f5f049104c9c', '郊廟歌辭 祀九宮貴神樂章 凱安', '郊廟歌辞 祀九宮貴神乐章 凱安', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["盛德陳萬舞，威稜暢九垓。","風雲交律候，日月麗昭回。","行慶休祥發，乘和春氣來。","百神肅臨享，蕩蕩天門開。"]', '["盛德陳万舞，威稜暢九垓。","风云交律候，日月丽昭回。","行慶休祥發，乘和春氣来。","百神肅臨享，蕩蕩天门开。"]', '诗', 'shi', '', NULL, '郊廟歌辭 祀九宮貴神樂章 凱安 不詳 shi');
